(function(g){g.__QURAN_DATA=g.__QURAN_DATA||{};g.__QURAN_DATA["tamil-059"]={"sura":59,"name_ar":"الحشر","name_en":"Al-Hashr","verses":24,"source":"https://www.tamililquran.com/tafsiribnkathir.php","count":24,"missing":[],"data":{"1":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=59&ayah=5\" class=\"link\">59:5</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 59:5 ஐ பார்க்கவும்"},"2":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=59&ayah=5\" class=\"link\">59:5</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 59:5 ஐ பார்க்கவும்"},"3":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=59&ayah=5\" class=\"link\">59:5</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 59:5 ஐ பார்க்கவும்"},"4":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=59&ayah=5\" class=\"link\">59:5</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 59:5 ஐ பார்க்கவும்"},"5":{"html":"<strong>இது மதீனாவில் அருளப்பட்டது</strong><br />\r\n<br />\r\nஇப்னு அப்பாஸ் (ரழி) அவர்கள் இந்த அத்தியாயத்தை 'ஸூரா பனூ நளீர்' என்று அழைப்பார்கள். ஸயீத் பின் மன்சூர் அவர்கள் பதிவு செய்துள்ளதாவது: ஸயீத் பின் ஜுபைர் அவர்கள் கூறினார்கள், \"நான் இப்னு அப்பாஸ் (ரழி) அவர்களிடம் ஸூரத்துல் ஹஷ்ரைப் பற்றிக் கேட்டேன். அதற்கு அவர்கள், 'அது பனூ நளீர் (கோத்திரத்தாரைப்) பற்றி அருளப்பட்டது' என்று கூறினார்கள்.\" புகாரி மற்றும் முஸ்லிம் ஆகியோரும் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து மற்றொரு அறிவிப்பாளர் தொடர் வழியாக இதனைப் பதிவு செய்துள்ளனர். புகாரி அவர்களும் அபூ அவானாவிலிருந்து, அவர் அபூ பிஷ்ரிடமிருந்தும், அவர் ஸயீத் பின் ஜுபைரிடமிருந்தும் பதிவு செய்துள்ளனர். அவர் கூறினார்: \"நான் இப்னு அப்பாஸ் (ரழி) அவர்களிடம் 'ஸூரத்துல் ஹஷ்ர்' பற்றிக் கேட்டேன். அதற்கு அவர்கள், 'ஸூரா பனூ நளீர்' என்று பதிலளித்தார்கள்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span><br />\r\n<br />\r\nஅளவற்ற அருளாளனும் நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் திருப்பெயரால்.<br />\r\n<br />\r\n<strong>அனைத்தும் அல்லாஹ்வை அதனதன் வழியில் துதிக்கின்றன</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سَبَّحَ</span> <span class=\"quran-arabic-font text-success\">لِلَّهِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الْعَزِيزُ</span> <span class=\"quran-arabic-font text-success\">الْحَكِيمُ</span><br />\r\n<br />\r\nவானங்களிலும் பூமியிலும் உள்ள அனைத்தும் அல்லாஹ்வைப் புகழ்ந்து, போற்றி, அவனது ஏகத்துவத்தை உறுதிப்படுத்தி, அவனிடம் பிரார்த்தனை செய்கின்றன என்று அல்லாஹ் கூறுகிறான். அல்லாஹ் மற்றொரு வசனத்தில் (ஆயத்தில்) கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">تُسَبِّحُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتُ</span> <span class=\"quran-arabic-font text-success\">السَّبْعُ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضُ</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">فِيهِنَّ</span> <span class=\"quran-arabic-font text-success\">وَإِنْ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">يُسَبِّحُ</span> <span class=\"quran-arabic-font text-success\">بِحَمْدِهِ</span> <span class=\"quran-arabic-font text-success\">وَلَكِنْ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تَفْقَهُونَ</span> <span class=\"quran-arabic-font text-success\">تَسْبِيحَهُمْ</span><br />\r\n<br />\r\n(ஏழு வானங்களும், பூமியும், அவற்றில் உள்ளவையும் அவனைத் துதிக்கின்றன. அவனது புகழைக் கொண்டு துதிக்காத பொருள் எதுவுமே இல்லை. எனினும், அவை துதிப்பதை நீங்கள் புரிந்து கொள்ள மாட்டீர்கள்.) (<a href=\"qurandisp.php?sura=17&ayah=44\" class=\"link\">17:44</a>) அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الْعَزِيزُ</span><br />\r\n<br />\r\n(மேலும், அவன் மிகைத்தவன்) அதாவது, வெல்ல முடியாத வல்லமை கொண்டவன்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الْحَكِيمُ</span><br />\r\n<br />\r\n(ஞானமிக்கவன்) தான் விதிக்கும் சட்டங்களிலும் தீர்மானங்களிலும் ஞானமுள்ளவன்.<br />\r\n<br />\r\n<strong>பனூ நளீர் கோத்திரத்தார் சந்தித்த இறுதி முடிவு</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">أَخْرَجَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُوا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">الْكِتَابِ</span><br />\r\n<br />\r\n(வேதக்காரர்களில் நிராகரித்தவர்களை அவன்தான் வெளியேற்றினான்). இப்னு அப்பாஸ் (ரழி), முஜாஹித், அஸ்-ஸுஹ்ரி மற்றும் பலரது கூற்றுப்படி இது 'பனூ நளீர்' என்ற யூத கோத்திரத்தைக் குறிக்கிறது. அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மதீனாவிற்கு ஹிஜ்ரத் (புலம்பெயர்தல்) செய்தபோது, யூதர்களுடன் ஒரு சமாதான உடன்படிக்கையை மேற்கொண்டார்கள். அதன்படி, நபிகள் நாயகம் (ஸல்) அவர்களும் அவர்களும் போரிட மாட்டார்கள் (என்று முடிவானது). ஆனால், அவர்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுடன் செய்துகொண்ட அந்த உடன்படிக்கைக்கு விரைவில் துரோகம் இழைத்தனர். எனவே, அல்லாஹ் அவர்கள் மீது தடுத்து நிறுத்த முடியாத தனது வேதனையை இறக்கினான்; அவனது விதி அவர்களைச் சூழ்ந்தது. முஸ்லிம்கள் தங்களால் கைப்பற்ற முடியாது என்று கருதிய அவர்களின் பலமான கோட்டைகளை விட்டு வெளியேறுமாறு நபிகள் நாயகம் (ஸல்) அவர்கள் அவர்களைக் கட்டாயப்படுத்தினார்கள். தங்கள் கோட்டைகள் தங்களை அல்லாஹ்வின் வேதனையிலிருந்து பாதுகாக்கும் என்று யூதர்கள் நினைத்தனர்; ஆனால் அவை அல்லாஹ்வுக்கு எதிராக அவர்களுக்குச் சிறிதும் உதவவில்லை. பின்னர், அவர்கள் எதிர்பாராத விதமாக அல்லாஹ்விடமிருந்து (தண்டனை) வந்தது. அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவர்களை மதீனாவிலிருந்து வெளியேற்றினார்கள். அவர்களில் சிலர் ஷாம் பகுதியிலுள்ள 'அத்ரிஆத்' என்ற இடத்திற்குச் சென்றனர். இதுவே மக்கள் ஒன்றுதிரட்டப்படும் (மஹ்ஷர்) மற்றும் உயிர்த்தெழுப்பப்படும் இடமாகும். மற்றவர்கள் கைபருக்குச் சென்றனர். அவர்கள் தங்கள் ஒட்டகங்கள் சுமக்கக்கூடிய பொருட்களை மட்டும் எடுத்துச் செல்ல நபிகள் நாயகம் (ஸல்) அவர்கள் அனுமதித்தார்கள். எடுத்துச் செல்ல முடியாத சொத்துக்களை அவர்களே அழித்தனர். இதனால்தான், கண்ணியத்திற்குரிய அல்லாஹ் இவ்வாறு கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يُخْرِبُونَ</span> <span class=\"quran-arabic-font text-success\">بُيُوتَهُمْ</span> <span class=\"quran-arabic-font text-success\">بِأَيْدِيهِمْ</span> <span class=\"quran-arabic-font text-success\">وَأَيْدِي</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">فَاعْتَبِرُوا</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">أُولِي</span> <span class=\"quran-arabic-font text-success\">الْأَبْصَارِ</span><br />\r\n<br />\r\n(அவர்கள் தங்கள் வீடுகளைத் தங்கள் கைகளாலும், முஃமின்களின் (இறைநம்பிக்கையாளர்களின்) கைகளாலும் அழித்துக் கொண்டனர். ஆகவே, அகப்பார்வை உடையவர்களே! இதிலிருந்து படிப்பினை பெறுங்கள்.) அதாவது, \"அல்லாஹ்வின் கட்டளையை மீறி, அவனது தூதரை எதிர்த்து, அவனது வேதத்தைப் பொய்பித்தவர்களின் முடிவைச் சிந்தித்துப் பாருங்கள். இவ்வுலகில் அல்லாஹ் அவர்களை எவ்வாறு இழிவுபடுத்தினான் என்பதையும், மறுமையில் அவர்களுக்காக அவன் வைத்துள்ள துன்பகரமான வேதனையையும் பாருங்கள்.\" அபுதாவூத் அவர்கள், அப்துர்ரஹ்மான் பின் கஅப் பின் மாலிக் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: நபிகள் நாயகம் (ஸல்) அவர்களின் தோழர்களில் ஒருவர் கூறினார், \"குறைஷி இணைவைப்பாளர்கள், அப்துல்லாஹ் பின் உபை மற்றும் அவ்ஸ், கஸ்ரஜ் கோத்திரங்களில் இன்னும் சிலைகளை வணங்கிக் கொண்டிருந்தவர்களுக்கும் கடிதம் எழுதினார்கள். அந்த நேரத்தில், பத்ருப் போருக்கு முன்னதாக, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மதீனாவில் இருந்தார்கள். அவர்கள் அந்த கடிதத்தில்: 'நீங்கள் எங்கள் ஆளுக்கு (முஹம்மதுக்கு) அடைக்கலம் கொடுத்துள்ளீர்கள். அல்லாஹ்வின் மீது ஆணையாக, நீங்கள் அவருடன் போரிட வேண்டும்; இல்லையெனில் நாங்கள் உங்களை வெளியேற்றுவோம் அல்லது எங்களது படைகளைத் திரட்டி வந்து, உங்கள் வீரர்களைக் கொன்று உங்கள் பெண்களைச் சிறைபிடிப்போம்' என்று எழுதியிருந்தனர். இந்த அச்சுறுத்தல் செய்தி அப்துல்லாஹ் பின் உபை மற்றும் அவ்ஸ், கஸ்ரஜ் கோத்திரத்து இணைவைப்பாளர்களை அடைந்ததும், அவர்கள் நபிகள் நாயகம் (ஸல்) அவர்களுடன் போரிடத் தயாரானார்கள். இந்தச் செய்தி நபிகள் நாயகம் (ஸல்) அவர்களுக்கு எட்டியதும், அவர்கள் அவர்களிடம் சென்று கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَقَدْ</span> <span class=\"quran-arabic-font text-success\">بَلَغَ</span> <span class=\"quran-arabic-font text-success\">وَعِيدُ</span> <span class=\"quran-arabic-font text-success\">قُرَيْشٍ</span> <span class=\"quran-arabic-font text-success\">مِنْكُمُ</span> <span class=\"quran-arabic-font text-success\">الْمَبَالِغَ،</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">كَانَتْ</span> <span class=\"quran-arabic-font text-success\">تَكِيدُكُمْ</span> <span class=\"quran-arabic-font text-success\">بِأَكْثَرَ</span> <span class=\"quran-arabic-font text-success\">مِمَّا</span> <span class=\"quran-arabic-font text-success\">تُرِيدُ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تَكِيدُوا</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">أَنْفُسَكُمْ،</span> <span class=\"quran-arabic-font text-success\">تُرِيدُونَ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">تُقَاتِلُوا</span> <span class=\"quran-arabic-font text-success\">أَبْنَاءَكُمْ</span> <span class=\"quran-arabic-font text-success\">وَإِخْوَانَكُم</span>»<br />\r\n<br />\r\n(குறைஷிகளின் அச்சுறுத்தல் உங்களை மிகுந்த கவலைக்குள்ளாக்கியுள்ளது! உங்கள் செயல்களால் நீங்களே உங்களுக்கு ஏற்படுத்திக் கொள்ளும் தீங்கை விட அதிகத் தீங்கை குறைஷிகளால் உங்களுக்கு ஏற்படுத்த முடியாது. நீங்கள் உங்கள் பிள்ளைகளுடனும் சகோதரர்களுடனும் போரிட விரும்புகிறீர்களா?) நபிகள் நாயகம் (ஸல்) அவர்களிடமிருந்து இந்த வார்த்தைகளைக் கேட்டதும் அவர்கள் கலைந்து சென்றனர். நடந்த செய்தி குறைஷி இணைவைப்பாளர்களை அடைந்தது. பத்ருப் போருக்குப் பிறகு, குறைஷி இணைவைப்பாளர்கள் மதீனாவிலிருந்த யூதர்களுக்கு, 'உங்களிடம் கவசங்களும் கோட்டைகளும் உள்ளன! நீங்கள் எமது ஆளுடன் போரிட வேண்டும், இல்லையெனில் நாங்கள் உங்களுக்கு இன்னின்ன தண்டனைகளைத் தருவோம்; உங்கள் பெண்களைக் கைப்பற்றுவதிலிருந்து எங்களை எதுவும் தடுக்க முடியாது' என்று கடிதம் எழுதினார்கள். இந்தக் கடிதத்தின் செய்தியும் நபிகள் நாயகம் (ஸல்) அவர்களுக்கு எட்டியது. பனூ நளீர் கோத்திரத்தினர் உடன்படிக்கையை மீறி துரோகம் செய்யத் திட்டமிட்டனர். பனூ நளீர் கோத்திரத்தினர், நபிகள் நாயகம் (ஸல்) அவர்களை முப்பது தோழர்களுடன் வந்து, இரு தரப்பிற்கும் இடைப்பட்ட ஒரு பகுதியில் தங்கள் முப்பது ரபிக்களை (யூத மத அறிஞர்களை) சந்திக்குமாறு செய்தி அனுப்பினார்கள். அந்த ரபிக்கள் நபிகள் நாயகம் (ஸல்) அவர்கள் கூறுவதைக் கேட்பார்கள் என்றும், அவர்கள் அவரை நம்பினால், பனூ நளீர் மக்கள் அனைவரும் அவரை நம்புவார்கள் என்றும் கூறினார்கள். ஆனால், அவர்கள் அல்லாஹ்வின் தூதரைக் (ஸல்) கொலை செய்யவே திட்டமிட்டனர். அவர்கள் தீங்கு இழைக்கும் முன்பே அல்லாஹ் இந்தச் சதியைப் பற்றித் தனது தூதருக்குத் (ஸல்) தெரிவித்தான். மறுநாள் நபிகள் நாயகம் (ஸல்) அவர்கள் தனது படைகளைத் திரட்டி அவர்களின் பகுதியை முற்றுகையிட்டு, அவர்களிடம் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">وَاللهِ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تَأْمَنُونَ</span> <span class=\"quran-arabic-font text-success\">عِنْدِي</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">بِعَهْدٍ</span> <span class=\"quran-arabic-font text-success\">تُعَاهِدُونَنِي</span> <span class=\"quran-arabic-font text-success\">عَلَيْه</span>»<br />\r\n<br />\r\n(அல்லாஹ்வின் மீது ஆணையாக! நீங்கள் என்னுடன் உங்கள் சமாதான உடன்படிக்கையைப் புதுப்பிக்கும் வரை, நீங்கள் என்னிடம் பாதுகாப்பாக இருக்க முடியாது.) அவர்கள் அதற்கு மறுப்பு தெரிவித்தனர். அன்றைய தினத்தின் எஞ்சிய பகுதியில் நபிகள் நாயகம் (ஸல்) அவர்கள் அவர்களுடன் போரிட்டார்கள். அடுத்த நாள் காலையில், நபிகள் நாயகம் (ஸல்) அவர்கள் பனூ குறைழா கோத்திரத்தை முற்றுகையிட்டு, அன்றைய தினம் பனூ நளீர் கோத்திரத்தினரைத் தனியாக விட்டுவிட்டார்கள். பனூ குறைழா கோத்திரத்தாரை ஒரு புதிய சமாதான உடன்படிக்கையில் கையெழுத்திடுமாறு நபிகள் நாயகம் (ஸல்) அவர்கள் கட்டளையிட்டார்கள்; அவர்களும் அதனை ஏற்றுக்கொண்டார்கள். பின்னர் நபிகள் நாயகம் (ஸல்) அவர்கள் பனூ குறைழாவை விட்டுவிட்டு, மீண்டும் பனூ நளீர் கோத்திரத்தாரிடம் சென்று, அவர்கள் மதீனாவிலிருந்து பாதுகாப்பாக வெளியேறுவதற்குப் பதிலாக சரணடைய ஒப்புக்கொள்ளும் வரை அவர்களுடன் போரிட்டார்கள். பனூ நளீர் கோத்திரத்தினர் மதீனாவிலிருந்து வெளியேறினர். அவர்கள் தங்கள் வீட்டுச் சாமான்கள் மற்றும் கதவுகள், மரக்கட்டைகள் உட்படத் தங்கள் ஒட்டகங்கள் சுமக்கக்கூடிய அனைத்தையும் எடுத்துச் சென்றனர். பனூ நளீர் கோத்திரத்தாரின் பேரீச்சைத் தோட்டங்களை அல்லாஹ் தனது தூதருக்கு (ஸல்) வழங்கினான். அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">أَفَاءَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">رَسُولِهِ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">فَمَا</span> <span class=\"quran-arabic-font text-success\">أَوْجَفْتُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">خَيْلٍ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">رِكَابٍ</span><br />\r\n<br />\r\n(அவர்களிடமிருந்து அல்லாஹ் தன் தூதருக்குப் போர்ச் செல்வமாக எதைக் கொடுத்தானோ, அதற்காக நீங்கள் குதிரைகளையோ ஒட்டகங்களையோ ஓட்டிச் செல்லவில்லை.) அதாவது, நீங்கள் சண்டையின்றிப் பெற்ற செல்வமாகும். நபிகள் நாயகம் (ஸல்) அவர்கள் அந்தத் தோட்டங்களின் பெரும்பகுதியை முஹாஜிர்களுக்குப் பங்கிட்டுக் கொடுத்தார்கள். அன்சாரிகளில் ஏழைகளாக இருந்த இருவருக்கு மட்டுமே அதில் பங்கு கொடுத்தார்கள். அவர்களைத் தவிர அன்சாரிகளில் வேறு யாருக்கும் அதில் அவர்கள் பங்கு வழங்கவில்லை. நபிகள் நாயகம் (ஸல்) அவர்கள் போர்ச் செல்வத்தில் ஒரு பகுதியைத் தமக்காக வைத்துக் கொண்டார்கள். நபிகள் நாயகம் (ஸல்) அவர்களின் அந்த தர்மத்தின் பகுதி, பின்னர் அவர்களின் மகளின் பிள்ளைகள், அதாவது பாத்திமா (ரழி) அவர்களின் பிள்ளைகளின் நிர்வாகத்திற்கு மாற்றப்பட்டது. எவ்வாறாயினும், பனூ நளீர் போரின் சுருக்கம் இதுவே. அல்லாஹ் ஒருவனிடமே நாம் உதவியைத் தேடுகிறோம்.<br />\r\n<br />\r\n<strong>பனூ நளீர் போர் ஏற்படுவதற்கான காரணம்</strong><br />\r\n<br />\r\nபிஃரு மஊனா என்ற இடத்தில் குர்ஆனைக் கற்பிப்பதற்காக நபிகள் நாயகம் (ஸல்) அவர்களால் அனுப்பப்பட்ட எழுபது தோழர்கள் கொல்லப்பட்டனர். அம்ர் பின் உமய்யா அழ்-ளம்ரீ (ரழி) அவர்கள் மட்டும் தப்பினார். அவர் மதீனாவிற்குத் திரும்பும் வழியில் பனூ ஆமிர் கோத்திரத்தைச் சேர்ந்த இருவரைக் கொன்றார். அந்த இருவருக்கும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பாதுகாப்பு அளித்திருந்தது அவருக்குத் தெரியாது. அவர் மதீனாவிற்குத் திரும்பி வந்து நடந்ததை நபிகள் நாயகம் (ஸல்) அவர்களிடம் கூறியபோது, நபிகள் நாயகம் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَقَدْ</span> <span class=\"quran-arabic-font text-success\">قَتَلْتَ</span> <span class=\"quran-arabic-font text-success\">رَجُلَيْنِ</span> <span class=\"quran-arabic-font text-success\">لَأَدِيَنَّهُمَا</span>»<br />\r\n<br />\r\n(நீர் இருவரைக் கொன்றுவிட்டீர், அவர்களுக்காக நான் இரத்தப்பழித் தொகை (தியா) செலுத்துவேன்.) பனூ நளீர் மற்றும் பனூ ஆமிர் கோத்திரத்தினர் ஒருவருக்கொருவர் கூட்டாளிகளாகவும் உடன்படிக்கை செய்தவர்களாகவும் இருந்தனர். எனவே, அந்த இருவருக்கான இரத்தப்பழித் தொகையைச் செலுத்த உதவுமாறு நபிகள் நாயகம் (ஸல்) அவர்கள் பனூ நளீர் கோத்திரத்தாரிடம் கேட்டார்கள். பனூ நளீர் கோத்திரத்தாரின் பகுதி மதீனாவின் புறநகரில் கிழக்கே சில மைல் தொலைவில் இருந்தது. முஹம்மது பின் இஸ்ஹாக் பின் யஸார் அவர்கள் தனது ஸீரா நூலில் கூறுகிறார்: \"பின்னர் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அம்ர் பின் உமய்யா அழ்-ளம்ரீயால் கொல்லப்பட்ட பனூ ஆமிர் கோத்திரத்தைச் சேர்ந்த இருவருக்கான இரத்தப்பழித் தொகையைச் செலுத்த உதவி கேட்க பனூ நளீர் கோத்திரத்தாரிடம் சென்றார்கள். யஸீத் பின் ரூமான் அவர்களின் கூற்றுப்படி, அவர்களுக்கு நபிகள் நாயகம் (ஸல்) அவர்களின் பாதுகாப்பு வாக்குறுதி இருந்தது. பனூ நளீர் மற்றும் பனூ ஆமிர் கோத்திரத்தாருக்குள் உடன்படிக்கை இருந்தது. அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் உதவி கேட்டு அவர்களிடம் சென்றபோது, 'நிச்சயமாக, ஓ அபுல் காஸிம்! நீங்கள் உதவி கேட்டதால் நாங்கள் உங்களுக்கு உதவுகிறோம்' என்றனர். ஆனால், அவர்கள் தங்களுக்குள் இரகசியமாகப் பேசிக் கொண்டபோது, 'இந்த மனிதரை (கொல்ல) இதைவிடச் சிறந்த வாய்ப்பு உங்களுக்குக் கிடைக்காது' என்று கூறினர். அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவர்களின் ஒரு வீட்டின் சுவருக்கு அருகில் அமர்ந்திருந்தார்கள். 'யார் இந்தச் சுவரில் ஏறி, இவர் மீது ஒரு கல்லைப் போட்டு இவரது தொல்லையிலிருந்து நம்மை விடுவிப்பார்?' என்று கேட்டனர். அம்ர் பின் ஜிஹாஷ் பின் கஅப் என்பவர் முன்வந்து, நபிகள் நாயகம் (ஸல்) அவர்கள் மீது கல்லை எறிய வீட்டின் சுவரில் ஏறினார். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அபூபக்ர் (ரழி), உமர் (ரழி) மற்றும் அலீ (ரழி) போன்ற சில தோழர்களுடன் அமர்ந்திருந்தார்கள். இந்தச் சதி பற்றிய வஹீ (இறைச்செய்தி) வானத்திலிருந்து நபிகள் நாயகம் (ஸல்) அவர்களுக்குத் தெரிவிக்கப்பட்டது. உடனே அவர்கள் எழுந்து மதீனாவிற்குத் திரும்பிச் சென்றார்கள். நபிகள் நாயகம் (ஸல்) அவர்களை நீண்ட நேரமாகக் காணாததால், தோழர்கள் அவர்களைத் தேடிச் சென்றனர். மதீனாவிலிருந்து ஒரு மனிதர் வருவதைக் கண்டு அவரிடம் கேட்டனர். அவர் நபிகள் நாயகம் (ஸல்) அவர்கள் மதீனாவிற்குள் நுழைவதைக் கண்டதாகக் கூறினார். தோழர்கள் நபிகள் நாயகம் (ஸல்) அவர்களிடம் சென்றபோது, யூதர்கள் தமக்கு எதிராகத் தீட்டிய துரோகச் சதியைப் பற்றி அவர்கள் தோழர்களிடம் கூறினார்கள். மேலும் போருக்குத் தயாராகும்படியும், பனூ நளீர் கோத்திரத்தாரை நோக்கிப் புறப்படும்படியும் கட்டளையிட்டார்கள். நபிகள் நாயகம் (ஸல்) அவர்கள் தனது படைகளைத் திரட்டி பனூ நளீர் பகுதிக்குச் சென்றார்கள். அவர்கள் தங்கள் பலமான கோட்டைகளில் தஞ்சம் புகுந்தனர். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவர்களின் பேரீச்சை மரங்களை வெட்டி எரிக்க உத்தரவிட்டார்கள். இதைக் கண்டு யூதர்கள், 'முஹம்மதே! பூமியில் குழப்பம் விளைவிப்பதைத் தடுத்து வந்த நீங்கள், இப்போது ஏன் பேரீச்சை மரங்களை வெட்டி எரிக்க உத்தரவிடுகிறீர்கள்?' என்று கூச்சலிட்டனர். இதற்கிடையில், அப்துல்லாஹ் பின் உபை பின் சலூல் மற்றும் பனூ அவ்ஃப் பின் கஸ்ரஜ் கோத்திரத்தைச் சேர்ந்த சிலர் பனூ நளீர் கோத்திரத்தாருக்கு ஒரு செய்தியை அனுப்பினார்கள்: 'உறுதியாக இருங்கள். நாங்கள் உங்களைக் கைவிட மாட்டோம். உங்களுக்கு எதிராகப் போர் நடந்தால் நாங்களும் உங்களுடன் சேர்ந்து போரிடுவோம். நீங்கள் வெளியேற்றப்பட்டால் நாங்களும் உங்களுடன் வருவோம்.' யூதர்கள் இந்த ஆதரவை நம்பிக் காத்திருந்தனர், ஆனால் நயவஞ்சகர்கள் வாக்குறுதியை நிறைவேற்றவில்லை. அல்லாஹ் யூதர்களின் உள்ளங்களில் திகிலை உண்டாக்கினான். அவர்கள் மதீனாவிலிருந்து பாதுகாப்பாக வெளியேறவும், உயிருக்கு உத்தரவாதம் அளிக்கவும் நபிகள் நாயகம் (ஸல்) அவர்களிடம் கோரிக்கை விடுத்தனர். அதற்குப் பதிலாக, ஆயுதங்களைத் தவிர, தங்கள் ஒட்டகங்கள் சுமக்கக்கூடிய பொருட்களை மட்டும் எடுத்துச் செல்ல அனுமதி கேட்டனர். நபிகள் நாயகம் (ஸல்) அவர்கள் அதற்குச் சம்மதித்தார்கள். யூதர்கள் தங்களால் இயன்ற அனைத்துச் செல்வங்களையும் சேகரித்தனர். ஒரு யூதர் தனது வீட்டு வாசலை எடுத்துச் செல்வதற்காக, அதன் சுவரையே இடித்தார். பனூ நளீர் கோத்திரத்தினர் கைபருக்கும், சில பேர் ஷாம் தேசத்திற்கும் சென்றனர். அவர்கள் விட்டுச் சென்ற மீதமுள்ள சொத்துக்கள் அனைத்தும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் கட்டுப்பாட்டிற்கு வந்தன. நபிகள் நாயகம் (ஸல்) அவர்கள் அதனை முஹாஜிர்களுக்குப் பங்கிட்டுக் கொடுத்தார்கள். அன்சாரிகளில் சஹ்ல் பின் ஹுனைஃப் (ரழி) மற்றும் அபூ துஜானா (ரழி) ஆகிய இரு ஏழைத் தோழர்களுக்கு மட்டும் பங்கு கொடுத்தார்கள். பனூ நளீர் கோத்திரத்தைச் சேர்ந்த யாமீன் பின் உமைர் மற்றும் அபூ ஸஅத் பின் வஹ்ப் ஆகிய இருவர் மட்டுமே இஸ்லாத்தை ஏற்றனர். அவர்கள் இஸ்லாத்தைத் தழுவியதால் தங்கள் செல்வத்தைப் பாதுகாத்துக் கொண்டனர்.\" இப்னு இஸ்ஹாக் தொடர்கிறார்: \"யாமீனின் சந்ததியினர் என்னிடம் கூறியது: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் யாமீனிடம், 'உமது சகோதரன் எனக்கு எதிராகச் செய்த சதியைக் குறித்து நீர் அறிந்தீரா?' என்று கேட்டார்கள். யாமீன் பின் உமைர் (ரழி) அவர்கள் தனது சகோதரன் அம்ர் பின் ஜிஹாஷைக் கொல்பவருக்கு வெகுமதி அளிப்பதாகக் கூறினார்; அதன்படி ஒருவர் அவனைக் கொன்றார்.\" இப்னு இஸ்ஹாக் மேலும் கூறினார்: \"ஸூரத்துல் ஹஷ்ர் முழுவதுமே பனூ நளீர் கோத்திரத்தாரைப் பற்றியே அருளப்பட்டது.\"<br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">أَخْرَجَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُوا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">الْكِتَابِ</span><br />\r\n<br />\r\n(வேதக்காரர்களில் நிராகரித்தவர்களை அவன்தான் வெளியேற்றினான்) இது பனூ நளீர் கோத்திரத்தாரைக் குறிக்கிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">دِيَارِهِمْ</span> <span class=\"quran-arabic-font text-success\">لِأَوَّلِ</span> <span class=\"quran-arabic-font text-success\">الْحَشْرِ</span><br />\r\n<br />\r\n(அவர்களின் வீடுகளிலிருந்து முதல் ஒன்று கூடலுக்காக.) அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">ظَنَنتُمْ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَخْرُجُواْ</span><br />\r\n<br />\r\n(அவர்கள் வெளியேறுவார்கள் என்று நீங்கள் நினைக்கவில்லை.) அதாவது, நீங்கள் அவர்களைச் சில நாட்களே முற்றுகையிட்டிருந்த நிலையில் அவர்கள் வெளியேறுவார்கள் என்று நீங்கள் கருதவில்லை. தோழர்கள் ஆறு நாட்கள் மட்டுமே முற்றுகையிட்டிருந்தனர். அவர்களின் கோட்டைகளோ மிகவும் பலமானவை. இதனால்தான் அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَظَنُّوا</span> <span class=\"quran-arabic-font text-success\">أَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">مَانِعَتُهُمْ</span> <span class=\"quran-arabic-font text-success\">حُصُونُهُمْ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">فَأَتَاهُمُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">حَيْثُ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَحْتَسِبُوا</span><br />\r\n<br />\r\n(மேலும் அவர்கள் தங்கள் கோட்டைகள் தங்களை அல்லாஹ்விடமிருந்து பாதுகாக்கும் என்று நினைத்தார்கள்! ஆனால் அல்லாஹ் அவர்கள் எதிர்பாராத விதத்தில் அவர்களிடம் வந்தான்.) அதாவது, அவர்கள் சற்றும் எதிர்பாராத தண்டனை அல்லாஹ்விடமிருந்து வந்தது. அல்லாஹ் மற்றொரு வசனத்தில் (ஆயத்தில்) கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">مَكَرَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">قَبْلِهِمْ</span> <span class=\"quran-arabic-font text-success\">فَأَتَى</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">بُنْيَانَهُمْ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْقَوَاعِدِ</span> <span class=\"quran-arabic-font text-success\">فَخَرَّ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمُ</span> <span class=\"quran-arabic-font text-success\">السَّقْفُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">فَوْقِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَأَتَاهُمُ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">حَيْثُ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَشْعُرُونَ</span><br />\r\n<br />\r\n(அவர்களுக்கு முன்னிருந்தவர்களும் இவ்வாறே சதி செய்தனர். ஆனால் அல்லாஹ் அவர்களின் கட்டிடங்களின் அஸ்திவாரங்களையே தகர்த்தான். ஆகவே, கூரை அவர்கள் மீது மேலிருந்து விழுந்தது. அவர்கள் உணராத திசையிலிருந்து வேதனை அவர்களை வந்தடைந்தது.) (<a href=\"qurandisp.php?sura=16&ayah=26\" class=\"link\">16:26</a>)<br />\r\n<br />\r\nஅல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَذَفَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">قُلُوبِهِمُ</span> <span class=\"quran-arabic-font text-success\">الرُّعْبَ</span><br />\r\n<br />\r\n(மேலும் அவன் அவர்களின் உள்ளங்களில் திகிலை ஏற்படுத்தினான்.) அதாவது அல்லாஹ் அவர்களின் உள்ளங்களில் அச்சத்தையும் பீதியையும் உண்டாக்கினான். ஒரு மாத காலப் பயண தூரத்திலுள்ள எதிரிகளையும் அச்சுறுத்துவதன் மூலம் எவருக்கு வெற்றி வழங்கப்பட்டதோ, அவரே அவர்களை முற்றுகையிட்டிருக்கும்போது அவர்களுக்கு அச்சம் ஏற்படாமல் இருக்குமா? நபிகள் நாயகம் (ஸல்) அவர்கள் மீது அல்லாஹ்வின் சாந்தியும் சமாதானமும் உண்டாவதாக. இப்னு இஸ்ஹாக்கின் விளக்கத்தில் நாம் ஏற்கனவே பார்த்தபடி:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يُخْرِبُونَ</span> <span class=\"quran-arabic-font text-success\">بُيُوتَهُمْ</span> <span class=\"quran-arabic-font text-success\">بِأَيْدِيهِمْ</span> <span class=\"quran-arabic-font text-success\">وَأَيْدِي</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span><br />\r\n<br />\r\n(அவர்கள் தங்கள் வீடுகளைத் தங்கள் கைகளாலும், முஃமின்களின் கைகளாலும் அழித்துக் கொண்டனர்.) யூதர்கள் தாங்கள் எடுத்துச் செல்ல விரும்பிய கூரைகளையும் கதவுகளையும் ஒட்டகங்களில் சுமந்து செல்வதற்காகத் தாங்களே அவற்றைப் பிரித்து அழித்தனர். இவ்வாறே உர்வா பின் அஸ்-ஸுபைர் (ரழி), அப்துர்ரஹ்மான் பின் ஸைத் பின் அஸ்லம் மற்றும் பலர் கூறியுள்ளனர்.<br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْلاَ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">كَتَبَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمُ</span> <span class=\"quran-arabic-font text-success\">الْجَلاَءَ</span> <span class=\"quran-arabic-font text-success\">لَعَذَّبَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span><br />\r\n<br />\r\n(மேலும் அல்லாஹ் அவர்கள் மீது நாடு கடத்தலை விதித்திருக்காவிட்டால், அவன் நிச்சயமாக அவர்களை இவ்வுலகிலேயே தண்டித்திருப்பான்.) அதாவது, அவர்கள் மதீனாவை விட்டு வெளியேற வேண்டும் என்று அல்லாஹ் ஏற்கனவே விதித்திருக்காவிட்டால், அவர்களைக் கொலை செய்தல் அல்லது சிறைப்பிடித்தல் போன்ற வேறு தண்டனைகளை அல்லாஹ் அவர்களுக்கு வழங்கியிருப்பான் என்று அஸ்-ஸுஹ்ரி கூறுகிறார். உர்வா, அஸ்-ஸுத்தி மற்றும் இப்னு ஸைத் ஆகியோர் கூறுகையில், யூதர்கள் இவ்வுலகில் தண்டிக்கப்பட வேண்டும் என்றும், மறுமையில் அவர்களுக்காக நரக நெருப்பை அல்லாஹ் தயார் செய்துள்ளான் என்றும் அல்லாஹ் விதித்துள்ளான்.<br />\r\n<br />\r\nஅல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْآخِرَةِ</span> <span class=\"quran-arabic-font text-success\">عَذَابُ</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span><br />\r\n<br />\r\n(மேலும் மறுமையில் அவர்களுக்கு நரக நெருப்பின் வேதனை உண்டு.) அதாவது, அவர்கள் நிச்சயமாகச் சந்திக்க வேண்டிய தண்டனை இதுவாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">بِأَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">شَآقُّواْ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">وَرَسُولَهُ</span><br />\r\n<br />\r\n(அது ஏனென்றால் அவர்கள் அல்லாஹ்வையும் அவனுடைய தூதரையும் எதிர்த்தார்கள்.) அதாவது, அல்லாஹ் இந்தத் தண்டனையை அவர்களுக்காகத் தயார் செய்து, தனது தூதரையும் தோழர்களையும் அவர்களுக்கு எதிராக அனுப்பினான். ஏனெனில் அவர்கள் அல்லாஹ்வையும் அவனது தூதரையும் எதிர்த்ததுடன், முந்தைய வேதங்களில் முஹம்மது (ஸல்) அவர்களின் வருகையைப் பற்றி அல்லாஹ் அறிவித்திருந்த நற்செய்திகளையும் மறுத்தனர். யூதர்கள் முஹம்மது (ஸல்) அவர்களைப் பற்றிய உண்மைகளைத் தங்கள் பிள்ளைகளை அறிவது போலவே அறிந்திருந்தனர்.<br />\r\n<br />\r\nஅல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يُشَآقِّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">شَدِيدُ</span> <span class=\"quran-arabic-font text-success\">الْعِقَابِ</span><br />\r\n<br />\r\n(மேலும் எவர் அல்லாஹ்வை எதிர்க்கிறாரோ, நிச்சயமாக அல்லாஹ் தண்டிப்பதில் கடுமையானவன்.)<br />\r\n<br />\r\n<strong>நபிகள் நாயகம் (ஸல்) அவர்கள் அல்லாஹ்வின் அனுமதியுடன் யூதர்களின் பேரீச்சை மரங்களை வெட்டினார்கள்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">قَطَعْتُمْ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">لِينَةٍ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">تَرَكْتُمُوهَا</span> <span class=\"quran-arabic-font text-success\">قَائِمَةً</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أُصُولِهَا</span> <span class=\"quran-arabic-font text-success\">فَبِإِذْنِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَلِيُخْزِيَ</span> <span class=\"quran-arabic-font text-success\">الْفَاسِقِينَ</span><br />\r\n<br />\r\n(நீங்கள் வெட்டிய 'லீனா' (பேரீச்சை மரம்) ஆகட்டும், அல்லது அதன் தண்டுப்பகுதியுடன் அப்படியே விட்டு வைத்ததாகட்டும், அது அல்லாஹ்வின் அனுமதியுடன்தான் நடந்தது. மேலும் அது பாவிகளை இழிவுபடுத்துவதற்காகவே ஆகும்.) 'லீனா' என்பது ஒரு சிறந்த வகை பேரீச்சை மரமாகும். அபூ உபைதா அவர்கள் கூறுகையில், 'லீனா' என்பது 'அஜ்வா' மற்றும் 'பர்னீ' வகைகளைத் தவிர்த்த பிற பேரீச்சை வகைகளைக் குறிக்கும் என்கிறார்கள். இன்னும் சிலர் 'அஜ்வா' தவிர மற்ற அனைத்துப் பேரீச்சை பழங்களையும் இது குறிக்கும் என்கின்றனர். இப்னு ஜரீர் அவர்கள் இது அனைத்துப் பேரீச்சை மரங்களையும் குறிக்கும் என்றும், இதில் 'புவைரா' வகையும் அடங்கும் என்றும் முஜாஹித் கூறியதாகக் குறிப்பிடுகிறார். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பனூ நளீர் கோத்திரத்தாரை இழிவுபடுத்தவும், அவர்கள் உள்ளங்களில் அச்சத்தை உண்டாக்கவும் அவர்களின் பேரீச்சை மரங்களை வெட்ட உத்தரவிட்டார்கள். முஹம்மது பின் இஸ்ஹாக், யஸீத் பின் ரூமான், கத்தாதா மற்றும் முகாத்தில் பின் ஹய்யான் ஆகியோர் கூறுகையில்: \"பனூ நளீர் கோத்திரத்தினர் நபிகள் நாயகம் (ஸல்) அவர்களுக்கு, 'பூமியில் குழப்பம் விளைவிப்பதைத் தடுத்த நீங்கள், இப்போது ஏன் மரங்களை வெட்ட உத்தரவிட்டீர்கள்?' என்று செய்தி அனுப்பினார்கள். அப்போது அல்லாஹ் இந்த கண்ணியமிக்க வசனத்தை இறக்கினான். முஸ்லிம்கள் வெட்டிய அல்லது விட்டு வைத்த எந்தவொரு பேரீச்சை மரமும் அல்லாஹ்வின் நாட்டம் மற்றும் அனுமதியுடன்தான் செய்யப்பட்டது என்றும், அது எதிரிகளை இழிவுபடுத்துவதற்காகவே என்றும் அல்லாஹ் கூறினான்.\"<br />\r\n<br />\r\nமுஜாஹித் அவர்கள் கூறுகையில்: \"முஹாஜிர்களில் சிலர், பேரீச்சை மரங்களை வெட்ட வேண்டாம், அவை முஸ்லிம்களுக்குப் போர்ச் செல்வங்களாகக் கிடைக்கும் என்று கூறித் தடுத்தனர். குர்ஆன், மரங்களை வெட்டியவர்களின் செயலையும், அதனைத் தடுத்தவர்களின் செயலையும் ஒருசேர அங்கீகரித்து, எது நடந்திருந்தாலும் அது அல்லாஹ்வின் அனுமதியுடன்தான் நடந்தது என்று தெளிவுபடுத்தியது.\" நபிகள் நாயகம் (ஸல்) அவர்களிடமிருந்தும் இதே பொருளில் ஹதீஸ் அறிவிக்கப்பட்டுள்ளது. அன்-நஸாயீ அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"(மரங்களை வெட்டியதால்) அவர்கள் தங்கள் கோட்டைகளிலிருந்து கீழே இறங்க நிர்பந்திக்கப்பட்டனர். அப்போது முஸ்லிம்கள் தயக்கம் காட்டி, 'நாங்கள் சிலவற்றை வெட்டினோம், சிலவற்றை விட்டுவிட்டோம். வெட்டியதற்கு நற்கூலி கிடைக்குமா? அல்லது விட்டுவிட்டதற்குப் பாவம் சேருமா?' என்று நபிகள் நாயகம் (ஸல்) அவர்களிடம் கேட்டனர். அப்போது அல்லாஹ் இந்த வசனத்தை இறக்கினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">قَطَعْتُمْ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">لِينَةٍ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">تَرَكْتُمُوهَا</span> <span class=\"quran-arabic-font text-success\">قَائِمَةً</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أُصُولِهَا</span> <span class=\"quran-arabic-font text-success\">فَبِإِذْنِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span><br />\r\n<br />\r\n(நீங்கள் வெட்டிய பேரீச்சை மரங்களாகட்டும் அல்லது அப்படியே விட்டதாகட்டும், அது அல்லாஹ்வின் அனுமதியுடன்தான் நடந்தது).\" இமாம் அஹ்மத் அவர்கள் இப்னு உமர் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"நபிகள் நாயகம் (ஸல்) அவர்கள் பனூ நளீர் கோத்திரத்தாரின் பேரீச்சை மரங்களை வெட்டி எரிக்க உத்தரவிட்டார்கள்.\" புகாரி மற்றும் முஸ்லிம் ஆகிய இரு நூல்களிலும் இதே போன்ற அறிவிப்பு உள்ளது. புகாரி அவர்கள் இப்னு உமர் (ரழி) வழியாகப் பதிவு செய்துள்ளதாவது: \"பனூ நளீர் மற்றும் பனூ குறைழா (நபிகள் நாயகத்திற்கு எதிராக) போரிட்டனர். நபிகள் நாயகம் (ஸல்) அவர்கள் பனூ நளீர் கூட்டத்தினரை நாடு கடத்தினார்கள். பனூ குறைழா கூட்டத்தினரை அங்கே இருக்க அனுமதித்தார்கள். பின்னர் குறைழா கூட்டத்தினருடன் போர் நடந்தபோது அவர்களின் ஆண்கள் கொல்லப்பட்டனர், பெண்கள் மற்றும் குழந்தைகள் சிறைபிடிக்கப்பட்டு சொத்துக்கள் முஸ்லிம்களுக்குப் பங்கிடப்பட்டன. அவர்களில் சிலர் நபிகள் நாயகம் (ஸல்) அவர்களிடம் தஞ்சம் புகுந்து இஸ்லாத்தை ஏற்றுத் தப்பித்துக் கொண்டனர். மதீனாவிலிருந்த பனூ கைனுகா, அப்துல்லாஹ் பின் ஸலாம் (ரழி) அவர்களின் கோத்திரம், பனூ ஹாரிதா உள்ளிட்ட அனைத்து யூதக் கூட்டத்தினரும் மதீனாவிலிருந்து வெளியேற்றப்பட்டனர்.\"<br />\r\n<br />\r\nஇரு ஸஹீஹ் நூல்களிலும் இப்னு உமர் (ரழி) அவர்கள் அறிவித்துள்ளதாவது: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பனூ நளீர் கோத்திரத்தாரின் 'அல்-புவைரா' என்ற இடத்திலுள்ள பேரீச்சை மரங்களை வெட்டி எரித்தார்கள்.\" அப்போது கண்ணியமிக்க அல்லாஹ் இந்த வசனத்தை இறக்கினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">قَطَعْتُمْ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">لِينَةٍ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">تَرَكْتُمُوهَا</span> <span class=\"quran-arabic-font text-success\">قَائِمَةً</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أُصُولِهَا</span> <span class=\"quran-arabic-font text-success\">فَبِإِذْنِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَلِيُخْزِيَ</span> <span class=\"quran-arabic-font text-success\">الْفَاسِقِينَ</span><br />\r\n<br />\r\n(நீங்கள் வெட்டிய 'லீனா' (பேரீச்சை மரம்) ஆகட்டும், அல்லது அதன் தண்டுப்பகுதியுடன் அப்படியே விட்டு வைத்ததாகட்டும், அது அல்லாஹ்வின் அனுமதியுடன்தான் நடந்தது. மேலும் அது பாவிகளை இழிவுபடுத்துவதற்காகவே ஆகும்.)\" முஹம்மது பின் இஸ்ஹாக் கூறுகையில், பனூ நளீர் போர் உஹுத் மற்றும் பிஃரு மஊனா சம்பவங்களுக்குப் பிறகு நடந்தது என்று குறிப்பிடுகிறார்.<br />\r\n<br />","text":"இது மதீனாவில் அருளப்பட்டது\n\r\n\n\r\nஇப்னு அப்பாஸ் (ரழி) அவர்கள் இந்த அத்தியாயத்தை 'ஸூரா பனூ நளீர்' என்று அழைப்பார்கள். ஸயீத் பின் மன்சூர் அவர்கள் பதிவு செய்துள்ளதாவது: ஸயீத் பின் ஜுபைர் அவர்கள் கூறினார்கள், \"நான் இப்னு அப்பாஸ் (ரழி) அவர்களிடம் ஸூரத்துல் ஹஷ்ரைப் பற்றிக் கேட்டேன். அதற்கு அவர்கள், 'அது பனூ நளீர் (கோத்திரத்தாரைப்) பற்றி அருளப்பட்டது' என்று கூறினார்கள்.\" புகாரி மற்றும் முஸ்லிம் ஆகியோரும் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து மற்றொரு அறிவிப்பாளர் தொடர் வழியாக இதனைப் பதிவு செய்துள்ளனர். புகாரி அவர்களும் அபூ அவானாவிலிருந்து, அவர் அபூ பிஷ்ரிடமிருந்தும், அவர் ஸயீத் பின் ஜுபைரிடமிருந்தும் பதிவு செய்துள்ளனர். அவர் கூறினார்: \"நான் இப்னு அப்பாஸ் (ரழி) அவர்களிடம் 'ஸூரத்துல் ஹஷ்ர்' பற்றிக் கேட்டேன். அதற்கு அவர்கள், 'ஸூரா பனூ நளீர்' என்று பதிலளித்தார்கள்.\"\n\r\n\n\r\nبِسْمِ اللَّهِ الرَّحْمَـنِ الرَّحِيمِ\n\r\n\n\r\nஅளவற்ற அருளாளனும் நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் திருப்பெயரால்.\n\r\n\n\r\nஅனைத்தும் அல்லாஹ்வை அதனதன் வழியில் துதிக்கின்றன\n\r\n\n\r\nسَبَّحَ لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَهُوَ الْعَزِيزُ الْحَكِيمُ\n\r\n\n\r\nவானங்களிலும் பூமியிலும் உள்ள அனைத்தும் அல்லாஹ்வைப் புகழ்ந்து, போற்றி, அவனது ஏகத்துவத்தை உறுதிப்படுத்தி, அவனிடம் பிரார்த்தனை செய்கின்றன என்று அல்லாஹ் கூறுகிறான். அல்லாஹ் மற்றொரு வசனத்தில் (ஆயத்தில்) கூறுகிறான்:\n\r\n\n\r\nتُسَبِّحُ لَهُ السَّمَاوَاتُ السَّبْعُ وَالْأَرْضُ وَمَنْ فِيهِنَّ وَإِنْ مِنْ شَيْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِ وَلَكِنْ لَا تَفْقَهُونَ تَسْبِيحَهُمْ\n\r\n\n\r\n(ஏழு வானங்களும், பூமியும், அவற்றில் உள்ளவையும் அவனைத் துதிக்கின்றன. அவனது புகழைக் கொண்டு துதிக்காத பொருள் எதுவுமே இல்லை. எனினும், அவை துதிப்பதை நீங்கள் புரிந்து கொள்ள மாட்டீர்கள்.) (17:44) அல்லாஹ்வின் கூற்று:\n\r\n\n\r\nوَهُوَ الْعَزِيزُ\n\r\n\n\r\n(மேலும், அவன் மிகைத்தவன்) அதாவது, வெல்ல முடியாத வல்லமை கொண்டவன்.\n\r\n\n\r\nالْحَكِيمُ\n\r\n\n\r\n(ஞானமிக்கவன்) தான் விதிக்கும் சட்டங்களிலும் தீர்மானங்களிலும் ஞானமுள்ளவன்.\n\r\n\n\r\nபனூ நளீர் கோத்திரத்தார் சந்தித்த இறுதி முடிவு\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nهُوَ الَّذِي أَخْرَجَ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ\n\r\n\n\r\n(வேதக்காரர்களில் நிராகரித்தவர்களை அவன்தான் வெளியேற்றினான்). இப்னு அப்பாஸ் (ரழி), முஜாஹித், அஸ்-ஸுஹ்ரி மற்றும் பலரது கூற்றுப்படி இது 'பனூ நளீர்' என்ற யூத கோத்திரத்தைக் குறிக்கிறது. அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மதீனாவிற்கு ஹிஜ்ரத் (புலம்பெயர்தல்) செய்தபோது, யூதர்களுடன் ஒரு சமாதான உடன்படிக்கையை மேற்கொண்டார்கள். அதன்படி, நபிகள் நாயகம் (ஸல்) அவர்களும் அவர்களும் போரிட மாட்டார்கள் (என்று முடிவானது). ஆனால், அவர்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுடன் செய்துகொண்ட அந்த உடன்படிக்கைக்கு விரைவில் துரோகம் இழைத்தனர். எனவே, அல்லாஹ் அவர்கள் மீது தடுத்து நிறுத்த முடியாத தனது வேதனையை இறக்கினான்; அவனது விதி அவர்களைச் சூழ்ந்தது. முஸ்லிம்கள் தங்களால் கைப்பற்ற முடியாது என்று கருதிய அவர்களின் பலமான கோட்டைகளை விட்டு வெளியேறுமாறு நபிகள் நாயகம் (ஸல்) அவர்கள் அவர்களைக் கட்டாயப்படுத்தினார்கள். தங்கள் கோட்டைகள் தங்களை அல்லாஹ்வின் வேதனையிலிருந்து பாதுகாக்கும் என்று யூதர்கள் நினைத்தனர்; ஆனால் அவை அல்லாஹ்வுக்கு எதிராக அவர்களுக்குச் சிறிதும் உதவவில்லை. பின்னர், அவர்கள் எதிர்பாராத விதமாக அல்லாஹ்விடமிருந்து (தண்டனை) வந்தது. அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவர்களை மதீனாவிலிருந்து வெளியேற்றினார்கள். அவர்களில் சிலர் ஷாம் பகுதியிலுள்ள 'அத்ரிஆத்' என்ற இடத்திற்குச் சென்றனர். இதுவே மக்கள் ஒன்றுதிரட்டப்படும் (மஹ்ஷர்) மற்றும் உயிர்த்தெழுப்பப்படும் இடமாகும். மற்றவர்கள் கைபருக்குச் சென்றனர். அவர்கள் தங்கள் ஒட்டகங்கள் சுமக்கக்கூடிய பொருட்களை மட்டும் எடுத்துச் செல்ல நபிகள் நாயகம் (ஸல்) அவர்கள் அனுமதித்தார்கள். எடுத்துச் செல்ல முடியாத சொத்துக்களை அவர்களே அழித்தனர். இதனால்தான், கண்ணியத்திற்குரிய அல்லாஹ் இவ்வாறு கூறினான்:\n\r\n\n\r\nيُخْرِبُونَ بُيُوتَهُمْ بِأَيْدِيهِمْ وَأَيْدِي الْمُؤْمِنِينَ فَاعْتَبِرُوا يَا أُولِي الْأَبْصَارِ\n\r\n\n\r\n(அவர்கள் தங்கள் வீடுகளைத் தங்கள் கைகளாலும், முஃமின்களின் (இறைநம்பிக்கையாளர்களின்) கைகளாலும் அழித்துக் கொண்டனர். ஆகவே, அகப்பார்வை உடையவர்களே! இதிலிருந்து படிப்பினை பெறுங்கள்.) அதாவது, \"அல்லாஹ்வின் கட்டளையை மீறி, அவனது தூதரை எதிர்த்து, அவனது வேதத்தைப் பொய்பித்தவர்களின் முடிவைச் சிந்தித்துப் பாருங்கள். இவ்வுலகில் அல்லாஹ் அவர்களை எவ்வாறு இழிவுபடுத்தினான் என்பதையும், மறுமையில் அவர்களுக்காக அவன் வைத்துள்ள துன்பகரமான வேதனையையும் பாருங்கள்.\" அபுதாவூத் அவர்கள், அப்துர்ரஹ்மான் பின் கஅப் பின் மாலிக் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: நபிகள் நாயகம் (ஸல்) அவர்களின் தோழர்களில் ஒருவர் கூறினார், \"குறைஷி இணைவைப்பாளர்கள், அப்துல்லாஹ் பின் உபை மற்றும் அவ்ஸ், கஸ்ரஜ் கோத்திரங்களில் இன்னும் சிலைகளை வணங்கிக் கொண்டிருந்தவர்களுக்கும் கடிதம் எழுதினார்கள். அந்த நேரத்தில், பத்ருப் போருக்கு முன்னதாக, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மதீனாவில் இருந்தார்கள். அவர்கள் அந்த கடிதத்தில்: 'நீங்கள் எங்கள் ஆளுக்கு (முஹம்மதுக்கு) அடைக்கலம் கொடுத்துள்ளீர்கள். அல்லாஹ்வின் மீது ஆணையாக, நீங்கள் அவருடன் போரிட வேண்டும்; இல்லையெனில் நாங்கள் உங்களை வெளியேற்றுவோம் அல்லது எங்களது படைகளைத் திரட்டி வந்து, உங்கள் வீரர்களைக் கொன்று உங்கள் பெண்களைச் சிறைபிடிப்போம்' என்று எழுதியிருந்தனர். இந்த அச்சுறுத்தல் செய்தி அப்துல்லாஹ் பின் உபை மற்றும் அவ்ஸ், கஸ்ரஜ் கோத்திரத்து இணைவைப்பாளர்களை அடைந்ததும், அவர்கள் நபிகள் நாயகம் (ஸல்) அவர்களுடன் போரிடத் தயாரானார்கள். இந்தச் செய்தி நபிகள் நாயகம் (ஸல்) அவர்களுக்கு எட்டியதும், அவர்கள் அவர்களிடம் சென்று கூறினார்கள்:\n\r\n\n\r\n«لَقَدْ بَلَغَ وَعِيدُ قُرَيْشٍ مِنْكُمُ الْمَبَالِغَ، مَا كَانَتْ تَكِيدُكُمْ بِأَكْثَرَ مِمَّا تُرِيدُ أَن تَكِيدُوا بِهِ أَنْفُسَكُمْ، تُرِيدُونَ أَنْ تُقَاتِلُوا أَبْنَاءَكُمْ وَإِخْوَانَكُم»\n\r\n\n\r\n(குறைஷிகளின் அச்சுறுத்தல் உங்களை மிகுந்த கவலைக்குள்ளாக்கியுள்ளது! உங்கள் செயல்களால் நீங்களே உங்களுக்கு ஏற்படுத்திக் கொள்ளும் தீங்கை விட அதிகத் தீங்கை குறைஷிகளால் உங்களுக்கு ஏற்படுத்த முடியாது. நீங்கள் உங்கள் பிள்ளைகளுடனும் சகோதரர்களுடனும் போரிட விரும்புகிறீர்களா?) நபிகள் நாயகம் (ஸல்) அவர்களிடமிருந்து இந்த வார்த்தைகளைக் கேட்டதும் அவர்கள் கலைந்து சென்றனர். நடந்த செய்தி குறைஷி இணைவைப்பாளர்களை அடைந்தது. பத்ருப் போருக்குப் பிறகு, குறைஷி இணைவைப்பாளர்கள் மதீனாவிலிருந்த யூதர்களுக்கு, 'உங்களிடம் கவசங்களும் கோட்டைகளும் உள்ளன! நீங்கள் எமது ஆளுடன் போரிட வேண்டும், இல்லையெனில் நாங்கள் உங்களுக்கு இன்னின்ன தண்டனைகளைத் தருவோம்; உங்கள் பெண்களைக் கைப்பற்றுவதிலிருந்து எங்களை எதுவும் தடுக்க முடியாது' என்று கடிதம் எழுதினார்கள். இந்தக் கடிதத்தின் செய்தியும் நபிகள் நாயகம் (ஸல்) அவர்களுக்கு எட்டியது. பனூ நளீர் கோத்திரத்தினர் உடன்படிக்கையை மீறி துரோகம் செய்யத் திட்டமிட்டனர். பனூ நளீர் கோத்திரத்தினர், நபிகள் நாயகம் (ஸல்) அவர்களை முப்பது தோழர்களுடன் வந்து, இரு தரப்பிற்கும் இடைப்பட்ட ஒரு பகுதியில் தங்கள் முப்பது ரபிக்களை (யூத மத அறிஞர்களை) சந்திக்குமாறு செய்தி அனுப்பினார்கள். அந்த ரபிக்கள் நபிகள் நாயகம் (ஸல்) அவர்கள் கூறுவதைக் கேட்பார்கள் என்றும், அவர்கள் அவரை நம்பினால், பனூ நளீர் மக்கள் அனைவரும் அவரை நம்புவார்கள் என்றும் கூறினார்கள். ஆனால், அவர்கள் அல்லாஹ்வின் தூதரைக் (ஸல்) கொலை செய்யவே திட்டமிட்டனர். அவர்கள் தீங்கு இழைக்கும் முன்பே அல்லாஹ் இந்தச் சதியைப் பற்றித் தனது தூதருக்குத் (ஸல்) தெரிவித்தான். மறுநாள் நபிகள் நாயகம் (ஸல்) அவர்கள் தனது படைகளைத் திரட்டி அவர்களின் பகுதியை முற்றுகையிட்டு, அவர்களிடம் கூறினார்கள்:\n\r\n\n\r\n«إِنَّكُمْ وَاللهِ لَا تَأْمَنُونَ عِنْدِي إِلَّا بِعَهْدٍ تُعَاهِدُونَنِي عَلَيْه»\n\r\n\n\r\n(அல்லாஹ்வின் மீது ஆணையாக! நீங்கள் என்னுடன் உங்கள் சமாதான உடன்படிக்கையைப் புதுப்பிக்கும் வரை, நீங்கள் என்னிடம் பாதுகாப்பாக இருக்க முடியாது.) அவர்கள் அதற்கு மறுப்பு தெரிவித்தனர். அன்றைய தினத்தின் எஞ்சிய பகுதியில் நபிகள் நாயகம் (ஸல்) அவர்கள் அவர்களுடன் போரிட்டார்கள். அடுத்த நாள் காலையில், நபிகள் நாயகம் (ஸல்) அவர்கள் பனூ குறைழா கோத்திரத்தை முற்றுகையிட்டு, அன்றைய தினம் பனூ நளீர் கோத்திரத்தினரைத் தனியாக விட்டுவிட்டார்கள். பனூ குறைழா கோத்திரத்தாரை ஒரு புதிய சமாதான உடன்படிக்கையில் கையெழுத்திடுமாறு நபிகள் நாயகம் (ஸல்) அவர்கள் கட்டளையிட்டார்கள்; அவர்களும் அதனை ஏற்றுக்கொண்டார்கள். பின்னர் நபிகள் நாயகம் (ஸல்) அவர்கள் பனூ குறைழாவை விட்டுவிட்டு, மீண்டும் பனூ நளீர் கோத்திரத்தாரிடம் சென்று, அவர்கள் மதீனாவிலிருந்து பாதுகாப்பாக வெளியேறுவதற்குப் பதிலாக சரணடைய ஒப்புக்கொள்ளும் வரை அவர்களுடன் போரிட்டார்கள். பனூ நளீர் கோத்திரத்தினர் மதீனாவிலிருந்து வெளியேறினர். அவர்கள் தங்கள் வீட்டுச் சாமான்கள் மற்றும் கதவுகள், மரக்கட்டைகள் உட்படத் தங்கள் ஒட்டகங்கள் சுமக்கக்கூடிய அனைத்தையும் எடுத்துச் சென்றனர். பனூ நளீர் கோத்திரத்தாரின் பேரீச்சைத் தோட்டங்களை அல்லாஹ் தனது தூதருக்கு (ஸல்) வழங்கினான். அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَمَا أَفَاءَ اللَّهُ عَلَى رَسُولِهِ مِنْهُمْ فَمَا أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلٍ وَلَا رِكَابٍ\n\r\n\n\r\n(அவர்களிடமிருந்து அல்லாஹ் தன் தூதருக்குப் போர்ச் செல்வமாக எதைக் கொடுத்தானோ, அதற்காக நீங்கள் குதிரைகளையோ ஒட்டகங்களையோ ஓட்டிச் செல்லவில்லை.) அதாவது, நீங்கள் சண்டையின்றிப் பெற்ற செல்வமாகும். நபிகள் நாயகம் (ஸல்) அவர்கள் அந்தத் தோட்டங்களின் பெரும்பகுதியை முஹாஜிர்களுக்குப் பங்கிட்டுக் கொடுத்தார்கள். அன்சாரிகளில் ஏழைகளாக இருந்த இருவருக்கு மட்டுமே அதில் பங்கு கொடுத்தார்கள். அவர்களைத் தவிர அன்சாரிகளில் வேறு யாருக்கும் அதில் அவர்கள் பங்கு வழங்கவில்லை. நபிகள் நாயகம் (ஸல்) அவர்கள் போர்ச் செல்வத்தில் ஒரு பகுதியைத் தமக்காக வைத்துக் கொண்டார்கள். நபிகள் நாயகம் (ஸல்) அவர்களின் அந்த தர்மத்தின் பகுதி, பின்னர் அவர்களின் மகளின் பிள்ளைகள், அதாவது பாத்திமா (ரழி) அவர்களின் பிள்ளைகளின் நிர்வாகத்திற்கு மாற்றப்பட்டது. எவ்வாறாயினும், பனூ நளீர் போரின் சுருக்கம் இதுவே. அல்லாஹ் ஒருவனிடமே நாம் உதவியைத் தேடுகிறோம்.\n\r\n\n\r\nபனூ நளீர் போர் ஏற்படுவதற்கான காரணம்\n\r\n\n\r\nபிஃரு மஊனா என்ற இடத்தில் குர்ஆனைக் கற்பிப்பதற்காக நபிகள் நாயகம் (ஸல்) அவர்களால் அனுப்பப்பட்ட எழுபது தோழர்கள் கொல்லப்பட்டனர். அம்ர் பின் உமய்யா அழ்-ளம்ரீ (ரழி) அவர்கள் மட்டும் தப்பினார். அவர் மதீனாவிற்குத் திரும்பும் வழியில் பனூ ஆமிர் கோத்திரத்தைச் சேர்ந்த இருவரைக் கொன்றார். அந்த இருவருக்கும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பாதுகாப்பு அளித்திருந்தது அவருக்குத் தெரியாது. அவர் மதீனாவிற்குத் திரும்பி வந்து நடந்ததை நபிகள் நாயகம் (ஸல்) அவர்களிடம் கூறியபோது, நபிகள் நாயகம் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«لَقَدْ قَتَلْتَ رَجُلَيْنِ لَأَدِيَنَّهُمَا»\n\r\n\n\r\n(நீர் இருவரைக் கொன்றுவிட்டீர், அவர்களுக்காக நான் இரத்தப்பழித் தொகை (தியா) செலுத்துவேன்.) பனூ நளீர் மற்றும் பனூ ஆமிர் கோத்திரத்தினர் ஒருவருக்கொருவர் கூட்டாளிகளாகவும் உடன்படிக்கை செய்தவர்களாகவும் இருந்தனர். எனவே, அந்த இருவருக்கான இரத்தப்பழித் தொகையைச் செலுத்த உதவுமாறு நபிகள் நாயகம் (ஸல்) அவர்கள் பனூ நளீர் கோத்திரத்தாரிடம் கேட்டார்கள். பனூ நளீர் கோத்திரத்தாரின் பகுதி மதீனாவின் புறநகரில் கிழக்கே சில மைல் தொலைவில் இருந்தது. முஹம்மது பின் இஸ்ஹாக் பின் யஸார் அவர்கள் தனது ஸீரா நூலில் கூறுகிறார்: \"பின்னர் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அம்ர் பின் உமய்யா அழ்-ளம்ரீயால் கொல்லப்பட்ட பனூ ஆமிர் கோத்திரத்தைச் சேர்ந்த இருவருக்கான இரத்தப்பழித் தொகையைச் செலுத்த உதவி கேட்க பனூ நளீர் கோத்திரத்தாரிடம் சென்றார்கள். யஸீத் பின் ரூமான் அவர்களின் கூற்றுப்படி, அவர்களுக்கு நபிகள் நாயகம் (ஸல்) அவர்களின் பாதுகாப்பு வாக்குறுதி இருந்தது. பனூ நளீர் மற்றும் பனூ ஆமிர் கோத்திரத்தாருக்குள் உடன்படிக்கை இருந்தது. அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் உதவி கேட்டு அவர்களிடம் சென்றபோது, 'நிச்சயமாக, ஓ அபுல் காஸிம்! நீங்கள் உதவி கேட்டதால் நாங்கள் உங்களுக்கு உதவுகிறோம்' என்றனர். ஆனால், அவர்கள் தங்களுக்குள் இரகசியமாகப் பேசிக் கொண்டபோது, 'இந்த மனிதரை (கொல்ல) இதைவிடச் சிறந்த வாய்ப்பு உங்களுக்குக் கிடைக்காது' என்று கூறினர். அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவர்களின் ஒரு வீட்டின் சுவருக்கு அருகில் அமர்ந்திருந்தார்கள். 'யார் இந்தச் சுவரில் ஏறி, இவர் மீது ஒரு கல்லைப் போட்டு இவரது தொல்லையிலிருந்து நம்மை விடுவிப்பார்?' என்று கேட்டனர். அம்ர் பின் ஜிஹாஷ் பின் கஅப் என்பவர் முன்வந்து, நபிகள் நாயகம் (ஸல்) அவர்கள் மீது கல்லை எறிய வீட்டின் சுவரில் ஏறினார். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அபூபக்ர் (ரழி), உமர் (ரழி) மற்றும் அலீ (ரழி) போன்ற சில தோழர்களுடன் அமர்ந்திருந்தார்கள். இந்தச் சதி பற்றிய வஹீ (இறைச்செய்தி) வானத்திலிருந்து நபிகள் நாயகம் (ஸல்) அவர்களுக்குத் தெரிவிக்கப்பட்டது. உடனே அவர்கள் எழுந்து மதீனாவிற்குத் திரும்பிச் சென்றார்கள். நபிகள் நாயகம் (ஸல்) அவர்களை நீண்ட நேரமாகக் காணாததால், தோழர்கள் அவர்களைத் தேடிச் சென்றனர். மதீனாவிலிருந்து ஒரு மனிதர் வருவதைக் கண்டு அவரிடம் கேட்டனர். அவர் நபிகள் நாயகம் (ஸல்) அவர்கள் மதீனாவிற்குள் நுழைவதைக் கண்டதாகக் கூறினார். தோழர்கள் நபிகள் நாயகம் (ஸல்) அவர்களிடம் சென்றபோது, யூதர்கள் தமக்கு எதிராகத் தீட்டிய துரோகச் சதியைப் பற்றி அவர்கள் தோழர்களிடம் கூறினார்கள். மேலும் போருக்குத் தயாராகும்படியும், பனூ நளீர் கோத்திரத்தாரை நோக்கிப் புறப்படும்படியும் கட்டளையிட்டார்கள். நபிகள் நாயகம் (ஸல்) அவர்கள் தனது படைகளைத் திரட்டி பனூ நளீர் பகுதிக்குச் சென்றார்கள். அவர்கள் தங்கள் பலமான கோட்டைகளில் தஞ்சம் புகுந்தனர். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவர்களின் பேரீச்சை மரங்களை வெட்டி எரிக்க உத்தரவிட்டார்கள். இதைக் கண்டு யூதர்கள், 'முஹம்மதே! பூமியில் குழப்பம் விளைவிப்பதைத் தடுத்து வந்த நீங்கள், இப்போது ஏன் பேரீச்சை மரங்களை வெட்டி எரிக்க உத்தரவிடுகிறீர்கள்?' என்று கூச்சலிட்டனர். இதற்கிடையில், அப்துல்லாஹ் பின் உபை பின் சலூல் மற்றும் பனூ அவ்ஃப் பின் கஸ்ரஜ் கோத்திரத்தைச் சேர்ந்த சிலர் பனூ நளீர் கோத்திரத்தாருக்கு ஒரு செய்தியை அனுப்பினார்கள்: 'உறுதியாக இருங்கள். நாங்கள் உங்களைக் கைவிட மாட்டோம். உங்களுக்கு எதிராகப் போர் நடந்தால் நாங்களும் உங்களுடன் சேர்ந்து போரிடுவோம். நீங்கள் வெளியேற்றப்பட்டால் நாங்களும் உங்களுடன் வருவோம்.' யூதர்கள் இந்த ஆதரவை நம்பிக் காத்திருந்தனர், ஆனால் நயவஞ்சகர்கள் வாக்குறுதியை நிறைவேற்றவில்லை. அல்லாஹ் யூதர்களின் உள்ளங்களில் திகிலை உண்டாக்கினான். அவர்கள் மதீனாவிலிருந்து பாதுகாப்பாக வெளியேறவும், உயிருக்கு உத்தரவாதம் அளிக்கவும் நபிகள் நாயகம் (ஸல்) அவர்களிடம் கோரிக்கை விடுத்தனர். அதற்குப் பதிலாக, ஆயுதங்களைத் தவிர, தங்கள் ஒட்டகங்கள் சுமக்கக்கூடிய பொருட்களை மட்டும் எடுத்துச் செல்ல அனுமதி கேட்டனர். நபிகள் நாயகம் (ஸல்) அவர்கள் அதற்குச் சம்மதித்தார்கள். யூதர்கள் தங்களால் இயன்ற அனைத்துச் செல்வங்களையும் சேகரித்தனர். ஒரு யூதர் தனது வீட்டு வாசலை எடுத்துச் செல்வதற்காக, அதன் சுவரையே இடித்தார். பனூ நளீர் கோத்திரத்தினர் கைபருக்கும், சில பேர் ஷாம் தேசத்திற்கும் சென்றனர். அவர்கள் விட்டுச் சென்ற மீதமுள்ள சொத்துக்கள் அனைத்தும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் கட்டுப்பாட்டிற்கு வந்தன. நபிகள் நாயகம் (ஸல்) அவர்கள் அதனை முஹாஜிர்களுக்குப் பங்கிட்டுக் கொடுத்தார்கள். அன்சாரிகளில் சஹ்ல் பின் ஹுனைஃப் (ரழி) மற்றும் அபூ துஜானா (ரழி) ஆகிய இரு ஏழைத் தோழர்களுக்கு மட்டும் பங்கு கொடுத்தார்கள். பனூ நளீர் கோத்திரத்தைச் சேர்ந்த யாமீன் பின் உமைர் மற்றும் அபூ ஸஅத் பின் வஹ்ப் ஆகிய இருவர் மட்டுமே இஸ்லாத்தை ஏற்றனர். அவர்கள் இஸ்லாத்தைத் தழுவியதால் தங்கள் செல்வத்தைப் பாதுகாத்துக் கொண்டனர்.\" இப்னு இஸ்ஹாக் தொடர்கிறார்: \"யாமீனின் சந்ததியினர் என்னிடம் கூறியது: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் யாமீனிடம், 'உமது சகோதரன் எனக்கு எதிராகச் செய்த சதியைக் குறித்து நீர் அறிந்தீரா?' என்று கேட்டார்கள். யாமீன் பின் உமைர் (ரழி) அவர்கள் தனது சகோதரன் அம்ர் பின் ஜிஹாஷைக் கொல்பவருக்கு வெகுமதி அளிப்பதாகக் கூறினார்; அதன்படி ஒருவர் அவனைக் கொன்றார்.\" இப்னு இஸ்ஹாக் மேலும் கூறினார்: \"ஸூரத்துல் ஹஷ்ர் முழுவதுமே பனூ நளீர் கோத்திரத்தாரைப் பற்றியே அருளப்பட்டது.\"\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nهُوَ الَّذِي أَخْرَجَ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ\n\r\n\n\r\n(வேதக்காரர்களில் நிராகரித்தவர்களை அவன்தான் வெளியேற்றினான்) இது பனூ நளீர் கோத்திரத்தாரைக் குறிக்கிறது.\n\r\n\n\r\nمِنْ دِيَارِهِمْ لِأَوَّلِ الْحَشْرِ\n\r\n\n\r\n(அவர்களின் வீடுகளிலிருந்து முதல் ஒன்று கூடலுக்காக.) அல்லாஹ் கூறினான்:\n\r\n\n\r\nمَا ظَنَنتُمْ أَن يَخْرُجُواْ\n\r\n\n\r\n(அவர்கள் வெளியேறுவார்கள் என்று நீங்கள் நினைக்கவில்லை.) அதாவது, நீங்கள் அவர்களைச் சில நாட்களே முற்றுகையிட்டிருந்த நிலையில் அவர்கள் வெளியேறுவார்கள் என்று நீங்கள் கருதவில்லை. தோழர்கள் ஆறு நாட்கள் மட்டுமே முற்றுகையிட்டிருந்தனர். அவர்களின் கோட்டைகளோ மிகவும் பலமானவை. இதனால்தான் அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَظَنُّوا أَنَّهُمْ مَانِعَتُهُمْ حُصُونُهُمْ مِنَ اللَّهِ فَأَتَاهُمُ اللَّهُ مِنْ حَيْثُ لَمْ يَحْتَسِبُوا\n\r\n\n\r\n(மேலும் அவர்கள் தங்கள் கோட்டைகள் தங்களை அல்லாஹ்விடமிருந்து பாதுகாக்கும் என்று நினைத்தார்கள்! ஆனால் அல்லாஹ் அவர்கள் எதிர்பாராத விதத்தில் அவர்களிடம் வந்தான்.) அதாவது, அவர்கள் சற்றும் எதிர்பாராத தண்டனை அல்லாஹ்விடமிருந்து வந்தது. அல்லாஹ் மற்றொரு வசனத்தில் (ஆயத்தில்) கூறுகிறான்:\n\r\n\n\r\nقَدْ مَكَرَ الَّذِينَ مِنْ قَبْلِهِمْ فَأَتَى اللَّهُ بُنْيَانَهُمْ مِنَ الْقَوَاعِدِ فَخَرَّ عَلَيْهِمُ السَّقْفُ مِنْ فَوْقِهِمْ وَأَتَاهُمُ الْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ\n\r\n\n\r\n(அவர்களுக்கு முன்னிருந்தவர்களும் இவ்வாறே சதி செய்தனர். ஆனால் அல்லாஹ் அவர்களின் கட்டிடங்களின் அஸ்திவாரங்களையே தகர்த்தான். ஆகவே, கூரை அவர்கள் மீது மேலிருந்து விழுந்தது. அவர்கள் உணராத திசையிலிருந்து வேதனை அவர்களை வந்தடைந்தது.) (16:26)\n\r\n\n\r\nஅல்லாஹ் கூறினான்:\n\r\n\n\r\nوَقَذَفَ فِى قُلُوبِهِمُ الرُّعْبَ\n\r\n\n\r\n(மேலும் அவன் அவர்களின் உள்ளங்களில் திகிலை ஏற்படுத்தினான்.) அதாவது அல்லாஹ் அவர்களின் உள்ளங்களில் அச்சத்தையும் பீதியையும் உண்டாக்கினான். ஒரு மாத காலப் பயண தூரத்திலுள்ள எதிரிகளையும் அச்சுறுத்துவதன் மூலம் எவருக்கு வெற்றி வழங்கப்பட்டதோ, அவரே அவர்களை முற்றுகையிட்டிருக்கும்போது அவர்களுக்கு அச்சம் ஏற்படாமல் இருக்குமா? நபிகள் நாயகம் (ஸல்) அவர்கள் மீது அல்லாஹ்வின் சாந்தியும் சமாதானமும் உண்டாவதாக. இப்னு இஸ்ஹாக்கின் விளக்கத்தில் நாம் ஏற்கனவே பார்த்தபடி:\n\r\n\n\r\nيُخْرِبُونَ بُيُوتَهُمْ بِأَيْدِيهِمْ وَأَيْدِي الْمُؤْمِنِينَ\n\r\n\n\r\n(அவர்கள் தங்கள் வீடுகளைத் தங்கள் கைகளாலும், முஃமின்களின் கைகளாலும் அழித்துக் கொண்டனர்.) யூதர்கள் தாங்கள் எடுத்துச் செல்ல விரும்பிய கூரைகளையும் கதவுகளையும் ஒட்டகங்களில் சுமந்து செல்வதற்காகத் தாங்களே அவற்றைப் பிரித்து அழித்தனர். இவ்வாறே உர்வா பின் அஸ்-ஸுபைர் (ரழி), அப்துர்ரஹ்மான் பின் ஸைத் பின் அஸ்லம் மற்றும் பலர் கூறியுள்ளனர்.\n\r\n\n\r\nஅல்லாஹ்வின் கூற்று:\n\r\n\n\r\nوَلَوْلاَ أَن كَتَبَ اللَّهُ عَلَيْهِمُ الْجَلاَءَ لَعَذَّبَهُمْ فِى الدُّنْيَا\n\r\n\n\r\n(மேலும் அல்லாஹ் அவர்கள் மீது நாடு கடத்தலை விதித்திருக்காவிட்டால், அவன் நிச்சயமாக அவர்களை இவ்வுலகிலேயே தண்டித்திருப்பான்.) அதாவது, அவர்கள் மதீனாவை விட்டு வெளியேற வேண்டும் என்று அல்லாஹ் ஏற்கனவே விதித்திருக்காவிட்டால், அவர்களைக் கொலை செய்தல் அல்லது சிறைப்பிடித்தல் போன்ற வேறு தண்டனைகளை அல்லாஹ் அவர்களுக்கு வழங்கியிருப்பான் என்று அஸ்-ஸுஹ்ரி கூறுகிறார். உர்வா, அஸ்-ஸுத்தி மற்றும் இப்னு ஸைத் ஆகியோர் கூறுகையில், யூதர்கள் இவ்வுலகில் தண்டிக்கப்பட வேண்டும் என்றும், மறுமையில் அவர்களுக்காக நரக நெருப்பை அல்லாஹ் தயார் செய்துள்ளான் என்றும் அல்லாஹ் விதித்துள்ளான்.\n\r\n\n\r\nஅல்லாஹ் கூறினான்:\n\r\n\n\r\nوَلَهُمْ فِي الْآخِرَةِ عَذَابُ النَّارِ\n\r\n\n\r\n(மேலும் மறுமையில் அவர்களுக்கு நரக நெருப்பின் வேதனை உண்டு.) அதாவது, அவர்கள் நிச்சயமாகச் சந்திக்க வேண்டிய தண்டனை இதுவாகும்.\n\r\n\n\r\nذَلِكَ بِأَنَّهُمْ شَآقُّواْ اللَّهَ وَرَسُولَهُ\n\r\n\n\r\n(அது ஏனென்றால் அவர்கள் அல்லாஹ்வையும் அவனுடைய தூதரையும் எதிர்த்தார்கள்.) அதாவது, அல்லாஹ் இந்தத் தண்டனையை அவர்களுக்காகத் தயார் செய்து, தனது தூதரையும் தோழர்களையும் அவர்களுக்கு எதிராக அனுப்பினான். ஏனெனில் அவர்கள் அல்லாஹ்வையும் அவனது தூதரையும் எதிர்த்ததுடன், முந்தைய வேதங்களில் முஹம்மது (ஸல்) அவர்களின் வருகையைப் பற்றி அல்லாஹ் அறிவித்திருந்த நற்செய்திகளையும் மறுத்தனர். யூதர்கள் முஹம்மது (ஸல்) அவர்களைப் பற்றிய உண்மைகளைத் தங்கள் பிள்ளைகளை அறிவது போலவே அறிந்திருந்தனர்.\n\r\n\n\r\nஅல்லாஹ் கூறினான்:\n\r\n\n\r\nوَمَن يُشَآقِّ اللَّهَ فَإِنَّ اللَّهَ شَدِيدُ الْعِقَابِ\n\r\n\n\r\n(மேலும் எவர் அல்லாஹ்வை எதிர்க்கிறாரோ, நிச்சயமாக அல்லாஹ் தண்டிப்பதில் கடுமையானவன்.)\n\r\n\n\r\nநபிகள் நாயகம் (ஸல்) அவர்கள் அல்லாஹ்வின் அனுமதியுடன் யூதர்களின் பேரீச்சை மரங்களை வெட்டினார்கள்\n\r\n\n\r\nஅல்லாஹ் கூறினான்:\n\r\n\n\r\nمَا قَطَعْتُمْ مِنْ لِينَةٍ أَوْ تَرَكْتُمُوهَا قَائِمَةً عَلَى أُصُولِهَا فَبِإِذْنِ اللَّهِ وَلِيُخْزِيَ الْفَاسِقِينَ\n\r\n\n\r\n(நீங்கள் வெட்டிய 'லீனா' (பேரீச்சை மரம்) ஆகட்டும், அல்லது அதன் தண்டுப்பகுதியுடன் அப்படியே விட்டு வைத்ததாகட்டும், அது அல்லாஹ்வின் அனுமதியுடன்தான் நடந்தது. மேலும் அது பாவிகளை இழிவுபடுத்துவதற்காகவே ஆகும்.) 'லீனா' என்பது ஒரு சிறந்த வகை பேரீச்சை மரமாகும். அபூ உபைதா அவர்கள் கூறுகையில், 'லீனா' என்பது 'அஜ்வா' மற்றும் 'பர்னீ' வகைகளைத் தவிர்த்த பிற பேரீச்சை வகைகளைக் குறிக்கும் என்கிறார்கள். இன்னும் சிலர் 'அஜ்வா' தவிர மற்ற அனைத்துப் பேரீச்சை பழங்களையும் இது குறிக்கும் என்கின்றனர். இப்னு ஜரீர் அவர்கள் இது அனைத்துப் பேரீச்சை மரங்களையும் குறிக்கும் என்றும், இதில் 'புவைரா' வகையும் அடங்கும் என்றும் முஜாஹித் கூறியதாகக் குறிப்பிடுகிறார். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பனூ நளீர் கோத்திரத்தாரை இழிவுபடுத்தவும், அவர்கள் உள்ளங்களில் அச்சத்தை உண்டாக்கவும் அவர்களின் பேரீச்சை மரங்களை வெட்ட உத்தரவிட்டார்கள். முஹம்மது பின் இஸ்ஹாக், யஸீத் பின் ரூமான், கத்தாதா மற்றும் முகாத்தில் பின் ஹய்யான் ஆகியோர் கூறுகையில்: \"பனூ நளீர் கோத்திரத்தினர் நபிகள் நாயகம் (ஸல்) அவர்களுக்கு, 'பூமியில் குழப்பம் விளைவிப்பதைத் தடுத்த நீங்கள், இப்போது ஏன் மரங்களை வெட்ட உத்தரவிட்டீர்கள்?' என்று செய்தி அனுப்பினார்கள். அப்போது அல்லாஹ் இந்த கண்ணியமிக்க வசனத்தை இறக்கினான். முஸ்லிம்கள் வெட்டிய அல்லது விட்டு வைத்த எந்தவொரு பேரீச்சை மரமும் அல்லாஹ்வின் நாட்டம் மற்றும் அனுமதியுடன்தான் செய்யப்பட்டது என்றும், அது எதிரிகளை இழிவுபடுத்துவதற்காகவே என்றும் அல்லாஹ் கூறினான்.\"\n\r\n\n\r\nமுஜாஹித் அவர்கள் கூறுகையில்: \"முஹாஜிர்களில் சிலர், பேரீச்சை மரங்களை வெட்ட வேண்டாம், அவை முஸ்லிம்களுக்குப் போர்ச் செல்வங்களாகக் கிடைக்கும் என்று கூறித் தடுத்தனர். குர்ஆன், மரங்களை வெட்டியவர்களின் செயலையும், அதனைத் தடுத்தவர்களின் செயலையும் ஒருசேர அங்கீகரித்து, எது நடந்திருந்தாலும் அது அல்லாஹ்வின் அனுமதியுடன்தான் நடந்தது என்று தெளிவுபடுத்தியது.\" நபிகள் நாயகம் (ஸல்) அவர்களிடமிருந்தும் இதே பொருளில் ஹதீஸ் அறிவிக்கப்பட்டுள்ளது. அன்-நஸாயீ அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"(மரங்களை வெட்டியதால்) அவர்கள் தங்கள் கோட்டைகளிலிருந்து கீழே இறங்க நிர்பந்திக்கப்பட்டனர். அப்போது முஸ்லிம்கள் தயக்கம் காட்டி, 'நாங்கள் சிலவற்றை வெட்டினோம், சிலவற்றை விட்டுவிட்டோம். வெட்டியதற்கு நற்கூலி கிடைக்குமா? அல்லது விட்டுவிட்டதற்குப் பாவம் சேருமா?' என்று நபிகள் நாயகம் (ஸல்) அவர்களிடம் கேட்டனர். அப்போது அல்லாஹ் இந்த வசனத்தை இறக்கினான்:\n\r\n\n\r\nمَا قَطَعْتُمْ مِنْ لِينَةٍ أَوْ تَرَكْتُمُوهَا قَائِمَةً عَلَى أُصُولِهَا فَبِإِذْنِ اللَّهِ\n\r\n\n\r\n(நீங்கள் வெட்டிய பேரீச்சை மரங்களாகட்டும் அல்லது அப்படியே விட்டதாகட்டும், அது அல்லாஹ்வின் அனுமதியுடன்தான் நடந்தது).\" இமாம் அஹ்மத் அவர்கள் இப்னு உமர் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"நபிகள் நாயகம் (ஸல்) அவர்கள் பனூ நளீர் கோத்திரத்தாரின் பேரீச்சை மரங்களை வெட்டி எரிக்க உத்தரவிட்டார்கள்.\" புகாரி மற்றும் முஸ்லிம் ஆகிய இரு நூல்களிலும் இதே போன்ற அறிவிப்பு உள்ளது. புகாரி அவர்கள் இப்னு உமர் (ரழி) வழியாகப் பதிவு செய்துள்ளதாவது: \"பனூ நளீர் மற்றும் பனூ குறைழா (நபிகள் நாயகத்திற்கு எதிராக) போரிட்டனர். நபிகள் நாயகம் (ஸல்) அவர்கள் பனூ நளீர் கூட்டத்தினரை நாடு கடத்தினார்கள். பனூ குறைழா கூட்டத்தினரை அங்கே இருக்க அனுமதித்தார்கள். பின்னர் குறைழா கூட்டத்தினருடன் போர் நடந்தபோது அவர்களின் ஆண்கள் கொல்லப்பட்டனர், பெண்கள் மற்றும் குழந்தைகள் சிறைபிடிக்கப்பட்டு சொத்துக்கள் முஸ்லிம்களுக்குப் பங்கிடப்பட்டன. அவர்களில் சிலர் நபிகள் நாயகம் (ஸல்) அவர்களிடம் தஞ்சம் புகுந்து இஸ்லாத்தை ஏற்றுத் தப்பித்துக் கொண்டனர். மதீனாவிலிருந்த பனூ கைனுகா, அப்துல்லாஹ் பின் ஸலாம் (ரழி) அவர்களின் கோத்திரம், பனூ ஹாரிதா உள்ளிட்ட அனைத்து யூதக் கூட்டத்தினரும் மதீனாவிலிருந்து வெளியேற்றப்பட்டனர்.\"\n\r\n\n\r\nஇரு ஸஹீஹ் நூல்களிலும் இப்னு உமர் (ரழி) அவர்கள் அறிவித்துள்ளதாவது: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பனூ நளீர் கோத்திரத்தாரின் 'அல்-புவைரா' என்ற இடத்திலுள்ள பேரீச்சை மரங்களை வெட்டி எரித்தார்கள்.\" அப்போது கண்ணியமிக்க அல்லாஹ் இந்த வசனத்தை இறக்கினான்:\n\r\n\n\r\nمَا قَطَعْتُمْ مِنْ لِينَةٍ أَوْ تَرَكْتُمُوهَا قَائِمَةً عَلَى أُصُولِهَا فَبِإِذْنِ اللَّهِ وَلِيُخْزِيَ الْفَاسِقِينَ\n\r\n\n\r\n(நீங்கள் வெட்டிய 'லீனா' (பேரீச்சை மரம்) ஆகட்டும், அல்லது அதன் தண்டுப்பகுதியுடன் அப்படியே விட்டு வைத்ததாகட்டும், அது அல்லாஹ்வின் அனுமதியுடன்தான் நடந்தது. மேலும் அது பாவிகளை இழிவுபடுத்துவதற்காகவே ஆகும்.)\" முஹம்மது பின் இஸ்ஹாக் கூறுகையில், பனூ நளீர் போர் உஹுத் மற்றும் பிஃரு மஊனா சம்பவங்களுக்குப் பிறகு நடந்தது என்று குறிப்பிடுகிறார்."},"6":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=59&ayah=7\" class=\"link\">59:7</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 59:7 ஐ பார்க்கவும்"},"7":{"html":"<strong>ஃபய் மற்றும் அது செலவிடப்படும் முறை</strong><br />\r\n<br />\r\nஉயர்ந்தோனாகிய அல்லாஹ் ‘ஃபய்’ (Fai') -க்கான சட்டங்களை விளக்குகிறான். ஃபய் என்பது முஸ்லிம்கள் நிராகரிப்பாளர்களுடன் போரிடாமலோ அல்லது குதிரைப்படை மற்றும் ஒட்டகப்படையைப் பயன்படுத்தாமலோ அவர்களிடமிருந்து ஈட்டும் போர்ச்செல்வமாகும். உதாரணமாக, பனூ அந்-நதீர் கோத்திரத்தாரிடமிருந்து பெறப்பட்ட போர்ச்செல்வம், குதிரைகளையோ ஒட்டகங்களையோ கொண்டு போரிட்டுப் பெறப்படவில்லை. முஸ்லிம்கள் பனூ அந்-நதீர் கோத்திரத்தாருடன் நேரடியாகப் போரிடவில்லை. மாறாக, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மீது அல்லாஹ் அவர்களின் உள்ளங்களில் ஏற்படுத்திய அச்சத்தின் காரணமாக, அவர்களை அவர்களின் கோட்டைகளிலிருந்து வெளியேறுமாறு அல்லாஹ் செய்தான். எனவே, அது அல்லாஹ் தனது தூதருக்கு (ஸல்) வழங்கிய 'ஃபய்' ஆகும். அதனைத் தாம் விரும்பிய நல்வழிகளில் செலவிடும் அதிகாரம் அவருக்கு வழங்கப்பட்டது. நிச்சயமாக, நபி (ஸல்) அவர்கள் அந்த ஃபய் செல்வத்தை நற்காரியங்களுக்காகவும், இந்த வசனத்தில் அல்லாஹ் குறிப்பிட்டுள்ளவாறு முஸ்லிம்களின் நலனுக்காகவும் செலவிட்டார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">أَفَاءَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">رَسُولِهِ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span><br />\r\n<br />\r\n(அவர்களிடமிருந்து தனது தூதருக்கு அல்லாஹ் ‘ஃபய்’ ஆக எதை வழங்கினானோ...) அதாவது, பனூ அந்-நதீர் கோத்திரத்தாரிடமிருந்து வழங்கியவை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَمَا</span> <span class=\"quran-arabic-font text-success\">أَوْجَفْتُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">خَيْلٍ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">رِكَابٍ</span><br />\r\n<br />\r\n(அதற்காக நீங்கள் குதிரைகளையோ ஒட்டகங்களையோ ஓட்டிச் செல்லவில்லை.) இது ஒட்டகங்களைப் பயன்படுத்துவதைக் குறிக்கிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَكِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">يُسَلِّطُ</span> <span class=\"quran-arabic-font text-success\">رُسُلَهُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">يَشَاءُ</span> <span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">قَدِيرٌ</span><br />\r\n<br />\r\n(ஆனால், அல்லாஹ் தான் நாடியவர்கள் மீது தனது தூதர்களுக்கு ஆதிக்கம் அளிக்கிறான். மேலும், அல்லாஹ் அனைத்துப் பொருட்கள் மீதும் பேராற்றல் உடையவன்.) இதன் பொருள், அல்லாஹ் மிக வல்லமையுள்ளவன், அவனை எவராலும் எதிர்க்கவோ முறியடிக்கவோ முடியாது; அவன் அனைத்துப் பொருட்கள் மீதும் அதிகாரம் செலுத்துபவன். உயர்ந்தோனாகிய அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">أَفَاءَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">رَسُولِهِ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">الْقُرَى</span><br />\r\n<br />\r\n(பல்வேறு ஊர் மக்களிடமிருந்து அல்லாஹ் தனது தூதருக்கு ‘ஃபய்’ ஆக எதைக் கொடுத்தானோ...) அதாவது, இம்முறையில் கைப்பற்றப்படும் அனைத்துக் கிராமங்கள் மற்றும் பகுதிகளிலிருந்து பெறப்படும் செல்வங்கள்; பனூ அந்-நதீர் கோத்திரத்தாரிடமிருந்து பெறப்பட்ட அதே சட்ட திட்டங்களுக்கு உட்பட்டதே ஆகும். இதனால்தான் உயர்ந்தோனாகிய அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلِلَّهِ</span> <span class=\"quran-arabic-font text-success\">وَلِلرَّسُولِ</span> <span class=\"quran-arabic-font text-success\">وَلِذِي</span> <span class=\"quran-arabic-font text-success\">الْقُرْبَى</span> <span class=\"quran-arabic-font text-success\">وَالْيَتَامَى</span> <span class=\"quran-arabic-font text-success\">وَالْمَسَاكِينِ</span> <span class=\"quran-arabic-font text-success\">وَابْنِ</span> <span class=\"quran-arabic-font text-success\">السَّبِيلِ</span><br />\r\n<br />\r\n(அது அல்லாஹ்வுக்கும், அவனுடைய தூதருக்கும், (அவருடைய) உறவினர்களுக்கும், அனாதைகளுக்கும், ஏழைகளுக்கும், வழிப்போக்கர்களுக்கும் உரியதாகும்...) இது அந்த வசனத்தின் இறுதி வரையிலும், ஃபய் எவ்வாறு செலவிடப்பட வேண்டும் என்பதைக் குறிப்பிடும் அடுத்த வசனம் வரையிலும் தொடர்கிறது. <br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள், உமர் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"பனூ அந்-நதீர் கோத்திரத்தாரின் செல்வம் அல்லாஹ் தனது தூதருக்கு (ஸல்) வழங்கிய 'ஃபய்' வகையைச் சேர்ந்தது. அதற்காக முஸ்லிம்கள் குதிரைப்படையையோ ஒட்டகப்படையையோ பயன்படுத்தத் தேவையில்லை. எனவே, அது அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்கே உரியதாக இருந்தது. அவர்கள் அதைத் தமது குடும்பத்தின் ஓராண்டுத் தேவைக்காகப் பயன்படுத்தினார்கள். மீதமுள்ளவற்றை உயர்ந்தோனும் கண்ணியமிக்கோனுமாகிய அல்லாஹ்வின் பாதையில் பயன்படுத்தப்படும் கவசங்கள் மற்றும் ஆயுதங்களை வாங்கப் பயன்படுத்தினார்கள்.\" அஹ்மத் அவர்கள் இந்தச் சம்பவத்தைச் சுருக்கமாகப் பதிவு செய்துள்ளார்கள். இப்னு மாஜாவைத் தவிர ஏனைய ஹதீஸ் தொகுப்பாளர்கள் (ஜமாஅத்) இந்த ஹதீஸைப் பதிவு செய்துள்ளனர். <br />\r\n<br />\r\nஅபூ தாவூத் அவர்கள் மாலிக் பின் அவ்ஸ் (ரழி) அவர்கள் வாயிலாகப் பதிவு செய்துள்ளார்கள்: \"நான் வீட்டில் இருந்தபோது, சூரியன் உச்சிக்கு வந்து வெப்பம் அதிகரித்தது. திடீரென்று உமர் பின் அல்-கத்தாப் (ரழி) அவர்களின் தூதுவர் என்னிடம் வந்தார். நான் அவருடன் சென்று, மெத்தை ஏதுமின்றி பேரீச்சை ஓலைகளால் செய்யப்பட்ட கட்டிலில் உமர் (ரழி) அவர்கள் அமர்ந்திருந்த இடத்திற்குள் நுழைந்தேன். நான் உள்ளே சென்றபோது அவர்கள், 'மாலிக்கே! உங்கள் சமூகத்தைச் சேர்ந்த சில குடும்பத்தினர் பஞ்சத்தின் காரணமாக என்னிடம் வந்துள்ளனர். அவர்களுக்கு நிவாரண உதவி வழங்க நான் உத்தரவிட்டுள்ளேன். எனவே, அதனைப் பெற்று அவர்களுக்குப் பங்கிட்டுக் கொடுங்கள்' என்றார்கள். அதற்கு நான், 'இப்பணியைச் செய்ய வேறு எவருக்காவது நீங்கள் உத்தரவிடக்கூடாதா?' எனக் கேட்டேன். அவர்கள், 'நீரே இதனைப் பெற்றுக்கொள்ளும்' என்றார்கள். பின்னர் யர்ஃபா (உமர் (ரழி) அவர்களின் பணியாளர்) வந்து, 'அமீருல் மூமினீன் அவர்களே! உஸ்மான் பின் அஃப்பான் (ரழி), அப்துர்-ரஹ்மான் பின் அவ்ஃப் (ரழி), அஸ்-ஸுபைர் பின் அல்-அவ்வாம் (ரழி) மற்றும் ஸஅத் பின் அபீ வக்காஸ் (ரழி) ஆகியோரை உள்ளே அனுமதிக்கலாமா?' எனக் கேட்டார். உமர் (ரழி) அவர்கள் 'ஆம்' என அனுமதி அளிக்க, அவர்களும் உள்ளே வந்தனர். சிறிது நேரத்திற்குப் பிறகு யர்ஃபா மீண்டும் வந்து, 'அமீருல் மூமினீன் அவர்களே! அல்-அப்பாஸ் (ரழி) மற்றும் அலீ (ரழி) ஆகியோரை அனுமதிக்கலாமா?' எனக் கேட்க, உமர் (ரழி) அவர்கள் 'ஆம்' என்றார்கள். அவர்களும் உள்ளே அனுமதிக்கப்பட்டனர். அப்போது அல்-அப்பாஸ் (ரழி) அவர்கள், 'இறைநம்பிக்கையாளர்களின் தலைவரே! எனக்கும் இவருக்கும் (அலீ (ரழி)) இடையே தீர்ப்பளியுங்கள்' என்றார். அங்கிருந்த குழுவினர் (உஸ்மான் (ரழி) மற்றும் அவரது தோழர்கள்), 'இறைநம்பிக்கையாளர்களின் தலைவரே! இவர்களுக்குள் தீர்ப்பளித்து, இருவரையும் ஒருவருக்கொருவர் விடுவியுங்கள்' என்றனர். இந்த நோக்கத்திற்காகவே அவர்கள் அந்த நான்கு பேரையும் தங்களுக்கு முன்பாக வரச் சொன்னார்கள் என்று நான் (மாலிக் பின் அவ்ஸ்) நினைத்தேன். உமர் (ரழி) அவர்கள், 'பொறுமையாக இருங்கள்!' என்றார்கள். <br />\r\n<br />\r\nபிறகு அவர்கள் அந்தக் குழுவினரிடம் (உஸ்மான் (ரழி) மற்றும் அவரது தோழர்களிடம்), 'எவருடைய அனுமதியால் வானமும் பூமியும் நிலைபெற்றுள்ளனவோ, அந்த அல்லாஹ்வின் மீது ஆணையாக உங்களிடம் கேட்கிறேன், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இவ்வாறு கூறியது உங்களுக்குத் தெரியுமா?<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">نُورَثُ،</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَرَكْنَا</span> <span class=\"quran-arabic-font text-success\">صَدَقَة</span>»<br />\r\n<br />\r\n(எங்களுக்கு வாரிசுரிமை கிடையாது; நாங்கள் விட்டுச் செல்பவை அனைத்தும் தர்மமாகும்.)' அந்தக் குழுவினர், 'ஆம், அவர்கள் (ஸல்) அவ்வாறு கூறினார்கள்' என்றனர். பிறகு உமர் (ரழி) அவர்கள் அலீ (ரழி) மற்றும் அல்-அப்பாஸ் (ரழி) பக்கம் திரும்பி, 'எவருடைய அனுமதியால் வானமும் பூமியும் நிலைபெற்றுள்ளனவோ, அந்த அல்லாஹ்வின் மீது ஆணையாக உங்கள் இருவரிடமும் கேட்கிறேன், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இவ்வாறு கூறியது உங்கள் இருவருக்கும் தெரியுமா?<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">نُورَثُ،</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَرَكْنَا</span> <span class=\"quran-arabic-font text-success\">صَدَقَة</span>»<br />\r\n<br />\r\n(எங்களுக்கு வாரிசுரிமை கிடையாது; நாங்கள் விட்டுச் செல்பவை அனைத்தும் தர்மமாகும்.)' அவர்கள் இருவரும், 'ஆம், அவர்கள் (ஸல்) அவ்வாறு கூறினார்கள்' என்று பதிலளித்தனர். <br />\r\n<br />\r\nபிறகு உமர் (ரழி) அவர்கள் கூறினார்கள்: 'அல்லாஹ் மற்ற எவருக்கும் வழங்காத ஒரு தனிச்சிறப்பைத் தனது தூதருக்கு (ஸல்) வழங்கினான். உயர்ந்தோனாகிய அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">أَفَاءَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">رَسُولِهِ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">فَمَا</span> <span class=\"quran-arabic-font text-success\">أَوْجَفْتُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">خَيْلٍ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">رِكَابٍ</span> <span class=\"quran-arabic-font text-success\">وَلَكِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">يُسَلِّطُ</span> <span class=\"quran-arabic-font text-success\">رُسُلَهُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">يَشَاءُ</span> <span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">قَدِيرٌ</span><br />\r\n<br />\r\n(அவர்களிடமிருந்து அல்லாஹ் தனது தூதருக்கு (ஃபய்யாக) கொடுத்த செல்வம் - அதற்காக நீங்கள் குதிரைகளையோ, ஒட்டகங்களையோ ஓட்டிச் செல்லவில்லை. ஆனால், அல்லாஹ் தான் நாடியவர் மீது தனது தூதர்களுக்கு ஆதிக்கம் செலுத்துகிறான். மேலும், அல்லாஹ் அனைத்துப் பொருட்களின் மீதும் ஆற்றலுடையவன்.) எனவே, பனூ அந்-நதீர் கோத்திரத்தாரிடமிருந்து சேகரிக்கப்பட்ட இந்தச் சொத்து, குறிப்பாக அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்கு வழங்கப்பட்டது. அல்லாஹ்வின் மீது ஆணையாக, அவர்கள் (ஸல்) உங்களை விடுத்து அதனைத் தமதாக்கிக் கொள்ளவோ, அல்லது உங்களைப் புறக்கணித்துத் தமக்கு மட்டும் சாதகமாக்கிக் கொள்ளவோ இல்லை. அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அதிலிருந்து தமக்கும் தம் குடும்பத்தாருக்கும் ஓராண்டுக்கான செலவுகளை எடுத்துக் கொண்டு, மீதமுள்ளதை முஸ்லிம்களின் பொதுக் கருவூலத்தில் (பைத்துல் மால்) விட்டுவிட்டார்கள்.' பிறகு உமர் (ரழி) அவர்கள் அங்கிருந்த குழுவினரிடம், 'அல்லாஹ்வின் மீது ஆணையாகக் கேட்கிறேன், இது உங்களுக்குத் தெரியுமா?' எனக் கேட்டார்கள். அவர்கள், 'ஆம்' என்றனர். பின்னர் அலீ (ரழி) மற்றும் அல்-அப்பாஸ் (ரழி) ஆகியோரிடம், 'அல்லாஹ்வின் மீது ஆணையாகக் கேட்கிறேன், இது உங்களுக்குத் தெரியுமா?' என வினவ, அவர்களும் 'ஆம்' என்றனர். <br />\r\n<br />\r\nஉமர் (ரழி) அவர்கள் மேலும் கூறினார்கள்: 'அல்லாஹ் தனது நபியைத் தன்னிடம் அழைத்துக் கொண்டபோது, அபூபக்ர் (ரழி) அவர்கள், 'நான் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் பிரதிநிதி (கலீஃபா)!' என்றார்கள். அப்போது நீங்கள் இருவரும் அபூபக்ர் (ரழி) அவர்களிடம் வந்து, உமது (அல்-அப்பாஸ் (ரழி)) சகோதரர் மகனிடமிருந்து உமது வாரிசுரிமைப் பங்கையும், இவர் (அலீ (ரழி)) தமது மனைவியின் தந்தைவழி வாரிசுரிமைப் பங்கையும் கேட்டீர்கள். அப்போது அபூபக்ர் (ரழி) அவர்கள், 'அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">نُورَثُ،</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَرَكْنَا</span> <span class=\"quran-arabic-font text-success\">صَدَقَة</span>»<br />\r\n<br />\r\n(எங்களுக்கு வாரிசுரிமை கிடையாது; நாங்கள் விட்டுச் செல்பவை அனைத்தும் தர்மமாகும்) என்று கூறினார்கள்' எனக் குறிப்பிட்டார்கள். அபூபக்ர் (ரழி) அவர்கள் உண்மையாளராகவும், இறையச்சமுடையவராகவும், நேர்வழி பெற்றவராகவும், சத்தியத்தைப் பின்பற்றுபவராகவும் இருந்தார் என்பதை அல்லாஹ் அறிவான். எனவே, அபூபக்ர் (ரழி) அவர்கள் அந்தச் சொத்தின் பொறுப்பை ஏற்று நிர்வகித்தார்கள். அபூபக்ர் (ரழி) அவர்கள் மறைந்த பிறகு, 'நான் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் பிரதிநிதியாகவும், அபூபக்ர் (ரழி) அவர்களின் பிரதிநிதியாகவும் இருக்கிறேன்' என்று கூறி, அல்லாஹ் நாடிய காலம் வரை அதனை நான் நிர்வகித்தேன். <br />\r\n<br />\r\nபின்னர் நீங்கள் இருவரும் (அலீ (ரழி) மற்றும் அல்-அப்பாஸ் (ரழி)) அதே கோரிக்கையுடன் அந்தச் சொத்தைக் கேட்டு என்னிடம் வந்தீர்கள். அப்போது நான் உங்களிடம், 'நீங்கள் விரும்பினால் இந்தச் சொத்தை உங்களிடம் ஒப்படைக்கத் தயாராக இருக்கிறேன்; ஆனால், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் எவ்வாறு நிர்வகித்தார்களோ அதே போன்று நீங்களும் நிர்வகிப்பீர்கள் என்று அல்லாஹ்வின் மீது உறுதிமொழி அளிக்க வேண்டும்' என்ற நிபந்தனையுடன் ஒப்படைத்தேன். நீங்கள் இருவரும் அதற்கு உடன்பட்டீர்கள், நானும் அதனை உங்களிடம் ஒப்படைத்தேன். இப்போது, நான் முன்பு வழங்கிய முடிவிற்கு மாற்றமான வேறொரு தீர்ப்பை வழங்குமாறு என்னிடம் வருகிறீர்கள். அல்லாஹ்வின் மீது ஆணையாக, இறுதி நாள் வரும் வரை நான் ஏற்கனவே வழங்கிய தீர்ப்பைத் தவிர வேறு எதனையும் வழங்க மாட்டேன். உங்களால் அதனை நிர்வகிக்க இயலாவிட்டால், அதனை என்னிடமே திருப்பித் தந்துவிடுங்கள், உங்கள் சார்பாக நானே அதனை நிர்வகிப்பேன்' என்று கூறினார்கள்.\" இதனை அஸ்-ஸுஹ்ரி அவர்களின் ஹதீஸிலிருந்து அவர்கள் பதிவு செய்துள்ளனர். <br />\r\n<br />\r\nஅல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَيْ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَكُونَ</span> <span class=\"quran-arabic-font text-success\">دُولَةً</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">الْأَغْنِيَاءِ</span> <span class=\"quran-arabic-font text-success\">مِنكُمْ</span><br />\r\n<br />\r\n(அது உங்களில் உள்ள செல்வந்தர்களிடையே மட்டுமே சுற்றிக் கொண்டிருக்கும் ஒன்றாக ஆகிவிடக் கூடாது என்பதற்காக.) இதன் பொருள், 'ஃபய் செல்வத்திற்கான செலவினங்களை நாம் இவ்வாறு அமைத்ததற்குக் காரணம், செல்வம் செல்வந்தர்களிடையே மட்டுமே தங்கிவிடக் கூடாது என்பதற்காகவே ஆகும்; இல்லையெனில் அவர்கள் தங்கள் இச்சைப்படி அதனைச் செலவிடுவார்களே ஒழிய ஏழைகளுக்கு எதனையும் வழங்கமாட்டார்கள்.'<br />\r\n<br />\r\n<strong>அனைத்துக் கட்டளைகளிலும் விலக்கல்களிலும் தூதருக்குக் கீழ்ப்படியுமாறு ஏவுதல்</strong><br />\r\n<br />\r\nஉயர்ந்தோனாகிய அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">آتَاكُمُ</span> <span class=\"quran-arabic-font text-success\">الرَّسُولُ</span> <span class=\"quran-arabic-font text-success\">فَخُذُوهُ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">نَهَاكُمْ</span> <span class=\"quran-arabic-font text-success\">عَنْهُ</span> <span class=\"quran-arabic-font text-success\">فَانتَهُوا</span><br />\r\n<br />\r\n(இன்னும், தூதர் உங்களுக்கு எதைக் கொடுக்கிறாரோ அதை எடுத்துக் கொள்ளுங்கள்; எதை விட்டும் உங்களைத் தடுக்கிறாரோ அதிலிருந்து விலகிக் கொள்ளுங்கள்.) இதன் பொருள், 'தூதர் உங்களுக்கு எதை ஏவுகிறாரோ அதனைச் செய்யுங்கள்; எதைத் தடுத்தாரோ அதனைத் தவிர்த்துக் கொள்ளுங்கள். நிச்சயமாக அவர் நன்மையை மட்டுமே ஏவுவார், தீமையை மட்டுமே தடுப்பார்.' <br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள், அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: «<span class=\"quran-arabic-font text-success\">لَعَنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">الْوَاشِمَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالْمُسْتَوْشِمَاتِ،</span> <span class=\"quran-arabic-font text-success\">وَالْمُتَنَمِّصَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالْمُتَفَلِّجَاتِ</span> <span class=\"quran-arabic-font text-success\">لِلْحُسْنِ،</span> <span class=\"quran-arabic-font text-success\">الْمُغَيِّرَاتِ</span> <span class=\"quran-arabic-font text-success\">خَلْقَ</span> <span class=\"quran-arabic-font text-success\">اللَّه</span>» \"பச்சை குத்தும் பெண்கள், பச்சை குத்திக் கொள்ளும் பெண்கள், புருவ முடிகளை அகற்றும் பெண்கள், அழகிற்காகப் பற்களுக்கு இடையே செயற்கையான இடைவெளிகளை உருவாக்கிக் கொள்ளும் பெண்கள் ஆகியோரை அல்லாஹ் சபிக்கிறான்; இவர்கள் அல்லாஹ்வின் படைப்பை மாற்றுகிறார்கள்.\" இக்கூற்று பனூ அஸத் கோத்திரத்தைச் சேர்ந்த உம்மு யஅகூப் என்ற பெண்ணுக்கு எட்டியது. அவர் அப்துல்லாஹ் (ரழி) அவர்களிடம் வந்து, \"நீங்கள் இன்னின்ன பெண்களைச் சபித்ததாக எனக்குச் செய்தி கிடைத்தது\" என்றார். அதற்கு அவர், \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் யாரைச் சபித்தார்களோ அவர்களையும், அல்லாஹ்வின் வேதத்தில் சபிக்கப்பட்டவர்களையும் நான் ஏன் சபிக்கக் கூடாது?\" என்று கேட்டார்கள். உம்மு யஅகூப், \"நான் குர்ஆன் முழுவதையும் ஓதியுள்ளேன், ஆனால் நீங்கள் கூறுவதை அதில் எங்கும் காணவில்லையே!\" என்றார். அதற்கு அப்துல்லாஹ் (ரழி), \"நிச்சயமாக நீர் குர்ஆனை (ஆழ்ந்து) ஓதியிருந்தால் அதைக் கண்டிருப்பீர். நீர் இதனை ஓதவில்லையா:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">آتَاكُمُ</span> <span class=\"quran-arabic-font text-success\">الرَّسُولُ</span> <span class=\"quran-arabic-font text-success\">فَخُذُوهُ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">نَهَاكُمْ</span> <span class=\"quran-arabic-font text-success\">عَنْهُ</span> <span class=\"quran-arabic-font text-success\">فَانتَهُوا</span><br />\r\n<br />\r\n(தூதர் உங்களுக்கு எதைக் கொடுக்கிறாரோ அதை எடுத்துக் கொள்ளுங்கள்; எதை விட்டும் உங்களைத் தடுக்கிறாரோ அதிலிருந்து விலகிக் கொள்ளுங்கள்.)\" அதற்கு அவர், \"ஆம், ஓதியிருக்கிறேன்\" என்றார். அப்துல்லாஹ் (ரழி), \"நிச்சயமாக அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இத்தகைய காரியங்களைத் தடை செய்துள்ளார்கள்\" என்றார்கள். அப்பெண்மணி, \"ஆனால் உங்கள் மனைவியே இக்காரியங்களைச் செய்கிறார் என்று நான் நினைக்கிறேன்\" என்றார். அவர், \"நீரே சென்று அவரைப் பாரும்\" என்றார். அப்பெண்மணி சென்று பார்த்தபோது அத்தகைய எதனையும் காணவில்லை. அவர் அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்களிடம் திரும்பி வந்து, அங்கே எதனையும் காணவில்லை என்று கூறினார். அதற்கு அவர், \"என் மனைவி நீர் நினைப்பது போல் இருந்திருந்தால், அவரை நான் என்னுடன் வைத்திருக்க மாட்டேன்\" என்றார்கள். புகாரி மற்றும் முஸ்லிம் ஆகிய இரு நூல்களிலும் சுஃப்யான் அஸ்-ஸவ்ரி அவர்களின் ஹதீஸாக இது இடம்பெற்றுள்ளது. <br />\r\n<br />\r\nஅதேபோல் அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிக்கும் ஹதீஸில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியுள்ளார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">أَمَرْتُكُمْ</span> <span class=\"quran-arabic-font text-success\">بِأَمْرٍ</span> <span class=\"quran-arabic-font text-success\">فَائْتُوا</span> <span class=\"quran-arabic-font text-success\">مِنْهُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">اسْتَطَعْتُمْ،</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">نَهَيْتُكُمْ</span> <span class=\"quran-arabic-font text-success\">عَنْهُ</span> <span class=\"quran-arabic-font text-success\">فَاجْتَنِبُوه</span>»<br />\r\n<br />\r\n(நான் உங்களுக்கு ஒரு காரியத்தை ஏவினால், உங்களால் முடிந்தவரை அதனைச் செய்யுங்கள். நான் உங்களுக்கு எதனையாவது தடுத்தால், அதனை முற்றிலுமாகத் தவிர்த்துக் கொள்ளுங்கள்.) <br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاتَّقُوا</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">شَدِيدُ</span> <span class=\"quran-arabic-font text-success\">الْعِقَابِ</span><br />\r\n<br />\r\n(அல்லாஹ்வுக்கு அஞ்சுங்கள்; நிச்சயமாக அல்லாஹ் தண்டிப்பதில் கடுமையானவன்.) இதன் பொருள், அல்லாஹ்வின் கட்டளைகளுக்குக் கீழ்ப்படிந்து, அவனது விலக்கல்களிலிருந்து விலகி இருப்பதன் மூலம் அல்லாஹ்விடம் தக்வா (இறையச்சம்) கொள்ளுதல். நிச்சயமாக அல்லாஹ், தனக்கு மாறு செய்பவர்களையும், தனது கட்டளைகளை நிராகரித்துப் புறக்கணிப்பவர்களையும், தான் தடுத்த காரியங்களைச் செய்பவர்களையும் தண்டிப்பதில் மிகக் கடுமையானவன்.<br />\r\n<br />","text":"ஃபய் மற்றும் அது செலவிடப்படும் முறை\n\r\n\n\r\nஉயர்ந்தோனாகிய அல்லாஹ் ‘ஃபய்’ (Fai') -க்கான சட்டங்களை விளக்குகிறான். ஃபய் என்பது முஸ்லிம்கள் நிராகரிப்பாளர்களுடன் போரிடாமலோ அல்லது குதிரைப்படை மற்றும் ஒட்டகப்படையைப் பயன்படுத்தாமலோ அவர்களிடமிருந்து ஈட்டும் போர்ச்செல்வமாகும். உதாரணமாக, பனூ அந்-நதீர் கோத்திரத்தாரிடமிருந்து பெறப்பட்ட போர்ச்செல்வம், குதிரைகளையோ ஒட்டகங்களையோ கொண்டு போரிட்டுப் பெறப்படவில்லை. முஸ்லிம்கள் பனூ அந்-நதீர் கோத்திரத்தாருடன் நேரடியாகப் போரிடவில்லை. மாறாக, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மீது அல்லாஹ் அவர்களின் உள்ளங்களில் ஏற்படுத்திய அச்சத்தின் காரணமாக, அவர்களை அவர்களின் கோட்டைகளிலிருந்து வெளியேறுமாறு அல்லாஹ் செய்தான். எனவே, அது அல்லாஹ் தனது தூதருக்கு (ஸல்) வழங்கிய 'ஃபய்' ஆகும். அதனைத் தாம் விரும்பிய நல்வழிகளில் செலவிடும் அதிகாரம் அவருக்கு வழங்கப்பட்டது. நிச்சயமாக, நபி (ஸல்) அவர்கள் அந்த ஃபய் செல்வத்தை நற்காரியங்களுக்காகவும், இந்த வசனத்தில் அல்லாஹ் குறிப்பிட்டுள்ளவாறு முஸ்லிம்களின் நலனுக்காகவும் செலவிட்டார்கள்.\n\r\n\n\r\nوَمَا أَفَاءَ اللَّهُ عَلَى رَسُولِهِ مِنْهُمْ\n\r\n\n\r\n(அவர்களிடமிருந்து தனது தூதருக்கு அல்லாஹ் ‘ஃபய்’ ஆக எதை வழங்கினானோ...) அதாவது, பனூ அந்-நதீர் கோத்திரத்தாரிடமிருந்து வழங்கியவை.\n\r\n\n\r\nفَمَا أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلٍ وَلَا رِكَابٍ\n\r\n\n\r\n(அதற்காக நீங்கள் குதிரைகளையோ ஒட்டகங்களையோ ஓட்டிச் செல்லவில்லை.) இது ஒட்டகங்களைப் பயன்படுத்துவதைக் குறிக்கிறது.\n\r\n\n\r\nوَلَكِنَّ اللَّهَ يُسَلِّطُ رُسُلَهُ عَلَى مَن يَشَاءُ وَاللَّهُ عَلَى كُلِّ شَيْءٍ قَدِيرٌ\n\r\n\n\r\n(ஆனால், அல்லாஹ் தான் நாடியவர்கள் மீது தனது தூதர்களுக்கு ஆதிக்கம் அளிக்கிறான். மேலும், அல்லாஹ் அனைத்துப் பொருட்கள் மீதும் பேராற்றல் உடையவன்.) இதன் பொருள், அல்லாஹ் மிக வல்லமையுள்ளவன், அவனை எவராலும் எதிர்க்கவோ முறியடிக்கவோ முடியாது; அவன் அனைத்துப் பொருட்கள் மீதும் அதிகாரம் செலுத்துபவன். உயர்ந்தோனாகிய அல்லாஹ் கூறினான்:\n\r\n\n\r\nمَا أَفَاءَ اللَّهُ عَلَى رَسُولِهِ مِنْ أَهْلِ الْقُرَى\n\r\n\n\r\n(பல்வேறு ஊர் மக்களிடமிருந்து அல்லாஹ் தனது தூதருக்கு ‘ஃபய்’ ஆக எதைக் கொடுத்தானோ...) அதாவது, இம்முறையில் கைப்பற்றப்படும் அனைத்துக் கிராமங்கள் மற்றும் பகுதிகளிலிருந்து பெறப்படும் செல்வங்கள்; பனூ அந்-நதீர் கோத்திரத்தாரிடமிருந்து பெறப்பட்ட அதே சட்ட திட்டங்களுக்கு உட்பட்டதே ஆகும். இதனால்தான் உயர்ந்தோனாகிய அல்லாஹ் கூறினான்:\n\r\n\n\r\nفَلِلَّهِ وَلِلرَّسُولِ وَلِذِي الْقُرْبَى وَالْيَتَامَى وَالْمَسَاكِينِ وَابْنِ السَّبِيلِ\n\r\n\n\r\n(அது அல்லாஹ்வுக்கும், அவனுடைய தூதருக்கும், (அவருடைய) உறவினர்களுக்கும், அனாதைகளுக்கும், ஏழைகளுக்கும், வழிப்போக்கர்களுக்கும் உரியதாகும்...) இது அந்த வசனத்தின் இறுதி வரையிலும், ஃபய் எவ்வாறு செலவிடப்பட வேண்டும் என்பதைக் குறிப்பிடும் அடுத்த வசனம் வரையிலும் தொடர்கிறது.\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள், உமர் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"பனூ அந்-நதீர் கோத்திரத்தாரின் செல்வம் அல்லாஹ் தனது தூதருக்கு (ஸல்) வழங்கிய 'ஃபய்' வகையைச் சேர்ந்தது. அதற்காக முஸ்லிம்கள் குதிரைப்படையையோ ஒட்டகப்படையையோ பயன்படுத்தத் தேவையில்லை. எனவே, அது அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்கே உரியதாக இருந்தது. அவர்கள் அதைத் தமது குடும்பத்தின் ஓராண்டுத் தேவைக்காகப் பயன்படுத்தினார்கள். மீதமுள்ளவற்றை உயர்ந்தோனும் கண்ணியமிக்கோனுமாகிய அல்லாஹ்வின் பாதையில் பயன்படுத்தப்படும் கவசங்கள் மற்றும் ஆயுதங்களை வாங்கப் பயன்படுத்தினார்கள்.\" அஹ்மத் அவர்கள் இந்தச் சம்பவத்தைச் சுருக்கமாகப் பதிவு செய்துள்ளார்கள். இப்னு மாஜாவைத் தவிர ஏனைய ஹதீஸ் தொகுப்பாளர்கள் (ஜமாஅத்) இந்த ஹதீஸைப் பதிவு செய்துள்ளனர்.\n\r\n\n\r\nஅபூ தாவூத் அவர்கள் மாலிக் பின் அவ்ஸ் (ரழி) அவர்கள் வாயிலாகப் பதிவு செய்துள்ளார்கள்: \"நான் வீட்டில் இருந்தபோது, சூரியன் உச்சிக்கு வந்து வெப்பம் அதிகரித்தது. திடீரென்று உமர் பின் அல்-கத்தாப் (ரழி) அவர்களின் தூதுவர் என்னிடம் வந்தார். நான் அவருடன் சென்று, மெத்தை ஏதுமின்றி பேரீச்சை ஓலைகளால் செய்யப்பட்ட கட்டிலில் உமர் (ரழி) அவர்கள் அமர்ந்திருந்த இடத்திற்குள் நுழைந்தேன். நான் உள்ளே சென்றபோது அவர்கள், 'மாலிக்கே! உங்கள் சமூகத்தைச் சேர்ந்த சில குடும்பத்தினர் பஞ்சத்தின் காரணமாக என்னிடம் வந்துள்ளனர். அவர்களுக்கு நிவாரண உதவி வழங்க நான் உத்தரவிட்டுள்ளேன். எனவே, அதனைப் பெற்று அவர்களுக்குப் பங்கிட்டுக் கொடுங்கள்' என்றார்கள். அதற்கு நான், 'இப்பணியைச் செய்ய வேறு எவருக்காவது நீங்கள் உத்தரவிடக்கூடாதா?' எனக் கேட்டேன். அவர்கள், 'நீரே இதனைப் பெற்றுக்கொள்ளும்' என்றார்கள். பின்னர் யர்ஃபா (உமர் (ரழி) அவர்களின் பணியாளர்) வந்து, 'அமீருல் மூமினீன் அவர்களே! உஸ்மான் பின் அஃப்பான் (ரழி), அப்துர்-ரஹ்மான் பின் அவ்ஃப் (ரழி), அஸ்-ஸுபைர் பின் அல்-அவ்வாம் (ரழி) மற்றும் ஸஅத் பின் அபீ வக்காஸ் (ரழி) ஆகியோரை உள்ளே அனுமதிக்கலாமா?' எனக் கேட்டார். உமர் (ரழி) அவர்கள் 'ஆம்' என அனுமதி அளிக்க, அவர்களும் உள்ளே வந்தனர். சிறிது நேரத்திற்குப் பிறகு யர்ஃபா மீண்டும் வந்து, 'அமீருல் மூமினீன் அவர்களே! அல்-அப்பாஸ் (ரழி) மற்றும் அலீ (ரழி) ஆகியோரை அனுமதிக்கலாமா?' எனக் கேட்க, உமர் (ரழி) அவர்கள் 'ஆம்' என்றார்கள். அவர்களும் உள்ளே அனுமதிக்கப்பட்டனர். அப்போது அல்-அப்பாஸ் (ரழி) அவர்கள், 'இறைநம்பிக்கையாளர்களின் தலைவரே! எனக்கும் இவருக்கும் (அலீ (ரழி)) இடையே தீர்ப்பளியுங்கள்' என்றார். அங்கிருந்த குழுவினர் (உஸ்மான் (ரழி) மற்றும் அவரது தோழர்கள்), 'இறைநம்பிக்கையாளர்களின் தலைவரே! இவர்களுக்குள் தீர்ப்பளித்து, இருவரையும் ஒருவருக்கொருவர் விடுவியுங்கள்' என்றனர். இந்த நோக்கத்திற்காகவே அவர்கள் அந்த நான்கு பேரையும் தங்களுக்கு முன்பாக வரச் சொன்னார்கள் என்று நான் (மாலிக் பின் அவ்ஸ்) நினைத்தேன். உமர் (ரழி) அவர்கள், 'பொறுமையாக இருங்கள்!' என்றார்கள்.\n\r\n\n\r\nபிறகு அவர்கள் அந்தக் குழுவினரிடம் (உஸ்மான் (ரழி) மற்றும் அவரது தோழர்களிடம்), 'எவருடைய அனுமதியால் வானமும் பூமியும் நிலைபெற்றுள்ளனவோ, அந்த அல்லாஹ்வின் மீது ஆணையாக உங்களிடம் கேட்கிறேன், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இவ்வாறு கூறியது உங்களுக்குத் தெரியுமா?\n\r\n\n\r\n«لَا نُورَثُ، مَا تَرَكْنَا صَدَقَة»\n\r\n\n\r\n(எங்களுக்கு வாரிசுரிமை கிடையாது; நாங்கள் விட்டுச் செல்பவை அனைத்தும் தர்மமாகும்.)' அந்தக் குழுவினர், 'ஆம், அவர்கள் (ஸல்) அவ்வாறு கூறினார்கள்' என்றனர். பிறகு உமர் (ரழி) அவர்கள் அலீ (ரழி) மற்றும் அல்-அப்பாஸ் (ரழி) பக்கம் திரும்பி, 'எவருடைய அனுமதியால் வானமும் பூமியும் நிலைபெற்றுள்ளனவோ, அந்த அல்லாஹ்வின் மீது ஆணையாக உங்கள் இருவரிடமும் கேட்கிறேன், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இவ்வாறு கூறியது உங்கள் இருவருக்கும் தெரியுமா?\n\r\n\n\r\n«لَا نُورَثُ، مَا تَرَكْنَا صَدَقَة»\n\r\n\n\r\n(எங்களுக்கு வாரிசுரிமை கிடையாது; நாங்கள் விட்டுச் செல்பவை அனைத்தும் தர்மமாகும்.)' அவர்கள் இருவரும், 'ஆம், அவர்கள் (ஸல்) அவ்வாறு கூறினார்கள்' என்று பதிலளித்தனர்.\n\r\n\n\r\nபிறகு உமர் (ரழி) அவர்கள் கூறினார்கள்: 'அல்லாஹ் மற்ற எவருக்கும் வழங்காத ஒரு தனிச்சிறப்பைத் தனது தூதருக்கு (ஸல்) வழங்கினான். உயர்ந்தோனாகிய அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَمَا أَفَاءَ اللَّهُ عَلَى رَسُولِهِ مِنْهُمْ فَمَا أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلٍ وَلَا رِكَابٍ وَلَكِنَّ اللَّهَ يُسَلِّطُ رُسُلَهُ عَلَى مَن يَشَاءُ وَاللَّهُ عَلَى كُلِّ شَيْءٍ قَدِيرٌ\n\r\n\n\r\n(அவர்களிடமிருந்து அல்லாஹ் தனது தூதருக்கு (ஃபய்யாக) கொடுத்த செல்வம் - அதற்காக நீங்கள் குதிரைகளையோ, ஒட்டகங்களையோ ஓட்டிச் செல்லவில்லை. ஆனால், அல்லாஹ் தான் நாடியவர் மீது தனது தூதர்களுக்கு ஆதிக்கம் செலுத்துகிறான். மேலும், அல்லாஹ் அனைத்துப் பொருட்களின் மீதும் ஆற்றலுடையவன்.) எனவே, பனூ அந்-நதீர் கோத்திரத்தாரிடமிருந்து சேகரிக்கப்பட்ட இந்தச் சொத்து, குறிப்பாக அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்கு வழங்கப்பட்டது. அல்லாஹ்வின் மீது ஆணையாக, அவர்கள் (ஸல்) உங்களை விடுத்து அதனைத் தமதாக்கிக் கொள்ளவோ, அல்லது உங்களைப் புறக்கணித்துத் தமக்கு மட்டும் சாதகமாக்கிக் கொள்ளவோ இல்லை. அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அதிலிருந்து தமக்கும் தம் குடும்பத்தாருக்கும் ஓராண்டுக்கான செலவுகளை எடுத்துக் கொண்டு, மீதமுள்ளதை முஸ்லிம்களின் பொதுக் கருவூலத்தில் (பைத்துல் மால்) விட்டுவிட்டார்கள்.' பிறகு உமர் (ரழி) அவர்கள் அங்கிருந்த குழுவினரிடம், 'அல்லாஹ்வின் மீது ஆணையாகக் கேட்கிறேன், இது உங்களுக்குத் தெரியுமா?' எனக் கேட்டார்கள். அவர்கள், 'ஆம்' என்றனர். பின்னர் அலீ (ரழி) மற்றும் அல்-அப்பாஸ் (ரழி) ஆகியோரிடம், 'அல்லாஹ்வின் மீது ஆணையாகக் கேட்கிறேன், இது உங்களுக்குத் தெரியுமா?' என வினவ, அவர்களும் 'ஆம்' என்றனர்.\n\r\n\n\r\nஉமர் (ரழி) அவர்கள் மேலும் கூறினார்கள்: 'அல்லாஹ் தனது நபியைத் தன்னிடம் அழைத்துக் கொண்டபோது, அபூபக்ர் (ரழி) அவர்கள், 'நான் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் பிரதிநிதி (கலீஃபா)!' என்றார்கள். அப்போது நீங்கள் இருவரும் அபூபக்ர் (ரழி) அவர்களிடம் வந்து, உமது (அல்-அப்பாஸ் (ரழி)) சகோதரர் மகனிடமிருந்து உமது வாரிசுரிமைப் பங்கையும், இவர் (அலீ (ரழி)) தமது மனைவியின் தந்தைவழி வாரிசுரிமைப் பங்கையும் கேட்டீர்கள். அப்போது அபூபக்ர் (ரழி) அவர்கள், 'அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்:\n\r\n\n\r\n«لَا نُورَثُ، مَا تَرَكْنَا صَدَقَة»\n\r\n\n\r\n(எங்களுக்கு வாரிசுரிமை கிடையாது; நாங்கள் விட்டுச் செல்பவை அனைத்தும் தர்மமாகும்) என்று கூறினார்கள்' எனக் குறிப்பிட்டார்கள். அபூபக்ர் (ரழி) அவர்கள் உண்மையாளராகவும், இறையச்சமுடையவராகவும், நேர்வழி பெற்றவராகவும், சத்தியத்தைப் பின்பற்றுபவராகவும் இருந்தார் என்பதை அல்லாஹ் அறிவான். எனவே, அபூபக்ர் (ரழி) அவர்கள் அந்தச் சொத்தின் பொறுப்பை ஏற்று நிர்வகித்தார்கள். அபூபக்ர் (ரழி) அவர்கள் மறைந்த பிறகு, 'நான் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் பிரதிநிதியாகவும், அபூபக்ர் (ரழி) அவர்களின் பிரதிநிதியாகவும் இருக்கிறேன்' என்று கூறி, அல்லாஹ் நாடிய காலம் வரை அதனை நான் நிர்வகித்தேன்.\n\r\n\n\r\nபின்னர் நீங்கள் இருவரும் (அலீ (ரழி) மற்றும் அல்-அப்பாஸ் (ரழி)) அதே கோரிக்கையுடன் அந்தச் சொத்தைக் கேட்டு என்னிடம் வந்தீர்கள். அப்போது நான் உங்களிடம், 'நீங்கள் விரும்பினால் இந்தச் சொத்தை உங்களிடம் ஒப்படைக்கத் தயாராக இருக்கிறேன்; ஆனால், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் எவ்வாறு நிர்வகித்தார்களோ அதே போன்று நீங்களும் நிர்வகிப்பீர்கள் என்று அல்லாஹ்வின் மீது உறுதிமொழி அளிக்க வேண்டும்' என்ற நிபந்தனையுடன் ஒப்படைத்தேன். நீங்கள் இருவரும் அதற்கு உடன்பட்டீர்கள், நானும் அதனை உங்களிடம் ஒப்படைத்தேன். இப்போது, நான் முன்பு வழங்கிய முடிவிற்கு மாற்றமான வேறொரு தீர்ப்பை வழங்குமாறு என்னிடம் வருகிறீர்கள். அல்லாஹ்வின் மீது ஆணையாக, இறுதி நாள் வரும் வரை நான் ஏற்கனவே வழங்கிய தீர்ப்பைத் தவிர வேறு எதனையும் வழங்க மாட்டேன். உங்களால் அதனை நிர்வகிக்க இயலாவிட்டால், அதனை என்னிடமே திருப்பித் தந்துவிடுங்கள், உங்கள் சார்பாக நானே அதனை நிர்வகிப்பேன்' என்று கூறினார்கள்.\" இதனை அஸ்-ஸுஹ்ரி அவர்களின் ஹதீஸிலிருந்து அவர்கள் பதிவு செய்துள்ளனர்.\n\r\n\n\r\nஅல்லாஹ் கூறினான்:\n\r\n\n\r\nكَيْ لَا يَكُونَ دُولَةً بَيْنَ الْأَغْنِيَاءِ مِنكُمْ\n\r\n\n\r\n(அது உங்களில் உள்ள செல்வந்தர்களிடையே மட்டுமே சுற்றிக் கொண்டிருக்கும் ஒன்றாக ஆகிவிடக் கூடாது என்பதற்காக.) இதன் பொருள், 'ஃபய் செல்வத்திற்கான செலவினங்களை நாம் இவ்வாறு அமைத்ததற்குக் காரணம், செல்வம் செல்வந்தர்களிடையே மட்டுமே தங்கிவிடக் கூடாது என்பதற்காகவே ஆகும்; இல்லையெனில் அவர்கள் தங்கள் இச்சைப்படி அதனைச் செலவிடுவார்களே ஒழிய ஏழைகளுக்கு எதனையும் வழங்கமாட்டார்கள்.'\n\r\n\n\r\nஅனைத்துக் கட்டளைகளிலும் விலக்கல்களிலும் தூதருக்குக் கீழ்ப்படியுமாறு ஏவுதல்\n\r\n\n\r\nஉயர்ந்தோனாகிய அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانتَهُوا\n\r\n\n\r\n(இன்னும், தூதர் உங்களுக்கு எதைக் கொடுக்கிறாரோ அதை எடுத்துக் கொள்ளுங்கள்; எதை விட்டும் உங்களைத் தடுக்கிறாரோ அதிலிருந்து விலகிக் கொள்ளுங்கள்.) இதன் பொருள், 'தூதர் உங்களுக்கு எதை ஏவுகிறாரோ அதனைச் செய்யுங்கள்; எதைத் தடுத்தாரோ அதனைத் தவிர்த்துக் கொள்ளுங்கள். நிச்சயமாக அவர் நன்மையை மட்டுமே ஏவுவார், தீமையை மட்டுமே தடுப்பார்.'\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள், அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: «لَعَنَ اللَّهُ الْوَاشِمَاتِ وَالْمُسْتَوْشِمَاتِ، وَالْمُتَنَمِّصَاتِ وَالْمُتَفَلِّجَاتِ لِلْحُسْنِ، الْمُغَيِّرَاتِ خَلْقَ اللَّه» \"பச்சை குத்தும் பெண்கள், பச்சை குத்திக் கொள்ளும் பெண்கள், புருவ முடிகளை அகற்றும் பெண்கள், அழகிற்காகப் பற்களுக்கு இடையே செயற்கையான இடைவெளிகளை உருவாக்கிக் கொள்ளும் பெண்கள் ஆகியோரை அல்லாஹ் சபிக்கிறான்; இவர்கள் அல்லாஹ்வின் படைப்பை மாற்றுகிறார்கள்.\" இக்கூற்று பனூ அஸத் கோத்திரத்தைச் சேர்ந்த உம்மு யஅகூப் என்ற பெண்ணுக்கு எட்டியது. அவர் அப்துல்லாஹ் (ரழி) அவர்களிடம் வந்து, \"நீங்கள் இன்னின்ன பெண்களைச் சபித்ததாக எனக்குச் செய்தி கிடைத்தது\" என்றார். அதற்கு அவர், \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் யாரைச் சபித்தார்களோ அவர்களையும், அல்லாஹ்வின் வேதத்தில் சபிக்கப்பட்டவர்களையும் நான் ஏன் சபிக்கக் கூடாது?\" என்று கேட்டார்கள். உம்மு யஅகூப், \"நான் குர்ஆன் முழுவதையும் ஓதியுள்ளேன், ஆனால் நீங்கள் கூறுவதை அதில் எங்கும் காணவில்லையே!\" என்றார். அதற்கு அப்துல்லாஹ் (ரழி), \"நிச்சயமாக நீர் குர்ஆனை (ஆழ்ந்து) ஓதியிருந்தால் அதைக் கண்டிருப்பீர். நீர் இதனை ஓதவில்லையா:\n\r\n\n\r\nوَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانتَهُوا\n\r\n\n\r\n(தூதர் உங்களுக்கு எதைக் கொடுக்கிறாரோ அதை எடுத்துக் கொள்ளுங்கள்; எதை விட்டும் உங்களைத் தடுக்கிறாரோ அதிலிருந்து விலகிக் கொள்ளுங்கள்.)\" அதற்கு அவர், \"ஆம், ஓதியிருக்கிறேன்\" என்றார். அப்துல்லாஹ் (ரழி), \"நிச்சயமாக அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இத்தகைய காரியங்களைத் தடை செய்துள்ளார்கள்\" என்றார்கள். அப்பெண்மணி, \"ஆனால் உங்கள் மனைவியே இக்காரியங்களைச் செய்கிறார் என்று நான் நினைக்கிறேன்\" என்றார். அவர், \"நீரே சென்று அவரைப் பாரும்\" என்றார். அப்பெண்மணி சென்று பார்த்தபோது அத்தகைய எதனையும் காணவில்லை. அவர் அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்களிடம் திரும்பி வந்து, அங்கே எதனையும் காணவில்லை என்று கூறினார். அதற்கு அவர், \"என் மனைவி நீர் நினைப்பது போல் இருந்திருந்தால், அவரை நான் என்னுடன் வைத்திருக்க மாட்டேன்\" என்றார்கள். புகாரி மற்றும் முஸ்லிம் ஆகிய இரு நூல்களிலும் சுஃப்யான் அஸ்-ஸவ்ரி அவர்களின் ஹதீஸாக இது இடம்பெற்றுள்ளது.\n\r\n\n\r\nஅதேபோல் அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிக்கும் ஹதீஸில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியுள்ளார்கள்:\n\r\n\n\r\n«إِذَا أَمَرْتُكُمْ بِأَمْرٍ فَائْتُوا مِنْهُ مَا اسْتَطَعْتُمْ، وَمَا نَهَيْتُكُمْ عَنْهُ فَاجْتَنِبُوه»\n\r\n\n\r\n(நான் உங்களுக்கு ஒரு காரியத்தை ஏவினால், உங்களால் முடிந்தவரை அதனைச் செய்யுங்கள். நான் உங்களுக்கு எதனையாவது தடுத்தால், அதனை முற்றிலுமாகத் தவிர்த்துக் கொள்ளுங்கள்.)\n\r\n\n\r\nஅல்லாஹ்வின் கூற்று:\n\r\n\n\r\nوَاتَّقُوا اللَّهَ إِنَّ اللَّهَ شَدِيدُ الْعِقَابِ\n\r\n\n\r\n(அல்லாஹ்வுக்கு அஞ்சுங்கள்; நிச்சயமாக அல்லாஹ் தண்டிப்பதில் கடுமையானவன்.) இதன் பொருள், அல்லாஹ்வின் கட்டளைகளுக்குக் கீழ்ப்படிந்து, அவனது விலக்கல்களிலிருந்து விலகி இருப்பதன் மூலம் அல்லாஹ்விடம் தக்வா (இறையச்சம்) கொள்ளுதல். நிச்சயமாக அல்லாஹ், தனக்கு மாறு செய்பவர்களையும், தனது கட்டளைகளை நிராகரித்துப் புறக்கணிப்பவர்களையும், தான் தடுத்த காரியங்களைச் செய்பவர்களையும் தண்டிப்பதில் மிகக் கடுமையானவன்."},"8":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=59&ayah=10\" class=\"link\">59:10</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 59:10 ஐ பார்க்கவும்"},"9":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=59&ayah=10\" class=\"link\">59:10</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 59:10 ஐ பார்க்கவும்"},"10":{"html":"<strong>ஃபய் நிதியைப் பெறத் தகுதியானவர்கள்; முஹாஜிர்கள் மற்றும் அன்சாரிகளின் சிறப்புகள்</strong><br />\r\n<br />\r\nஃபய் (Fai') நிதியில் பங்கு பெறத் தகுதியுள்ள ஏழை மக்களின் பிரிவுகளைப் பற்றி அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِلْفُقَرَاءِ</span> <span class=\"quran-arabic-font text-success\">الْمُهَاجِرِينَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">أُخْرِجُوا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">دِيَارِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَأَمْوَالِهِمْ</span> <span class=\"quran-arabic-font text-success\">يَبْتَغُونَ</span> <span class=\"quran-arabic-font text-success\">فَضْلاً</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَرِضْوَانًا</span><br />\r\n<br />\r\n(இப்பங்கானது) தங்கள் வீடுகளையும், தங்கள் சொத்துக்களையும் விட்டு வெளியேற்றப்பட்ட ஏழை முஹாஜிர்களுக்குரியதாகும். அவர்கள் அல்லாஹ்விடமிருந்து அருளையும் (அவனது) திருப்பொருத்தத்தையும் நாடுகின்றனர்; அதாவது, அல்லாஹ்வின் திருப்பொருத்தத்தையும் அவனது அருளையும் நாடி, தங்கள் வீடுகளை விட்டு வெளியேறி, தங்கள் உறவினர்களை எதிர்த்து நின்றவர்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَنصُرُونَ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">وَرَسُولَهُ</span> <span class=\"quran-arabic-font text-success\">أُولَئِكَ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الصَّادِقُونَ</span><br />\r\n<br />\r\n(மேலும் அல்லாஹ்வுக்கும் அவனது தூதருக்கும் உதவி செய்கிறார்கள். இவர்களே உண்மையாளர்கள்.) அதாவது, அவர்கள் சொல்லிலும் செயலிலும் உண்மையாக இருந்தவர்கள்; அவர்களே முஹாஜிர்களின் தலைவர்கள். உயர்ந்தோனாகிய அல்லாஹ் அடுத்து அன்சாரிகளைப் புகழ்ந்து, அவர்களின் சிறப்பு, அந்தஸ்து மற்றும் கண்ணியத்தை வலியுறுத்துகிறான். தங்களுக்குத் தேவையிருந்தும் பிறருக்கு முன்னுரிமை அளித்ததையும், பொறாமை கொள்ளாததையும் குறிப்பிடுகிறான். அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">تَبَوَّءُوا</span> <span class=\"quran-arabic-font text-success\">الدَّارَ</span> <span class=\"quran-arabic-font text-success\">وَالْإِيمَانَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">قَبْلِهِمْ</span><br />\r\n<br />\r\n(மேலும், அவர்களுக்கு முன்பே ஈமானை ஏற்றுக்கொண்டு, (மதீனாவைத்) தங்கள் இல்லமாகக் கொண்டவர்களுக்கும் (இதில் பங்குண்டு).) இது முஹாஜிர்கள் அங்கு வருவதற்கு முன்பே ஹிஜ்ரத் நகரமான மதீனாவில் வசித்தவர்களையும், அவர்களில் பலருக்கு முன்பே ஈமானை ஏற்றுக்கொண்டவர்களையும் குறிக்கிறது. உமர் (ரழி) அவர்கள் கூறினார்கள்: \"எனக்குப் பின் வரவிருக்கும் கலீஃபாவுக்கு நான் சில பரிந்துரைகளைச் செய்கிறேன்: முதன்மையான முஹாஜிர்களின் உரிமைகளையும் சிறப்புகளையும் அறிந்து அவர்களின் கண்ணியத்தைப் பாதுகாக்க வேண்டும். மேலும், மதீனாவில் வசித்து ஈமானை முன்கூட்டியே ஏற்றுக்கொண்ட அன்சாரிகளிடம் கனிவாக இருக்குமாறும், அவர்களில் நன்மை செய்வோரின் நற்செயல்களை ஏற்றுக்கொண்டு, தவறிழைப்பவர்களை மன்னிக்குமாறும் பரிந்துரைக்கிறேன்.\" இந்த ஹதீஸை புகாரி பதிவு செய்துள்ளார். அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يُحِبُّونَ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">هَاجَرَ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِمْ</span><br />\r\n<br />\r\n(தம்மிடம் ஹிஜ்ரத் செய்து வருபவர்களை அவர்கள் நேசிக்கிறார்கள்.) இது அவர்களின் பெருந்தன்மை மற்றும் கண்ணியமான நடத்தையைக் காட்டுகிறது; அவர்கள் முஹாஜிர்களை நேசித்ததோடு தங்கள் செல்வத்தைக் கொண்டு அவர்களுக்கு ஆறுதலும் அளித்தனர். இமாம் அஹ்மத் அவர்கள் அனஸ் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"முஹாஜிர்கள் கூறினார்கள்: 'அல்லாஹ்வின் தூதரே (ஸல்)! நாங்கள் ஹிஜ்ரத் செய்து வந்த இந்த மக்களைப் போன்ற சிறந்த மனிதர்களை நாங்கள் கண்டதில்லை. பற்றாக்குறையான நேரத்திலும் எங்களுக்கு ஆதரவளித்து, செழிப்பான நேரத்திலும் இன்முகத்துடன் எங்களுக்குப் பகிர்ந்து கொடுக்கிறார்கள். அவர்கள் எங்களின் தேவைகளைப் பூர்த்தி செய்ததோடு தங்கள் செல்வத்தையும் எங்களுடன் பகிர்ந்து கொண்டார்கள்; இதனால் எங்களின் நன்மைகள் அனைத்தையும் அவர்களே பெற்றுவிடுவார்களோ என்று நாங்கள் அஞ்சுகிறோம்.' அதற்கு நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَا،</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">أَثْنَيْتُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">وَدَعَوْتُمُ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">لَهُم</span>»<br />\r\n<br />\r\n('இல்லை, நீங்கள் அவர்களுக்கு நன்றி செலுத்தி, அவர்களுக்காக அல்லாஹ்விடம் பிரார்த்தனை செய்யும் வரை அவர்கள் மட்டுமே அந்த நன்மையைப் பெற்றுவிட மாட்டார்கள்.')\" இந்த அறிவிப்பை மற்ற நூல்களில் நான் காணவில்லை. புகாரி பதிவு செய்துள்ள ஹதீஸில், யஹ்யா பின் ஸயீத் அவர்கள் அனஸ் பின் மாலிக் (ரழி) அவர்கள் அல்-வலீதிடம் சென்றபோது கூறியதைக் கேட்டுள்ளார்: \"நபி (ஸல்) அவர்கள் அன்சாரிகளை அழைத்து பஹ்ரைன் நிலத்தை அவர்களுக்குப் பங்கிட்டுக் கொடுக்க முன்வந்தார்கள். அதற்கு அன்சாரிகள், 'எங்கள் முஹாஜிர் சகோதரர்களுக்கும் அதே போன்ற ஒரு பங்கை நீங்கள் கொடுக்கும் வரை நாங்கள் எதையும் பெற்றுக்கொள்ள மாட்டோம்' என்று கூறினார்கள். அதற்கு நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِمَّا</span> <span class=\"quran-arabic-font text-success\">لَا،</span> <span class=\"quran-arabic-font text-success\">فَاصْبِرُوا</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">تَلْقَوْنِي،</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">سَيُصِيبُكُمْ</span> <span class=\"quran-arabic-font text-success\">بَعْدِي</span> <span class=\"quran-arabic-font text-success\">أَثَرَةً</span>»<br />\r\n<br />\r\n('அப்படியென்றால், (மறுமையில்) என்னைச் சந்திக்கும் வரை பொறுமையாக இருங்கள்; ஏனெனில் எனக்குப் பிறகு மற்றவர்களுக்கு முன்னுரிமை அளிக்கப்படுவதை நீங்கள் காண்பீர்கள்.')\" இந்த அறிவிப்பு புகாரியில் மட்டுமே உள்ளது. அபூ ஹுரைரா (ரழி) அவர்கள் கூறியதாக புகாரி பதிவு செய்துள்ளார்: \"அன்சாரிகள் (நபி (ஸல்) அவர்களிடம்), 'எங்களின் பேரீச்சைத் தோப்புகளை எங்களுக்கும் எங்கள் முஹாஜிர் சகோதரர்களுக்கும் இடையில் பங்கிடுங்கள்' என்றார்கள். நபி (ஸல்) அவர்கள் 'வேண்டாம்' என்றார்கள். பிறகு அன்சாரிகள் (முஹாஜிர்களிடம்), 'அப்படியென்றால் நீங்கள் தோப்புகளைப் பராமரிக்கும் வேலையைச் செய்யுங்கள், பலனை எங்களுடன் பகிர்ந்து கொள்ளுங்கள்' என்றார்கள். முஹாஜிர்கள், 'நாங்கள் செவியேற்றோம், கீழ்ப்படிந்தோம்' என்று கூறினார்கள்.\" இதை புகாரி பதிவு செய்துள்ளார் (முஸ்லிமில் இல்லை).<br />\r\n<br />\r\n<strong>அன்சாரிகள் முஹாஜிர்கள் மீது ஒருபோதும் பொறாமை கொள்ளவில்லை</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">يَجِدُونَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">صُدُورِهِمْ</span> <span class=\"quran-arabic-font text-success\">حَاجَةً</span> <span class=\"quran-arabic-font text-success\">مِمَّا</span> <span class=\"quran-arabic-font text-success\">أُوتُوا</span><br />\r\n<br />\r\n(மேலும் அவர்களுக்கு வழங்கப்பட்டவை குறித்து இவர்கள் தங்கள் உள்ளங்களில் எந்தத் தேவையையும் (பொறாமையையும்) காணமாட்டார்கள்.) அதாவது, முஹாஜிர்களுக்கு அல்லாஹ் வழங்கிய அந்தஸ்து, தகுதி அல்லது உயர் நிலைகளைக் கண்டு அன்சாரிகள் பொறாமைப்படவில்லை. அல்லாஹ்வின் கூற்றான:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مِمَّا</span> <span class=\"quran-arabic-font text-success\">أُوتُوا</span><br />\r\n<br />\r\n(அவர்களுக்கு வழங்கப்பட்டவை) என்பது முஹாஜிர்களுக்கு அளிக்கப்பட்ட சிறப்புகளைக் குறிப்பதாக கதாதா மற்றும் இப்னு ஸைத் கூறுகின்றனர்.<br />\r\n<br />\r\n<strong>அன்சாரிகளின் தன்னலமற்ற தன்மை</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيُؤْثِرُونَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَنفُسِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">بِهِمْ</span> <span class=\"quran-arabic-font text-success\">خَصَاصَةٌ</span><br />\r\n<br />\r\n(தங்களுக்குத் தேவையிருந்த போதிலும், தங்களை விட அவர்களுக்கே முன்னுரிமை அளிக்கின்றனர்.) அதாவது, அவர்கள் தங்கள் சொந்தத் தேவைகளை விட வறியவர்களின் தேவைகளுக்கு முன்னுரிமை அளித்தார்கள்; தங்களுக்குத் தேவையிருந்தும் மற்றவர்களுக்கே முதலில் கொடுத்தார்கள். ஓர் ஆதாரப்பூர்வமான ஹதீஸில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَفْضَلُ</span> <span class=\"quran-arabic-font text-success\">الصَّدَقَةِ</span> <span class=\"quran-arabic-font text-success\">جُهْدُ</span> <span class=\"quran-arabic-font text-success\">الْمُقِل</span>»<br />\r\n<br />\r\n(வறுமையிலும் சிரமத்திலும் இருக்கும்போது கொடுக்கப்படும் தர்மமே மிகச் சிறந்த தர்மமாகும்.) இந்த உயர்ந்த தகுதியானது, அல்லாஹ் தனது வசனங்களில் விவரித்துள்ளவர்களின் தகுதியை விடச் சிறந்தது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيُطْعِمُونَ</span> <span class=\"quran-arabic-font text-success\">الطَّعَامَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">حُبِّهِ</span><br />\r\n<br />\r\n(மேலும் அவர்கள், அதன் மீதுள்ள பிரியத்திற்கு மத்தியிலும் உணவளிக்கிறார்கள்.) (<a href=\"qurandisp.php?sura=76&ayah=8\" class=\"link\">76:8</a>), மற்றும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَءَاتَى</span> <span class=\"quran-arabic-font text-success\">الْمَالَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">حُبِّهِ</span><br />\r\n<br />\r\n(மேலும் பொருளின் மீது விருப்பம் இருந்தபோதிலும், தனது செல்வத்தைக் கொடுக்கிறான்.) (<a href=\"qurandisp.php?sura=2&ayah=177\" class=\"link\">2:177</a>). பின்னவர்கள் தங்களுக்கு விருப்பமான பொருளைத் தர்மம் செய்தார்கள்; ஆனால் அது அவர்களுக்கு மிக அவசியமானதாக இருக்கவில்லை. ஆனால் அன்சாரிகளோ, தங்களுக்கு மிகவும் தேவையிருந்த பொருளைத் தர்மம் செய்து பிறருக்கு முன்னுரிமை அளித்தார்கள். அபூபக்கர் அஸ்-சித்தீக் (ரழி) அவர்கள் தங்கள் சொத்துக்கள் அனைத்தையும் தர்மமாக வழங்கியபோது, \"உன் குடும்பத்திற்காக எதை மீதம் வைத்திருக்கிறாய்?\" என்று அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கேட்டார்கள். அதற்கு அவர், \"நான் அவர்களுக்காக அல்லாஹ்வையும் அவனது தூதரையும் மீதம் வைத்துள்ளேன்\" என்றார். யர்முக் போரின்போது இக்ரிமா (பின் அபீ ஜஹ்ல்) (ரழி) அவர்களும் மற்ற இரண்டு வீரர்களும் காயமடைந்திருந்தபோது அவர்களுக்குத் தண்ணீர் வழங்கப்பட்டது. அவர்கள் ஒவ்வொருவரும் தனக்கு முன்னால் மற்றவருக்குத் தாகம் தீர்க்கட்டும் என்று கூறினார்கள். தாகத்தால் தவித்துக் கொண்டிருந்தும் அவர்கள் பிறருக்கே முன்னுரிமை அளித்தார்கள். அந்தத் தண்ணீர் மூன்றாவது நபரை அடைவதற்குள் அனைவரும் இறந்துவிட்டனர்; அவர்களில் யாரும் தண்ணீர் குடிக்கவில்லை! அல்லாஹ் அவர்களைப் பொருந்திக்கொள்வானாக! புகாரி பதிவு செய்துள்ள ஹதீஸில் அபூ ஹுரைரா (ரழி) அவர்கள் கூறுகிறார்கள்: \"ஒரு மனிதர் நபி (ஸல்) அவர்களிடம் வந்து, 'அல்லாஹ்வின் தூதரே! நான் வறுமையால் வாடுகிறேன்' என்றார். நபி (ஸல்) அவர்கள் தங்கள் மனைவியரிடம் ஆள் அனுப்பினார்கள். ஆனால் அவர்களிடம் எதுவும் இல்லை. அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَلَا</span> <span class=\"quran-arabic-font text-success\">رَجُلٌ</span> <span class=\"quran-arabic-font text-success\">يُضَيِّفُ</span> <span class=\"quran-arabic-font text-success\">هَذَا،</span> <span class=\"quran-arabic-font text-success\">اللَّيْلَةَ،</span> <span class=\"quran-arabic-font text-success\">رَحِمَهُ</span> <span class=\"quran-arabic-font text-success\">الله</span>»<br />\r\n<br />\r\n('இன்று இரவு இவரை விருந்தினராக உபசரிப்பவர் யார்? அவருக்கு அல்லாஹ் அருள் புரிவான்') என்றார்கள். ஓர் அன்சாரித் தோழர், 'அல்லாஹ்வின் தூதரே (ஸல்)! நான் அழைத்துச் செல்கிறேன்' என்று கூறி அவரைத் தன் வீட்டிற்கு அழைத்துச் சென்றார். தன் மனைவியிடம், 'அல்லாஹ்வின் தூதரின் (ஸல்) விருந்தாளியைக் கண்ணியமாக உபசரி' என்றார். மனைவி, 'நம்மிடம் குழந்தைகளின் உணவைத் தவிர வேறு எதுவும் இல்லையே' என்றார். அதற்கு அவர், 'குழந்தைகள் உணவு கேட்டால் அவர்களைத் தூங்க வைத்திடு. பிறகு விளக்கை அணைத்துவிட்டு, நாம் இன்று இரவு பசியோடு உறங்குவோம்' என்றார். காலையில் அந்தத் தோழர் நபி (ஸல்) அவர்களிடம் வந்தபோது, அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَقَدْ</span> <span class=\"quran-arabic-font text-success\">عَجِبَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">عَزَّ</span> <span class=\"quran-arabic-font text-success\">وَجَلَّ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">ضَحِكَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">فُلَانٍ</span> <span class=\"quran-arabic-font text-success\">وَفُلَانَة</span>»<br />\r\n<br />\r\n('இன்னார் மற்றும் அவரது மனைவியின் செயலைக் கண்டு அல்லாஹ் வியப்படைந்தான் அல்லது சிரித்தான்.') பிறகு அல்லாஹ் இந்த வசனத்தை இறக்கினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيُؤْثِرُونَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَنفُسِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">بِهِمْ</span> <span class=\"quran-arabic-font text-success\">خَصَاصَةٌ</span><br />\r\n<br />\r\n(மேலும் தங்களுக்குத் தேவையிருந்த போதிலும், தங்களை விட அவர்களுக்கே முன்னுரிமை அளிக்கின்றனர்.)\" புகாரி இந்த ஹதீஸைத் தனது ஸஹீஹ் நூலின் மற்றொரு இடத்திலும் பதிவு செய்துள்ளார். முஸ்லிம், திர்மிதி மற்றும் நஸாயியும் இதனைப் பதிவு செய்துள்ளனர். மற்றொரு அறிவிப்பில் அந்தத் தோழர் அபூ தல்ஹா அல்-அன்சாரி (ரழி) என்று குறிப்பிடப்பட்டுள்ளது. அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يُوقَ</span> <span class=\"quran-arabic-font text-success\">شُحَّ</span> <span class=\"quran-arabic-font text-success\">نَفْسِهِ</span> <span class=\"quran-arabic-font text-success\">فَأُولَئِكَ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْمُفْلِحُونَ</span><br />\r\n<br />\r\n(எவர் தனது உள்ளத்தின் கஞ்சத்தனத்திலிருந்து காக்கப்பட்டாரோ, அத்தகையவர்களே வெற்றியாளர்கள்.) கஞ்சத்தனத்திலிருந்து காக்கப்பட்டவர் வெற்றியையும் நற்பலனையும் பெற்றுவிட்டதை இது காட்டுகிறது. இமாம் அஹ்மத் அவர்கள் ஜாபிர் பின் அப்துல்லாஹ் (ரழி) அவர்கள் வாயிலாகப் பதிவு செய்துள்ளார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِيَّاكُمْ</span> <span class=\"quran-arabic-font text-success\">وَالظُّلْمَ،</span> <span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">الظُّلْمَ</span> <span class=\"quran-arabic-font text-success\">ظُلُمَاتٌ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَةِ،</span> <span class=\"quran-arabic-font text-success\">وَاتَّقُوا</span> <span class=\"quran-arabic-font text-success\">الشُّحَّ،</span> <span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">الشُّحَّ</span> <span class=\"quran-arabic-font text-success\">أَهْلَكَ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">قَبْلَكُمْ،</span> <span class=\"quran-arabic-font text-success\">حَمَلَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَلى</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">سَفَكُوا</span> <span class=\"quran-arabic-font text-success\">دِمَاءَهُمْ</span> <span class=\"quran-arabic-font text-success\">وَاسْتَحَلُّوا</span> <span class=\"quran-arabic-font text-success\">مَحَارِمَهُم</span>»<br />\r\n<br />\r\n(அநீதி இழைப்பதைத் தவிர்த்துக் கொள்ளுங்கள்; ஏனெனில் அநீதியானது மறுமை நாளில் இருள்களாக அமையும். கஞ்சத்தனத்தைத் தவிர்த்துக் கொள்ளுங்கள்; ஏனெனில் அது உங்களுக்கு முன்னிருந்தவர்களை அழித்தது. அது அவர்களை இரத்தம் சிந்தவும், தடுக்கப்பட்டவற்றை ஆகுமாக்கிக் கொள்ளவும் தூண்டியது.) முஸ்லிம் இந்த ஹதீஸைப் பதிவு செய்துள்ளார். இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார்கள்: அல்-அஸ்வத் பின் ஹிலால் என்பவர் கூறுகிறார்: ஒரு மனிதர் அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்களிடம் வந்து, \"அபூ அப்துர் ரஹ்மானே! நான் அழிந்துவிடுவேனோ என்று அஞ்சுகிறேன்\" என்றார். \"ஏன்?\" என்று அவர் கேட்க, அதற்கு அவர் \"அல்லாஹ்வின் வசனத்தைக் கேட்கிறேன்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يُوقَ</span> <span class=\"quran-arabic-font text-success\">شُحَّ</span> <span class=\"quran-arabic-font text-success\">نَفْسِهِ</span> <span class=\"quran-arabic-font text-success\">فَأُولَئِكَ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْمُفْلِحُونَ</span><br />\r\n<br />\r\n(எவர் தனது உள்ளத்தின் கஞ்சத்தனத்திலிருந்து காக்கப்பட்டாரோ அவர்களே வெற்றியாளர்கள்.) நானோ கஞ்சனாக இருக்கிறேன், எதையும் எளிதில் கொடுப்பதில்லை\" என்றார். அதற்கு அப்துல்லாஹ் (ரழி) அவர்கள், \"குர்ஆனில் அல்லாஹ் குறிப்பிட்டுள்ள கஞ்சத்தனம் (ஷுஹ்) என்பது இதுவல்ல; அது உங்கள் சகோதரனின் செல்வத்தை அநியாயமாக அபகரிப்பதாகும். உன்னிடம் இருப்பது கருமித்தனம் (பக்ல்); ஒரு கருமியாக இருப்பது உண்மையில் தீய பண்புதான்\" என்றார். அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">جَاءُوا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">بَعْدِهِمْ</span> <span class=\"quran-arabic-font text-success\">يَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">اغْفِرْ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">وَلِإِخْوَانِنَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">سَبَقُونَا</span> <span class=\"quran-arabic-font text-success\">بِالْإِيمَانِ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">تَجْعَلْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">قُلُوبِنَا</span> <span class=\"quran-arabic-font text-success\">غِلاًّ</span> <span class=\"quran-arabic-font text-success\">لِلَّذِينَ</span> <span class=\"quran-arabic-font text-success\">آمَنُوا</span> <span class=\"quran-arabic-font text-success\">رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">إِنَّكَ</span> <span class=\"quran-arabic-font text-success\">رَءُوفٌ</span> <span class=\"quran-arabic-font text-success\">رَحِيمٌ</span><br />\r\n<br />\r\n(மேலும் அவர்களுக்குப் பின் வந்தவர்கள், \"எங்கள் இறைவா! எங்களுக்கும் ஈமானில் எங்களுக்கு முந்திச் சென்ற எங்கள் சகோதரர்களுக்கும் மன்னிப்பு வழங்குவாயாக! மேலும் ஈமான் கொண்டவர்கள் மீது எங்கள் உள்ளங்களில் எந்த வெறுப்பையும் ஏற்படுத்தாதே! எங்கள் இறைவா! நிச்சயமாக நீ மிக்க இரக்கமுள்ளவன், மகா கருணையாளன்\" என்று கூறுகின்றனர்.) ஃபய்உ நிதியைப் பெறத் தகுதியுள்ள ஏழைகளின் மூன்றாவது வகை இவர்களாவர். இந்த மூன்று வகையினரும் முஹாஜிர்கள், அன்சாரிகள் மற்றும் அவர்களை அழகிய முறையில் பின்பற்றுபவர்கள் ஆவர். அல்லாஹ் மற்றொரு வசனத்தில் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالسَّابِقُونَ</span> <span class=\"quran-arabic-font text-success\">الْأَوَّلُونَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُهَاجِرِينَ</span> <span class=\"quran-arabic-font text-success\">وَالأَنْصَارِ</span> <span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">اتَّبَعُوهُم</span> <span class=\"quran-arabic-font text-success\">بِإِحْسَانٍ</span> <span class=\"quran-arabic-font text-success\">رَضِيَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَنْهُمْ</span> <span class=\"quran-arabic-font text-success\">وَرَضُوا</span> <span class=\"quran-arabic-font text-success\">عَنْهُ</span><br />\r\n<br />\r\n(முஹாஜிர்கள் மற்றும் அன்சாரிகளில் முதன்மையானவர்களும், அவர்களை அழகிய முறையில் பின்பற்றியவர்களும்; அல்லாஹ் அவர்களைப் பொருந்திக் கொண்டான்; அவர்களும் அவனைப் பொருந்திக் கொண்டனர்.) (<a href=\"qurandisp.php?sura=9&ayah=100\" class=\"link\">9:100</a>). மூன்றாவது வகையினர் முஹாஜிர்களையும் அன்சாரிகளையும் அவர்களின் நற்செயல்கள் மற்றும் நற்பண்புகளில் பின்பற்றி, அவர்களுக்காகப் பகிரங்கமாகவும் ரகசியமாகவும் பிரார்த்தனை செய்பவர்கள். இதனால்தான் உயர்ந்தோனாகிய அல்லாஹ் இந்த கண்ணியமான வசனத்தில் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">جَاءُوا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">بَعْدِهِمْ</span> <span class=\"quran-arabic-font text-success\">يَقُولُونَ</span><br />\r\n<br />\r\n(மேலும் அவர்களுக்குப் பின் வந்தவர்கள் கூறுகிறார்கள்), அதாவது அவர்கள் கூறும் பிரார்த்தனை இதுதான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">اغْفِرْ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">وَلِإِخْوَانِنَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">سَبَقُونَا</span> <span class=\"quran-arabic-font text-success\">بِالْإِيمَانِ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">تَجْعَلْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">قُلُوبِنَا</span> <span class=\"quran-arabic-font text-success\">غِلاًّ</span><br />\r\n<br />\r\n(எங்கள் இறைவா! எங்களுக்கும் ஈமானில் எங்களுக்கு முந்திச் சென்ற எங்கள் சகோதரர்களுக்கும் மன்னிப்பு வழங்குவாயாக! எங்கள் உள்ளங்களில் எந்த வெறுப்பையும் ஏற்படுத்தாதே), அதாவது கோபம் அல்லது பொறாமை,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِلَّذِينَ</span> <span class=\"quran-arabic-font text-success\">آمَنُوا</span> <span class=\"quran-arabic-font text-success\">رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">إِنَّكَ</span> <span class=\"quran-arabic-font text-success\">رَءُوفٌ</span> <span class=\"quran-arabic-font text-success\">رَحِيمٌ</span><br />\r\n<br />\r\n(ஈமான் கொண்டவர்களுக்கு எதிராக. எங்கள் இறைவா! நிச்சயமாக நீ மிக்க இரக்கமுள்ளவன், மகா கருணையாளன்.) இமாம் மாலிக் (ரஹ்) அவர்கள், ஸஹாபாக்களைக் குறை கூறும் ராஃபிதாக்களுக்கு இந்த ஃபய்உ நிதியில் எந்தப் பங்கும் கிடையாது என்று இந்த ஆயத்தைக் கொண்டே மிக அழகாகச் சட்டமியற்றியுள்ளார்கள். ஏனெனில் அல்லாஹ் விவரித்துள்ள இந்தப் பண்பு (முன்னோர்களுக்காகப் பிரார்த்தித்தல்) அவர்களிடம் இல்லை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">اغْفِرْ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">وَلِإِخْوَانِنَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">سَبَقُونَا</span> <span class=\"quran-arabic-font text-success\">بِالْإِيمَانِ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">تَجْعَلْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">قُلُوبِنَا</span> <span class=\"quran-arabic-font text-success\">غِلاًّ</span> <span class=\"quran-arabic-font text-success\">لِلَّذِينَ</span> <span class=\"quran-arabic-font text-success\">آمَنُوا</span><br />\r\n<br />\r\n(எங்கள் இறைவா! எங்களுக்கும் ஈமானில் எங்களுக்கு முந்திச் சென்ற எங்கள் சகோதரர்களுக்கும் மன்னிப்பு வழங்குவாயாக! மேலும் ஈமான் கொண்டவர்கள் மீது எங்கள் உள்ளங்களில் எந்த வெறுப்பையும் ஏற்படுத்தாதே! எங்கள் இறைவா! நிச்சயமாக நீ மிக்க இரக்கமுள்ளவன், மகா கருணையாளன்.) இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார்கள்: ஆயிஷா (ரழி) அவர்கள் கூறினார்கள், \"அவர்களுக்காக (ஸஹாபாக்களுக்காக) பாவமன்னிப்புக் கோருமாறு அவர்கள் கட்டளையிடப்பட்டனர்; ஆனால் அதற்குப் பதிலாக அவர்கள் அவர்களைச் சபித்தனர்!\" பிறகு இந்த வசனத்தை ஓதினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">جَاءُوا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">بَعْدِهِمْ</span> <span class=\"quran-arabic-font text-success\">يَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">اغْفِرْ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">وَلِإِخْوَانِنَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">سَبَقُونَا</span> <span class=\"quran-arabic-font text-success\">بِالْإِيمَانِ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">تَجْعَلْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">قُلُوبِنَا</span> <span class=\"quran-arabic-font text-success\">غِلاًّ</span> <span class=\"quran-arabic-font text-success\">لِلَّذِينَ</span> <span class=\"quran-arabic-font text-success\">آمَنُوا</span><br />\r\n<br />\r\n(மேலும் அவர்களுக்குப் பின் வந்தவர்கள், \"எங்கள் இறைவா! எங்களுக்கும் ஈமானில் எங்களுக்கு முந்திச் சென்ற எங்கள் சகோதரர்களுக்கும் மன்னிப்பு வழங்குவாயாக! மேலும் ஈமான் கொண்டவர்கள் மீது எங்கள் உள்ளங்களில் எந்த வெறுப்பையும் ஏற்படுத்தாதே\" என்று கூறுகின்றனர்.)<br />\r\n<br />","text":"ஃபய் நிதியைப் பெறத் தகுதியானவர்கள்; முஹாஜிர்கள் மற்றும் அன்சாரிகளின் சிறப்புகள்\n\r\n\n\r\nஃபய் (Fai') நிதியில் பங்கு பெறத் தகுதியுள்ள ஏழை மக்களின் பிரிவுகளைப் பற்றி அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nلِلْفُقَرَاءِ الْمُهَاجِرِينَ الَّذِينَ أُخْرِجُوا مِنْ دِيَارِهِمْ وَأَمْوَالِهِمْ يَبْتَغُونَ فَضْلاً مِنَ اللَّهِ وَرِضْوَانًا\n\r\n\n\r\n(இப்பங்கானது) தங்கள் வீடுகளையும், தங்கள் சொத்துக்களையும் விட்டு வெளியேற்றப்பட்ட ஏழை முஹாஜிர்களுக்குரியதாகும். அவர்கள் அல்லாஹ்விடமிருந்து அருளையும் (அவனது) திருப்பொருத்தத்தையும் நாடுகின்றனர்; அதாவது, அல்லாஹ்வின் திருப்பொருத்தத்தையும் அவனது அருளையும் நாடி, தங்கள் வீடுகளை விட்டு வெளியேறி, தங்கள் உறவினர்களை எதிர்த்து நின்றவர்கள்.\n\r\n\n\r\nوَيَنصُرُونَ اللَّهَ وَرَسُولَهُ أُولَئِكَ هُمُ الصَّادِقُونَ\n\r\n\n\r\n(மேலும் அல்லாஹ்வுக்கும் அவனது தூதருக்கும் உதவி செய்கிறார்கள். இவர்களே உண்மையாளர்கள்.) அதாவது, அவர்கள் சொல்லிலும் செயலிலும் உண்மையாக இருந்தவர்கள்; அவர்களே முஹாஜிர்களின் தலைவர்கள். உயர்ந்தோனாகிய அல்லாஹ் அடுத்து அன்சாரிகளைப் புகழ்ந்து, அவர்களின் சிறப்பு, அந்தஸ்து மற்றும் கண்ணியத்தை வலியுறுத்துகிறான். தங்களுக்குத் தேவையிருந்தும் பிறருக்கு முன்னுரிமை அளித்ததையும், பொறாமை கொள்ளாததையும் குறிப்பிடுகிறான். அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَالَّذِينَ تَبَوَّءُوا الدَّارَ وَالْإِيمَانَ مِنْ قَبْلِهِمْ\n\r\n\n\r\n(மேலும், அவர்களுக்கு முன்பே ஈமானை ஏற்றுக்கொண்டு, (மதீனாவைத்) தங்கள் இல்லமாகக் கொண்டவர்களுக்கும் (இதில் பங்குண்டு).) இது முஹாஜிர்கள் அங்கு வருவதற்கு முன்பே ஹிஜ்ரத் நகரமான மதீனாவில் வசித்தவர்களையும், அவர்களில் பலருக்கு முன்பே ஈமானை ஏற்றுக்கொண்டவர்களையும் குறிக்கிறது. உமர் (ரழி) அவர்கள் கூறினார்கள்: \"எனக்குப் பின் வரவிருக்கும் கலீஃபாவுக்கு நான் சில பரிந்துரைகளைச் செய்கிறேன்: முதன்மையான முஹாஜிர்களின் உரிமைகளையும் சிறப்புகளையும் அறிந்து அவர்களின் கண்ணியத்தைப் பாதுகாக்க வேண்டும். மேலும், மதீனாவில் வசித்து ஈமானை முன்கூட்டியே ஏற்றுக்கொண்ட அன்சாரிகளிடம் கனிவாக இருக்குமாறும், அவர்களில் நன்மை செய்வோரின் நற்செயல்களை ஏற்றுக்கொண்டு, தவறிழைப்பவர்களை மன்னிக்குமாறும் பரிந்துரைக்கிறேன்.\" இந்த ஹதீஸை புகாரி பதிவு செய்துள்ளார். அல்லாஹ் கூறினான்:\n\r\n\n\r\nيُحِبُّونَ مَنْ هَاجَرَ إِلَيْهِمْ\n\r\n\n\r\n(தம்மிடம் ஹிஜ்ரத் செய்து வருபவர்களை அவர்கள் நேசிக்கிறார்கள்.) இது அவர்களின் பெருந்தன்மை மற்றும் கண்ணியமான நடத்தையைக் காட்டுகிறது; அவர்கள் முஹாஜிர்களை நேசித்ததோடு தங்கள் செல்வத்தைக் கொண்டு அவர்களுக்கு ஆறுதலும் அளித்தனர். இமாம் அஹ்மத் அவர்கள் அனஸ் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"முஹாஜிர்கள் கூறினார்கள்: 'அல்லாஹ்வின் தூதரே (ஸல்)! நாங்கள் ஹிஜ்ரத் செய்து வந்த இந்த மக்களைப் போன்ற சிறந்த மனிதர்களை நாங்கள் கண்டதில்லை. பற்றாக்குறையான நேரத்திலும் எங்களுக்கு ஆதரவளித்து, செழிப்பான நேரத்திலும் இன்முகத்துடன் எங்களுக்குப் பகிர்ந்து கொடுக்கிறார்கள். அவர்கள் எங்களின் தேவைகளைப் பூர்த்தி செய்ததோடு தங்கள் செல்வத்தையும் எங்களுடன் பகிர்ந்து கொண்டார்கள்; இதனால் எங்களின் நன்மைகள் அனைத்தையும் அவர்களே பெற்றுவிடுவார்களோ என்று நாங்கள் அஞ்சுகிறோம்.' அதற்கு நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«لَا، مَا أَثْنَيْتُمْ عَلَيْهِمْ وَدَعَوْتُمُ اللهَ لَهُم»\n\r\n\n\r\n('இல்லை, நீங்கள் அவர்களுக்கு நன்றி செலுத்தி, அவர்களுக்காக அல்லாஹ்விடம் பிரார்த்தனை செய்யும் வரை அவர்கள் மட்டுமே அந்த நன்மையைப் பெற்றுவிட மாட்டார்கள்.')\" இந்த அறிவிப்பை மற்ற நூல்களில் நான் காணவில்லை. புகாரி பதிவு செய்துள்ள ஹதீஸில், யஹ்யா பின் ஸயீத் அவர்கள் அனஸ் பின் மாலிக் (ரழி) அவர்கள் அல்-வலீதிடம் சென்றபோது கூறியதைக் கேட்டுள்ளார்: \"நபி (ஸல்) அவர்கள் அன்சாரிகளை அழைத்து பஹ்ரைன் நிலத்தை அவர்களுக்குப் பங்கிட்டுக் கொடுக்க முன்வந்தார்கள். அதற்கு அன்சாரிகள், 'எங்கள் முஹாஜிர் சகோதரர்களுக்கும் அதே போன்ற ஒரு பங்கை நீங்கள் கொடுக்கும் வரை நாங்கள் எதையும் பெற்றுக்கொள்ள மாட்டோம்' என்று கூறினார்கள். அதற்கு நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِمَّا لَا، فَاصْبِرُوا حَتَّى تَلْقَوْنِي، فَإِنَّهُ سَيُصِيبُكُمْ بَعْدِي أَثَرَةً»\n\r\n\n\r\n('அப்படியென்றால், (மறுமையில்) என்னைச் சந்திக்கும் வரை பொறுமையாக இருங்கள்; ஏனெனில் எனக்குப் பிறகு மற்றவர்களுக்கு முன்னுரிமை அளிக்கப்படுவதை நீங்கள் காண்பீர்கள்.')\" இந்த அறிவிப்பு புகாரியில் மட்டுமே உள்ளது. அபூ ஹுரைரா (ரழி) அவர்கள் கூறியதாக புகாரி பதிவு செய்துள்ளார்: \"அன்சாரிகள் (நபி (ஸல்) அவர்களிடம்), 'எங்களின் பேரீச்சைத் தோப்புகளை எங்களுக்கும் எங்கள் முஹாஜிர் சகோதரர்களுக்கும் இடையில் பங்கிடுங்கள்' என்றார்கள். நபி (ஸல்) அவர்கள் 'வேண்டாம்' என்றார்கள். பிறகு அன்சாரிகள் (முஹாஜிர்களிடம்), 'அப்படியென்றால் நீங்கள் தோப்புகளைப் பராமரிக்கும் வேலையைச் செய்யுங்கள், பலனை எங்களுடன் பகிர்ந்து கொள்ளுங்கள்' என்றார்கள். முஹாஜிர்கள், 'நாங்கள் செவியேற்றோம், கீழ்ப்படிந்தோம்' என்று கூறினார்கள்.\" இதை புகாரி பதிவு செய்துள்ளார் (முஸ்லிமில் இல்லை).\n\r\n\n\r\nஅன்சாரிகள் முஹாஜிர்கள் மீது ஒருபோதும் பொறாமை கொள்ளவில்லை\n\r\n\n\r\nஅல்லாஹ் கூறினான்:\n\r\n\n\r\nوَلَا يَجِدُونَ فِي صُدُورِهِمْ حَاجَةً مِمَّا أُوتُوا\n\r\n\n\r\n(மேலும் அவர்களுக்கு வழங்கப்பட்டவை குறித்து இவர்கள் தங்கள் உள்ளங்களில் எந்தத் தேவையையும் (பொறாமையையும்) காணமாட்டார்கள்.) அதாவது, முஹாஜிர்களுக்கு அல்லாஹ் வழங்கிய அந்தஸ்து, தகுதி அல்லது உயர் நிலைகளைக் கண்டு அன்சாரிகள் பொறாமைப்படவில்லை. அல்லாஹ்வின் கூற்றான:\n\r\n\n\r\nمِمَّا أُوتُوا\n\r\n\n\r\n(அவர்களுக்கு வழங்கப்பட்டவை) என்பது முஹாஜிர்களுக்கு அளிக்கப்பட்ட சிறப்புகளைக் குறிப்பதாக கதாதா மற்றும் இப்னு ஸைத் கூறுகின்றனர்.\n\r\n\n\r\nஅன்சாரிகளின் தன்னலமற்ற தன்மை\n\r\n\n\r\nஅல்லாஹ் கூறினான்:\n\r\n\n\r\nوَيُؤْثِرُونَ عَلَى أَنفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ\n\r\n\n\r\n(தங்களுக்குத் தேவையிருந்த போதிலும், தங்களை விட அவர்களுக்கே முன்னுரிமை அளிக்கின்றனர்.) அதாவது, அவர்கள் தங்கள் சொந்தத் தேவைகளை விட வறியவர்களின் தேவைகளுக்கு முன்னுரிமை அளித்தார்கள்; தங்களுக்குத் தேவையிருந்தும் மற்றவர்களுக்கே முதலில் கொடுத்தார்கள். ஓர் ஆதாரப்பூர்வமான ஹதீஸில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«أَفْضَلُ الصَّدَقَةِ جُهْدُ الْمُقِل»\n\r\n\n\r\n(வறுமையிலும் சிரமத்திலும் இருக்கும்போது கொடுக்கப்படும் தர்மமே மிகச் சிறந்த தர்மமாகும்.) இந்த உயர்ந்த தகுதியானது, அல்லாஹ் தனது வசனங்களில் விவரித்துள்ளவர்களின் தகுதியை விடச் சிறந்தது:\n\r\n\n\r\nوَيُطْعِمُونَ الطَّعَامَ عَلَى حُبِّهِ\n\r\n\n\r\n(மேலும் அவர்கள், அதன் மீதுள்ள பிரியத்திற்கு மத்தியிலும் உணவளிக்கிறார்கள்.) (76:8), மற்றும்,\n\r\n\n\r\nوَءَاتَى الْمَالَ عَلَى حُبِّهِ\n\r\n\n\r\n(மேலும் பொருளின் மீது விருப்பம் இருந்தபோதிலும், தனது செல்வத்தைக் கொடுக்கிறான்.) (2:177). பின்னவர்கள் தங்களுக்கு விருப்பமான பொருளைத் தர்மம் செய்தார்கள்; ஆனால் அது அவர்களுக்கு மிக அவசியமானதாக இருக்கவில்லை. ஆனால் அன்சாரிகளோ, தங்களுக்கு மிகவும் தேவையிருந்த பொருளைத் தர்மம் செய்து பிறருக்கு முன்னுரிமை அளித்தார்கள். அபூபக்கர் அஸ்-சித்தீக் (ரழி) அவர்கள் தங்கள் சொத்துக்கள் அனைத்தையும் தர்மமாக வழங்கியபோது, \"உன் குடும்பத்திற்காக எதை மீதம் வைத்திருக்கிறாய்?\" என்று அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கேட்டார்கள். அதற்கு அவர், \"நான் அவர்களுக்காக அல்லாஹ்வையும் அவனது தூதரையும் மீதம் வைத்துள்ளேன்\" என்றார். யர்முக் போரின்போது இக்ரிமா (பின் அபீ ஜஹ்ல்) (ரழி) அவர்களும் மற்ற இரண்டு வீரர்களும் காயமடைந்திருந்தபோது அவர்களுக்குத் தண்ணீர் வழங்கப்பட்டது. அவர்கள் ஒவ்வொருவரும் தனக்கு முன்னால் மற்றவருக்குத் தாகம் தீர்க்கட்டும் என்று கூறினார்கள். தாகத்தால் தவித்துக் கொண்டிருந்தும் அவர்கள் பிறருக்கே முன்னுரிமை அளித்தார்கள். அந்தத் தண்ணீர் மூன்றாவது நபரை அடைவதற்குள் அனைவரும் இறந்துவிட்டனர்; அவர்களில் யாரும் தண்ணீர் குடிக்கவில்லை! அல்லாஹ் அவர்களைப் பொருந்திக்கொள்வானாக! புகாரி பதிவு செய்துள்ள ஹதீஸில் அபூ ஹுரைரா (ரழி) அவர்கள் கூறுகிறார்கள்: \"ஒரு மனிதர் நபி (ஸல்) அவர்களிடம் வந்து, 'அல்லாஹ்வின் தூதரே! நான் வறுமையால் வாடுகிறேன்' என்றார். நபி (ஸல்) அவர்கள் தங்கள் மனைவியரிடம் ஆள் அனுப்பினார்கள். ஆனால் அவர்களிடம் எதுவும் இல்லை. அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்:\n\r\n\n\r\n«أَلَا رَجُلٌ يُضَيِّفُ هَذَا، اللَّيْلَةَ، رَحِمَهُ الله»\n\r\n\n\r\n('இன்று இரவு இவரை விருந்தினராக உபசரிப்பவர் யார்? அவருக்கு அல்லாஹ் அருள் புரிவான்') என்றார்கள். ஓர் அன்சாரித் தோழர், 'அல்லாஹ்வின் தூதரே (ஸல்)! நான் அழைத்துச் செல்கிறேன்' என்று கூறி அவரைத் தன் வீட்டிற்கு அழைத்துச் சென்றார். தன் மனைவியிடம், 'அல்லாஹ்வின் தூதரின் (ஸல்) விருந்தாளியைக் கண்ணியமாக உபசரி' என்றார். மனைவி, 'நம்மிடம் குழந்தைகளின் உணவைத் தவிர வேறு எதுவும் இல்லையே' என்றார். அதற்கு அவர், 'குழந்தைகள் உணவு கேட்டால் அவர்களைத் தூங்க வைத்திடு. பிறகு விளக்கை அணைத்துவிட்டு, நாம் இன்று இரவு பசியோடு உறங்குவோம்' என்றார். காலையில் அந்தத் தோழர் நபி (ஸல்) அவர்களிடம் வந்தபோது, அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«لَقَدْ عَجِبَ اللهُ عَزَّ وَجَلَّ أَوْ ضَحِكَ مِنْ فُلَانٍ وَفُلَانَة»\n\r\n\n\r\n('இன்னார் மற்றும் அவரது மனைவியின் செயலைக் கண்டு அல்லாஹ் வியப்படைந்தான் அல்லது சிரித்தான்.') பிறகு அல்லாஹ் இந்த வசனத்தை இறக்கினான்:\n\r\n\n\r\nوَيُؤْثِرُونَ عَلَى أَنفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ\n\r\n\n\r\n(மேலும் தங்களுக்குத் தேவையிருந்த போதிலும், தங்களை விட அவர்களுக்கே முன்னுரிமை அளிக்கின்றனர்.)\" புகாரி இந்த ஹதீஸைத் தனது ஸஹீஹ் நூலின் மற்றொரு இடத்திலும் பதிவு செய்துள்ளார். முஸ்லிம், திர்மிதி மற்றும் நஸாயியும் இதனைப் பதிவு செய்துள்ளனர். மற்றொரு அறிவிப்பில் அந்தத் தோழர் அபூ தல்ஹா அல்-அன்சாரி (ரழி) என்று குறிப்பிடப்பட்டுள்ளது. அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَمَن يُوقَ شُحَّ نَفْسِهِ فَأُولَئِكَ هُمُ الْمُفْلِحُونَ\n\r\n\n\r\n(எவர் தனது உள்ளத்தின் கஞ்சத்தனத்திலிருந்து காக்கப்பட்டாரோ, அத்தகையவர்களே வெற்றியாளர்கள்.) கஞ்சத்தனத்திலிருந்து காக்கப்பட்டவர் வெற்றியையும் நற்பலனையும் பெற்றுவிட்டதை இது காட்டுகிறது. இமாம் அஹ்மத் அவர்கள் ஜாபிர் பின் அப்துல்லாஹ் (ரழி) அவர்கள் வாயிலாகப் பதிவு செய்துள்ளார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِيَّاكُمْ وَالظُّلْمَ، فَإِنَّ الظُّلْمَ ظُلُمَاتٌ يَوْمَ الْقِيَامَةِ، وَاتَّقُوا الشُّحَّ، فَإِنَّ الشُّحَّ أَهْلَكَ مَنْ كَانَ قَبْلَكُمْ، حَمَلَهُمْ عَلى أَنْ سَفَكُوا دِمَاءَهُمْ وَاسْتَحَلُّوا مَحَارِمَهُم»\n\r\n\n\r\n(அநீதி இழைப்பதைத் தவிர்த்துக் கொள்ளுங்கள்; ஏனெனில் அநீதியானது மறுமை நாளில் இருள்களாக அமையும். கஞ்சத்தனத்தைத் தவிர்த்துக் கொள்ளுங்கள்; ஏனெனில் அது உங்களுக்கு முன்னிருந்தவர்களை அழித்தது. அது அவர்களை இரத்தம் சிந்தவும், தடுக்கப்பட்டவற்றை ஆகுமாக்கிக் கொள்ளவும் தூண்டியது.) முஸ்லிம் இந்த ஹதீஸைப் பதிவு செய்துள்ளார். இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார்கள்: அல்-அஸ்வத் பின் ஹிலால் என்பவர் கூறுகிறார்: ஒரு மனிதர் அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்களிடம் வந்து, \"அபூ அப்துர் ரஹ்மானே! நான் அழிந்துவிடுவேனோ என்று அஞ்சுகிறேன்\" என்றார். \"ஏன்?\" என்று அவர் கேட்க, அதற்கு அவர் \"அல்லாஹ்வின் வசனத்தைக் கேட்கிறேன்:\n\r\n\n\r\nوَمَن يُوقَ شُحَّ نَفْسِهِ فَأُولَئِكَ هُمُ الْمُفْلِحُونَ\n\r\n\n\r\n(எவர் தனது உள்ளத்தின் கஞ்சத்தனத்திலிருந்து காக்கப்பட்டாரோ அவர்களே வெற்றியாளர்கள்.) நானோ கஞ்சனாக இருக்கிறேன், எதையும் எளிதில் கொடுப்பதில்லை\" என்றார். அதற்கு அப்துல்லாஹ் (ரழி) அவர்கள், \"குர்ஆனில் அல்லாஹ் குறிப்பிட்டுள்ள கஞ்சத்தனம் (ஷுஹ்) என்பது இதுவல்ல; அது உங்கள் சகோதரனின் செல்வத்தை அநியாயமாக அபகரிப்பதாகும். உன்னிடம் இருப்பது கருமித்தனம் (பக்ல்); ஒரு கருமியாக இருப்பது உண்மையில் தீய பண்புதான்\" என்றார். அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَالَّذِينَ جَاءُوا مِنْ بَعْدِهِمْ يَقُولُونَ رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالْإِيمَانِ وَلَا تَجْعَلْ فِي قُلُوبِنَا غِلاًّ لِلَّذِينَ آمَنُوا رَبَّنَا إِنَّكَ رَءُوفٌ رَحِيمٌ\n\r\n\n\r\n(மேலும் அவர்களுக்குப் பின் வந்தவர்கள், \"எங்கள் இறைவா! எங்களுக்கும் ஈமானில் எங்களுக்கு முந்திச் சென்ற எங்கள் சகோதரர்களுக்கும் மன்னிப்பு வழங்குவாயாக! மேலும் ஈமான் கொண்டவர்கள் மீது எங்கள் உள்ளங்களில் எந்த வெறுப்பையும் ஏற்படுத்தாதே! எங்கள் இறைவா! நிச்சயமாக நீ மிக்க இரக்கமுள்ளவன், மகா கருணையாளன்\" என்று கூறுகின்றனர்.) ஃபய்உ நிதியைப் பெறத் தகுதியுள்ள ஏழைகளின் மூன்றாவது வகை இவர்களாவர். இந்த மூன்று வகையினரும் முஹாஜிர்கள், அன்சாரிகள் மற்றும் அவர்களை அழகிய முறையில் பின்பற்றுபவர்கள் ஆவர். அல்லாஹ் மற்றொரு வசனத்தில் கூறுகிறான்:\n\r\n\n\r\nوَالسَّابِقُونَ الْأَوَّلُونَ مِنَ الْمُهَاجِرِينَ وَالأَنْصَارِ وَالَّذِينَ اتَّبَعُوهُم بِإِحْسَانٍ رَضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ\n\r\n\n\r\n(முஹாஜிர்கள் மற்றும் அன்சாரிகளில் முதன்மையானவர்களும், அவர்களை அழகிய முறையில் பின்பற்றியவர்களும்; அல்லாஹ் அவர்களைப் பொருந்திக் கொண்டான்; அவர்களும் அவனைப் பொருந்திக் கொண்டனர்.) (9:100). மூன்றாவது வகையினர் முஹாஜிர்களையும் அன்சாரிகளையும் அவர்களின் நற்செயல்கள் மற்றும் நற்பண்புகளில் பின்பற்றி, அவர்களுக்காகப் பகிரங்கமாகவும் ரகசியமாகவும் பிரார்த்தனை செய்பவர்கள். இதனால்தான் உயர்ந்தோனாகிய அல்லாஹ் இந்த கண்ணியமான வசனத்தில் கூறினான்:\n\r\n\n\r\nوَالَّذِينَ جَاءُوا مِنْ بَعْدِهِمْ يَقُولُونَ\n\r\n\n\r\n(மேலும் அவர்களுக்குப் பின் வந்தவர்கள் கூறுகிறார்கள்), அதாவது அவர்கள் கூறும் பிரார்த்தனை இதுதான்:\n\r\n\n\r\nرَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالْإِيمَانِ وَلَا تَجْعَلْ فِي قُلُوبِنَا غِلاًّ\n\r\n\n\r\n(எங்கள் இறைவா! எங்களுக்கும் ஈமானில் எங்களுக்கு முந்திச் சென்ற எங்கள் சகோதரர்களுக்கும் மன்னிப்பு வழங்குவாயாக! எங்கள் உள்ளங்களில் எந்த வெறுப்பையும் ஏற்படுத்தாதே), அதாவது கோபம் அல்லது பொறாமை,\n\r\n\n\r\nلِلَّذِينَ آمَنُوا رَبَّنَا إِنَّكَ رَءُوفٌ رَحِيمٌ\n\r\n\n\r\n(ஈமான் கொண்டவர்களுக்கு எதிராக. எங்கள் இறைவா! நிச்சயமாக நீ மிக்க இரக்கமுள்ளவன், மகா கருணையாளன்.) இமாம் மாலிக் (ரஹ்) அவர்கள், ஸஹாபாக்களைக் குறை கூறும் ராஃபிதாக்களுக்கு இந்த ஃபய்உ நிதியில் எந்தப் பங்கும் கிடையாது என்று இந்த ஆயத்தைக் கொண்டே மிக அழகாகச் சட்டமியற்றியுள்ளார்கள். ஏனெனில் அல்லாஹ் விவரித்துள்ள இந்தப் பண்பு (முன்னோர்களுக்காகப் பிரார்த்தித்தல்) அவர்களிடம் இல்லை.\n\r\n\n\r\nرَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالْإِيمَانِ وَلَا تَجْعَلْ فِي قُلُوبِنَا غِلاًّ لِلَّذِينَ آمَنُوا\n\r\n\n\r\n(எங்கள் இறைவா! எங்களுக்கும் ஈமானில் எங்களுக்கு முந்திச் சென்ற எங்கள் சகோதரர்களுக்கும் மன்னிப்பு வழங்குவாயாக! மேலும் ஈமான் கொண்டவர்கள் மீது எங்கள் உள்ளங்களில் எந்த வெறுப்பையும் ஏற்படுத்தாதே! எங்கள் இறைவா! நிச்சயமாக நீ மிக்க இரக்கமுள்ளவன், மகா கருணையாளன்.) இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார்கள்: ஆயிஷா (ரழி) அவர்கள் கூறினார்கள், \"அவர்களுக்காக (ஸஹாபாக்களுக்காக) பாவமன்னிப்புக் கோருமாறு அவர்கள் கட்டளையிடப்பட்டனர்; ஆனால் அதற்குப் பதிலாக அவர்கள் அவர்களைச் சபித்தனர்!\" பிறகு இந்த வசனத்தை ஓதினார்கள்:\n\r\n\n\r\nوَالَّذِينَ جَاءُوا مِنْ بَعْدِهِمْ يَقُولُونَ رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالْإِيمَانِ وَلَا تَجْعَلْ فِي قُلُوبِنَا غِلاًّ لِلَّذِينَ آمَنُوا\n\r\n\n\r\n(மேலும் அவர்களுக்குப் பின் வந்தவர்கள், \"எங்கள் இறைவா! எங்களுக்கும் ஈமானில் எங்களுக்கு முந்திச் சென்ற எங்கள் சகோதரர்களுக்கும் மன்னிப்பு வழங்குவாயாக! மேலும் ஈமான் கொண்டவர்கள் மீது எங்கள் உள்ளங்களில் எந்த வெறுப்பையும் ஏற்படுத்தாதே\" என்று கூறுகின்றனர்.)"},"11":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=59&ayah=17\" class=\"link\">59:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 59:17 ஐ பார்க்கவும்"},"12":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=59&ayah=17\" class=\"link\">59:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 59:17 ஐ பார்க்கவும்"},"13":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=59&ayah=17\" class=\"link\">59:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 59:17 ஐ பார்க்கவும்"},"14":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=59&ayah=17\" class=\"link\">59:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 59:17 ஐ பார்க்கவும்"},"15":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=59&ayah=17\" class=\"link\">59:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 59:17 ஐ பார்க்கவும்"},"16":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=59&ayah=17\" class=\"link\">59:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 59:17 ஐ பார்க்கவும்"},"17":{"html":"<strong>நயவஞ்சகர்கள் யூதர்களுக்கு அளித்த ஆதரவு குறித்த பொய்யான வாக்குறுதி</strong><br />\r\n<br />\r\nஅப்துல்லாஹ் பின் உபை மற்றும் அவனைப் போன்ற நயவஞ்சகர்கள், பனூ நளீர் கோத்திரத்தாரிடம் ஒரு தூதரை அனுப்பி அவர்களுக்கு உதவி செய்வதாக வாக்குறுதி அளித்தார்கள் என்று அல்லாஹ் கூறுகிறான். கண்ணியமும் உயர்வும் மிக்க அல்லாஹ் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾أَلَمْ</span> <span class=\"quran-arabic-font text-success\">تَرَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">نَافَقُواْ</span> <span class=\"quran-arabic-font text-success\">يَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">لإِخْوَانِهِمُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">الْكِتَابِ</span> <span class=\"quran-arabic-font text-success\">لَئِنْ</span> <span class=\"quran-arabic-font text-success\">أُخْرِجْتُمْ</span> <span class=\"quran-arabic-font text-success\">لَنَخْرُجَنَّ</span> <span class=\"quran-arabic-font text-success\">مَعَكُمْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">نُطِيعُ</span> <span class=\"quran-arabic-font text-success\">فيكُمْ</span> <span class=\"quran-arabic-font text-success\">أَحَداً</span> <span class=\"quran-arabic-font text-success\">أَبَداً</span> <span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">قُوتِلْتُمْ</span> <span class=\"quran-arabic-font text-success\">لَنَنصُرَنَّكُمْ﴿</span><br />\r\n<br />\r\n(வேதக்காரர்களில் நிராகரித்த தம் சகோதரர்களிடம், \"நீங்கள் வெளியேற்றப்பட்டால், நிச்சயமாக நாங்களும் உங்களுடன் வெளியேறிவிடுவோம்; உங்களைக் குறித்த விஷயத்தில் நாங்கள் யாருக்கும் எப்போதும் கீழ்ப்படிய மாட்டோம்; நீங்கள் தாக்கப்பட்டு போர் செய்யப்பட்டால், நிச்சயமாக நாங்கள் உங்களுக்கு உதவி செய்வோம்\" என்று கூறும் நயவஞ்சகர்களை நீர் பார்க்கவில்லையா?) பின்னர் அல்லாஹ் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">يَشْهَدُ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">لَكَاذِبُونَ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக அவர்கள் பொய்யர்களே என்பதற்கு அல்லாஹ்வே சாட்சியாக இருக்கிறான்.) அதாவது, நயவஞ்சகர்கள் இந்த வாக்குறுதியை அளித்தபோது பொய் சொன்னார்கள். ஏனெனில், அவை நிறைவேற்றும் எண்ணம் இல்லாமல் சொல்லப்பட்ட வெறும் வார்த்தைகளே. மேலும், அவர்கள் செய்வதாகச் சொன்னதை ஒருபோதும் அவர்களால் நிறைவேற்றியிருக்க முடியாது. இதனால்தான் அல்லாஹ் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾وَلَئِن</span> <span class=\"quran-arabic-font text-success\">قُوتِلُواْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَنصُرُونَهُمْ﴿</span><br />\r\n<br />\r\n(அவர்கள் மீது தாக்குதல் நடத்தப்பட்டால், இவர்கள் அவர்களுக்கு உதவி செய்யவே மாட்டார்கள்.) அதாவது, நயவஞ்சகர்கள் யூதர்களுடன் சேர்ந்து போரிட மாட்டார்கள். <span class=\"quran-arabic-font text-success\">﴾وَلَئِن</span> <span class=\"quran-arabic-font text-success\">نَّصَرُوهُمْ﴿</span><br />\r\n<br />\r\n(அவர்கள் இவர்களுக்கு உதவி செய்தாலும் கூட,) நயவஞ்சகர்கள் அவர்களுடன் சேர்ந்து போரிட்டாலும் கூட, <span class=\"quran-arabic-font text-success\">﴾لَيُوَلُّنَّ</span> <span class=\"quran-arabic-font text-success\">الأَدْبَارَ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُنصَرُونَ﴿</span><br />\r\n<br />\r\n(அவர்கள் புறங்காட்டி ஓடிவிடுவார்கள்; பின்னர் அவர்கள் வெற்றி பெற மாட்டார்கள்.) இந்த வசனம் ஒரு நற்செய்தியைக் கொண்டுள்ளது; அது பின்வரும் வசனம் சொல்லும் நற்செய்தியைப் போன்றதேயாகும்: <span class=\"quran-arabic-font text-success\">﴾لَأَنتُمْ</span> <span class=\"quran-arabic-font text-success\">أَشَدُّ</span> <span class=\"quran-arabic-font text-success\">رَهْبَةً</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">صُدُورِهِمْ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, அவர்களின் உள்ளங்களில் அல்லாஹ்வை விட உங்களைப் பற்றிய அச்சம்தான் மிகக் கடுமையாக இருக்கிறது.) அதாவது, நயவஞ்சகர்கள் அல்லாஹ்வுக்கு அஞ்சுவதை விட உங்களுக்கு அதிகமாக அஞ்சுகிறார்கள். இதையே அவன் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾إِذَا</span> <span class=\"quran-arabic-font text-success\">فَرِيقٌ</span> <span class=\"quran-arabic-font text-success\">مِّنْهُمْ</span> <span class=\"quran-arabic-font text-success\">يَخْشَوْنَ</span> <span class=\"quran-arabic-font text-success\">النَّاسَ</span> <span class=\"quran-arabic-font text-success\">كَخَشْيَةِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">أَشَدَّ</span> <span class=\"quran-arabic-font text-success\">خَشْيَةً﴿</span><br />\r\n<br />\r\n(கவனிப்பீராக! அவர்களில் ஒரு பிரிவினர் அல்லாஹ்வுக்கு அஞ்சுவது போல் அல்லது அதைவிடக் கடுமையாக மனிதர்களுக்கு அஞ்சுகின்றனர்.) (<a href=\"qurandisp.php?sura=4&ayah=77\" class=\"link\">4:77</a>) இதனால்தான் அல்லாஹ் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">بِأَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">قَوْمٌ</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يَفْقَهُونَ﴿</span><br />\r\n<br />\r\n(ஏனென்றால், அவர்கள் விளங்கிக் கொள்ளாத ஒரு சமூகத்தாராக இருக்கிறார்கள்.) பின்னர் அல்லாஹ் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾لَا</span> <span class=\"quran-arabic-font text-success\">يُقَاتِلُونَكُمْ</span> <span class=\"quran-arabic-font text-success\">جَمِيعاً</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">قُرًى</span> <span class=\"quran-arabic-font text-success\">مُّحَصَّنَةٍ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">وَرَآءِ</span> <span class=\"quran-arabic-font text-success\">جُدُرٍ﴿</span><br />\r\n<br />\r\n(அவர்கள் அனைவரும் ஒன்று சேர்ந்தும் உங்களுடன் போரிட மாட்டார்கள்; பாதுகாக்கப்பட்ட கோட்டைகளுக்குள்ளிருந்தோ அல்லது மதில்களுக்குப் பின்னாலிருந்தோ தவிர.) அதாவது, அவர்களின் கோழைத்தனம் மற்றும் முஸ்லிம்கள் மீதான அச்சம் காரணமாக, முற்றுகையிடப்பட்ட பாதுகாப்பான கோட்டைகளுக்குப் பின்னாலிருந்து அன்றி முஸ்லிம்களுடன் அவர்கள் போரிட மாட்டார்கள். அவர்கள் தங்களைத் தற்காத்துக் கொள்ள வேண்டிய கட்டாயம் ஏற்படும்போது மட்டுமே போரிடுவார்கள் (முஸ்லிம்களைப் பழிவாங்குவதாக அவர்கள் அச்சுறுத்தினாலும் கூட). உயர்ந்தோனாகிய அல்லாஹ் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾بَأْسُهُمْ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمْ</span> <span class=\"quran-arabic-font text-success\">شَدِيدٌ﴿</span><br />\r\n<br />\r\n(அவர்களுக்கிடையே உள்ள பகைமை மிகவும் கடுமையானது.) அதாவது, அவர்கள் ஒருவருக்கொருவர் கொண்டுள்ள பகைமை மிகத் தீவிரமானது. <span class=\"quran-arabic-font text-success\">﴾وَيُذِيقَ</span> <span class=\"quran-arabic-font text-success\">بَعْضَكُمْ</span> <span class=\"quran-arabic-font text-success\">بَأْسَ</span> <span class=\"quran-arabic-font text-success\">بَعْضٍ﴿</span><br />\r\n<br />\r\n(உங்களில் சிலர் மற்ற சிலரின் வன்முறையைச் சுவைக்கும்படி செய்வான்.) (<a href=\"qurandisp.php?sura=6&ayah=65\" class=\"link\">6:65</a>) அல்லாஹ் இந்த வசனத்தில் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾تَحْسَبُهُمْ</span> <span class=\"quran-arabic-font text-success\">جَمِيعاً</span> <span class=\"quran-arabic-font text-success\">وَقُلُوبُهُمْ</span> <span class=\"quran-arabic-font text-success\">شَتَّى﴿</span><br />\r\n<br />\r\n(அவர்கள் ஒன்றுபட்டிருப்பதாக நீர் நினைப்பீர்; ஆனால் அவர்களின் உள்ளங்கள் பிளவுபட்டுள்ளன.) அதாவது, அவர்கள் படைகளை ஒன்றிணைப்பதைப் பார்த்து அந்தப் படைகள் இணக்கமாக இருப்பதாக ஒருவர் நினைக்கலாம். ஆனால் உண்மையில் அவர்கள் கடுமையாகப் பிளவுபட்டுள்ளனர். இந்த வசனம் நயவஞ்சகர்களையும் வேதக்காரர்களையும் குறிக்கிறது என்று இப்ராஹீம் அந்-நகஈ கூறினார்கள். <span class=\"quran-arabic-font text-success\">﴾ذلِكَ</span> <span class=\"quran-arabic-font text-success\">بِأَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">قَوْمٌ</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يَعْقِلُونَ﴿</span><br />\r\n<br />\r\n(ஏனென்றால், அவர்கள் புரிந்து கொள்ளாத ஒரு சமூகத்தாராக இருக்கிறார்கள்.) அல்லாஹ் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾كَمَثَلِ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِهِمْ</span> <span class=\"quran-arabic-font text-success\">قَرِيباً</span> <span class=\"quran-arabic-font text-success\">ذَاقُواْ</span> <span class=\"quran-arabic-font text-success\">وَبَالَ</span> <span class=\"quran-arabic-font text-success\">أَمْرِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَلَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَذَابٌ</span> <span class=\"quran-arabic-font text-success\">أَلِيمٌ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவர்கள் தங்களுக்குச் சமீபத்தில் முன் சென்றவர்களைப் போன்றவர்கள்; அவர்கள் தங்கள் செயலின் தீய விளைவைச் சுவைத்தார்கள். மேலும் அவர்களுக்கு வலிமிகுந்த வேதனையுண்டு.) இது பனூ கைனுகா யூத கோத்திரத்தைக் குறிக்கிறது என்று இப்னு அப்பாஸ் (ரழி), கதாதா மற்றும் முஹம்மது பின் இஸ்ஹாக் ஆகியோர் கூறுகிறார்கள். மேலும் முஜாஹித், அஸ்ஸுத்தீ மற்றும் முகாதில் பின் ஹய்யான் ஆகியோர், \"இது பத்ருப் போரில் தோல்வியுற்ற மக்கா முஷ்ரிக்குகளைக் குறிக்கிறது\" என்றும் கூறியுள்ளனர்.<br />\r\n<br />\r\n<strong>நயவஞ்சகர்கள் மற்றும் யூதர்களின் உவமை</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾كَمَثَلِ</span> <span class=\"quran-arabic-font text-success\">الشَّيْطَانِ</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">لِلْإِنسَانِ</span> <span class=\"quran-arabic-font text-success\">اكْفُرْ</span> <span class=\"quran-arabic-font text-success\">فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">كَفَرَ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">بَرِىءٌ</span> <span class=\"quran-arabic-font text-success\">مِّنكَ﴿</span><br />\r\n<br />\r\n(ஷைத்தானின் உதாரணத்தைப் போன்றது; அவன் மனிதனிடம், \"நிராகரித்துவிடு\" என்று கூறினான். மனிதன் நிராகரித்ததும், ஷைத்தான், \"நிச்சயமாக நான் உன்னை விட்டும் நீங்கிக்கொண்டேன்\" என்று கூறினான்...) அதாவது, \"முஸ்லிம்கள் உங்களுக்கு எதிராகப் போரிட்டால் நாங்கள் உங்களுக்கு உதவுவோம்\" என்று கூறிய நயவஞ்சகர்களின் வாக்குறுதியால் யூதர்கள் ஏமாற்றப்பட்ட உதாரணம், ஷைத்தானுடைய உதாரணத்தைப் போன்றதாகும். நிலைமை விபரீதமாகி யூதர்கள் முற்றுகையிடப்பட்டபோது, நயவஞ்சகர்கள் அவர்களுக்குத் துரோகம் இழைத்து, படுதோல்வியைச் சுவைக்க அவர்களைக் கைவிட்டனர். அவ்வாறே, ஷைத்தான் மனிதர்களை நிராகரிப்பின் பக்கம் ஈர்க்கிறான். அவர்கள் அவனுக்குக் கீழ்ப்படியும்போது, அவன் அவர்களைக் கைவிட்டு, அவர்களின் செயல்களிலிருந்து தான் நீங்கிக்கொண்டதாக அறிவித்து, இவ்வாறு கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾إِنِّى</span> <span class=\"quran-arabic-font text-success\">أَخَافُ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">رَبَّ</span> <span class=\"quran-arabic-font text-success\">الْعَالَمِينَ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக நான் அகிலங்களின் இறைவனாகிய அல்லாஹ்வுக்கு அஞ்சுகிறேன்!) அல்லாஹ் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾فَكَانَ</span> <span class=\"quran-arabic-font text-success\">عَاقِبَتَهُمَا</span> <span class=\"quran-arabic-font text-success\">أَنَّهُمَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">خَالِدِينَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا﴿</span><br />\r\n<br />\r\n(எனவே, அவ்விருவரின் முடிவும் நிச்சயமாக அவர்கள் நரக நெருப்பில் தங்குவதாகும்; அதில் அவர்கள் என்றென்றும் இருப்பார்கள்.) அதாவது, நிராகரிப்பைச் செய்யுமாறு தூண்டிய ஷைத்தான் மற்றும் அவனது அழைப்பை ஏற்றுக்கொண்டவர்கள் ஆகிய இருவரின் முடிவும் நரக நெருப்பில் என்றென்றும் தங்குவதாகும். <span class=\"quran-arabic-font text-success\">﴾وَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">جَزَآءُ</span> <span class=\"quran-arabic-font text-success\">الظَّالِمِينَ﴿</span><br />\r\n<br />\r\n(இதுவே அநியாயக்காரர்களின் பிரதிபலனாகும்.) அதாவது, இது ஒவ்வொரு அநியாயக்காரனுக்கும் கிடைக்கின்ற கூலியாகும்.<br />\r\n<br />","text":"நயவஞ்சகர்கள் யூதர்களுக்கு அளித்த ஆதரவு குறித்த பொய்யான வாக்குறுதி\n\r\n\n\r\nஅப்துல்லாஹ் பின் உபை மற்றும் அவனைப் போன்ற நயவஞ்சகர்கள், பனூ நளீர் கோத்திரத்தாரிடம் ஒரு தூதரை அனுப்பி அவர்களுக்கு உதவி செய்வதாக வாக்குறுதி அளித்தார்கள் என்று அல்லாஹ் கூறுகிறான். கண்ணியமும் உயர்வும் மிக்க அல்லாஹ் கூறினான்: ﴾أَلَمْ تَرَ إِلَى الَّذِينَ نَافَقُواْ يَقُولُونَ لإِخْوَانِهِمُ الَّذِينَ كَفَرُواْ مِنْ أَهْلِ الْكِتَابِ لَئِنْ أُخْرِجْتُمْ لَنَخْرُجَنَّ مَعَكُمْ وَلاَ نُطِيعُ فيكُمْ أَحَداً أَبَداً وَإِن قُوتِلْتُمْ لَنَنصُرَنَّكُمْ﴿\n\r\n\n\r\n(வேதக்காரர்களில் நிராகரித்த தம் சகோதரர்களிடம், \"நீங்கள் வெளியேற்றப்பட்டால், நிச்சயமாக நாங்களும் உங்களுடன் வெளியேறிவிடுவோம்; உங்களைக் குறித்த விஷயத்தில் நாங்கள் யாருக்கும் எப்போதும் கீழ்ப்படிய மாட்டோம்; நீங்கள் தாக்கப்பட்டு போர் செய்யப்பட்டால், நிச்சயமாக நாங்கள் உங்களுக்கு உதவி செய்வோம்\" என்று கூறும் நயவஞ்சகர்களை நீர் பார்க்கவில்லையா?) பின்னர் அல்லாஹ் கூறினான்: ﴾وَاللَّهُ يَشْهَدُ إِنَّهُمْ لَكَاذِبُونَ﴿\n\r\n\n\r\n(நிச்சயமாக அவர்கள் பொய்யர்களே என்பதற்கு அல்லாஹ்வே சாட்சியாக இருக்கிறான்.) அதாவது, நயவஞ்சகர்கள் இந்த வாக்குறுதியை அளித்தபோது பொய் சொன்னார்கள். ஏனெனில், அவை நிறைவேற்றும் எண்ணம் இல்லாமல் சொல்லப்பட்ட வெறும் வார்த்தைகளே. மேலும், அவர்கள் செய்வதாகச் சொன்னதை ஒருபோதும் அவர்களால் நிறைவேற்றியிருக்க முடியாது. இதனால்தான் அல்லாஹ் கூறினான்: ﴾وَلَئِن قُوتِلُواْ لاَ يَنصُرُونَهُمْ﴿\n\r\n\n\r\n(அவர்கள் மீது தாக்குதல் நடத்தப்பட்டால், இவர்கள் அவர்களுக்கு உதவி செய்யவே மாட்டார்கள்.) அதாவது, நயவஞ்சகர்கள் யூதர்களுடன் சேர்ந்து போரிட மாட்டார்கள். ﴾وَلَئِن نَّصَرُوهُمْ﴿\n\r\n\n\r\n(அவர்கள் இவர்களுக்கு உதவி செய்தாலும் கூட,) நயவஞ்சகர்கள் அவர்களுடன் சேர்ந்து போரிட்டாலும் கூட, ﴾لَيُوَلُّنَّ الأَدْبَارَ ثُمَّ لاَ يُنصَرُونَ﴿\n\r\n\n\r\n(அவர்கள் புறங்காட்டி ஓடிவிடுவார்கள்; பின்னர் அவர்கள் வெற்றி பெற மாட்டார்கள்.) இந்த வசனம் ஒரு நற்செய்தியைக் கொண்டுள்ளது; அது பின்வரும் வசனம் சொல்லும் நற்செய்தியைப் போன்றதேயாகும்: ﴾لَأَنتُمْ أَشَدُّ رَهْبَةً فِى صُدُورِهِمْ مِّنَ اللَّهِ﴿\n\r\n\n\r\n(நிச்சயமாக, அவர்களின் உள்ளங்களில் அல்லாஹ்வை விட உங்களைப் பற்றிய அச்சம்தான் மிகக் கடுமையாக இருக்கிறது.) அதாவது, நயவஞ்சகர்கள் அல்லாஹ்வுக்கு அஞ்சுவதை விட உங்களுக்கு அதிகமாக அஞ்சுகிறார்கள். இதையே அவன் கூறுகிறான்: ﴾إِذَا فَرِيقٌ مِّنْهُمْ يَخْشَوْنَ النَّاسَ كَخَشْيَةِ اللَّهِ أَوْ أَشَدَّ خَشْيَةً﴿\n\r\n\n\r\n(கவனிப்பீராக! அவர்களில் ஒரு பிரிவினர் அல்லாஹ்வுக்கு அஞ்சுவது போல் அல்லது அதைவிடக் கடுமையாக மனிதர்களுக்கு அஞ்சுகின்றனர்.) (4:77) இதனால்தான் அல்லாஹ் கூறினான்: ﴾ذَلِكَ بِأَنَّهُمْ قَوْمٌ لاَّ يَفْقَهُونَ﴿\n\r\n\n\r\n(ஏனென்றால், அவர்கள் விளங்கிக் கொள்ளாத ஒரு சமூகத்தாராக இருக்கிறார்கள்.) பின்னர் அல்லாஹ் கூறினான்: ﴾لَا يُقَاتِلُونَكُمْ جَمِيعاً إِلاَّ فِى قُرًى مُّحَصَّنَةٍ أَوْ مِن وَرَآءِ جُدُرٍ﴿\n\r\n\n\r\n(அவர்கள் அனைவரும் ஒன்று சேர்ந்தும் உங்களுடன் போரிட மாட்டார்கள்; பாதுகாக்கப்பட்ட கோட்டைகளுக்குள்ளிருந்தோ அல்லது மதில்களுக்குப் பின்னாலிருந்தோ தவிர.) அதாவது, அவர்களின் கோழைத்தனம் மற்றும் முஸ்லிம்கள் மீதான அச்சம் காரணமாக, முற்றுகையிடப்பட்ட பாதுகாப்பான கோட்டைகளுக்குப் பின்னாலிருந்து அன்றி முஸ்லிம்களுடன் அவர்கள் போரிட மாட்டார்கள். அவர்கள் தங்களைத் தற்காத்துக் கொள்ள வேண்டிய கட்டாயம் ஏற்படும்போது மட்டுமே போரிடுவார்கள் (முஸ்லிம்களைப் பழிவாங்குவதாக அவர்கள் அச்சுறுத்தினாலும் கூட). உயர்ந்தோனாகிய அல்லாஹ் கூறினான்: ﴾بَأْسُهُمْ بَيْنَهُمْ شَدِيدٌ﴿\n\r\n\n\r\n(அவர்களுக்கிடையே உள்ள பகைமை மிகவும் கடுமையானது.) அதாவது, அவர்கள் ஒருவருக்கொருவர் கொண்டுள்ள பகைமை மிகத் தீவிரமானது. ﴾وَيُذِيقَ بَعْضَكُمْ بَأْسَ بَعْضٍ﴿\n\r\n\n\r\n(உங்களில் சிலர் மற்ற சிலரின் வன்முறையைச் சுவைக்கும்படி செய்வான்.) (6:65) அல்லாஹ் இந்த வசனத்தில் கூறினான்: ﴾تَحْسَبُهُمْ جَمِيعاً وَقُلُوبُهُمْ شَتَّى﴿\n\r\n\n\r\n(அவர்கள் ஒன்றுபட்டிருப்பதாக நீர் நினைப்பீர்; ஆனால் அவர்களின் உள்ளங்கள் பிளவுபட்டுள்ளன.) அதாவது, அவர்கள் படைகளை ஒன்றிணைப்பதைப் பார்த்து அந்தப் படைகள் இணக்கமாக இருப்பதாக ஒருவர் நினைக்கலாம். ஆனால் உண்மையில் அவர்கள் கடுமையாகப் பிளவுபட்டுள்ளனர். இந்த வசனம் நயவஞ்சகர்களையும் வேதக்காரர்களையும் குறிக்கிறது என்று இப்ராஹீம் அந்-நகஈ கூறினார்கள். ﴾ذلِكَ بِأَنَّهُمْ قَوْمٌ لاَّ يَعْقِلُونَ﴿\n\r\n\n\r\n(ஏனென்றால், அவர்கள் புரிந்து கொள்ளாத ஒரு சமூகத்தாராக இருக்கிறார்கள்.) அல்லாஹ் கூறினான்: ﴾كَمَثَلِ الَّذِينَ مِن قَبْلِهِمْ قَرِيباً ذَاقُواْ وَبَالَ أَمْرِهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ ﴿\n\r\n\n\r\n(அவர்கள் தங்களுக்குச் சமீபத்தில் முன் சென்றவர்களைப் போன்றவர்கள்; அவர்கள் தங்கள் செயலின் தீய விளைவைச் சுவைத்தார்கள். மேலும் அவர்களுக்கு வலிமிகுந்த வேதனையுண்டு.) இது பனூ கைனுகா யூத கோத்திரத்தைக் குறிக்கிறது என்று இப்னு அப்பாஸ் (ரழி), கதாதா மற்றும் முஹம்மது பின் இஸ்ஹாக் ஆகியோர் கூறுகிறார்கள். மேலும் முஜாஹித், அஸ்ஸுத்தீ மற்றும் முகாதில் பின் ஹய்யான் ஆகியோர், \"இது பத்ருப் போரில் தோல்வியுற்ற மக்கா முஷ்ரிக்குகளைக் குறிக்கிறது\" என்றும் கூறியுள்ளனர்.\n\r\n\n\r\nநயவஞ்சகர்கள் மற்றும் யூதர்களின் உவமை\n\r\n\n\r\nஅல்லாஹ் கூறினான்: ﴾كَمَثَلِ الشَّيْطَانِ إِذْ قَالَ لِلْإِنسَانِ اكْفُرْ فَلَمَّا كَفَرَ قَالَ إِنِّى بَرِىءٌ مِّنكَ﴿\n\r\n\n\r\n(ஷைத்தானின் உதாரணத்தைப் போன்றது; அவன் மனிதனிடம், \"நிராகரித்துவிடு\" என்று கூறினான். மனிதன் நிராகரித்ததும், ஷைத்தான், \"நிச்சயமாக நான் உன்னை விட்டும் நீங்கிக்கொண்டேன்\" என்று கூறினான்...) அதாவது, \"முஸ்லிம்கள் உங்களுக்கு எதிராகப் போரிட்டால் நாங்கள் உங்களுக்கு உதவுவோம்\" என்று கூறிய நயவஞ்சகர்களின் வாக்குறுதியால் யூதர்கள் ஏமாற்றப்பட்ட உதாரணம், ஷைத்தானுடைய உதாரணத்தைப் போன்றதாகும். நிலைமை விபரீதமாகி யூதர்கள் முற்றுகையிடப்பட்டபோது, நயவஞ்சகர்கள் அவர்களுக்குத் துரோகம் இழைத்து, படுதோல்வியைச் சுவைக்க அவர்களைக் கைவிட்டனர். அவ்வாறே, ஷைத்தான் மனிதர்களை நிராகரிப்பின் பக்கம் ஈர்க்கிறான். அவர்கள் அவனுக்குக் கீழ்ப்படியும்போது, அவன் அவர்களைக் கைவிட்டு, அவர்களின் செயல்களிலிருந்து தான் நீங்கிக்கொண்டதாக அறிவித்து, இவ்வாறு கூறுகிறான்: ﴾إِنِّى أَخَافُ اللَّهَ رَبَّ الْعَالَمِينَ﴿\n\r\n\n\r\n(நிச்சயமாக நான் அகிலங்களின் இறைவனாகிய அல்லாஹ்வுக்கு அஞ்சுகிறேன்!) அல்லாஹ் கூறினான்: ﴾فَكَانَ عَاقِبَتَهُمَا أَنَّهُمَا فِى النَّارِ خَالِدِينَ فِيهَا﴿\n\r\n\n\r\n(எனவே, அவ்விருவரின் முடிவும் நிச்சயமாக அவர்கள் நரக நெருப்பில் தங்குவதாகும்; அதில் அவர்கள் என்றென்றும் இருப்பார்கள்.) அதாவது, நிராகரிப்பைச் செய்யுமாறு தூண்டிய ஷைத்தான் மற்றும் அவனது அழைப்பை ஏற்றுக்கொண்டவர்கள் ஆகிய இருவரின் முடிவும் நரக நெருப்பில் என்றென்றும் தங்குவதாகும். ﴾وَذَلِكَ جَزَآءُ الظَّالِمِينَ﴿\n\r\n\n\r\n(இதுவே அநியாயக்காரர்களின் பிரதிபலனாகும்.) அதாவது, இது ஒவ்வொரு அநியாயக்காரனுக்கும் கிடைக்கின்ற கூலியாகும்."},"18":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=59&ayah=20\" class=\"link\">59:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 59:20 ஐ பார்க்கவும்"},"19":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=59&ayah=20\" class=\"link\">59:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 59:20 ஐ பார்க்கவும்"},"20":{"html":"<strong>தக்வாவைக் கடைப்பிடிப்பதற்கும் மறுமை நாளுக்காகத் தயாராவதற்குமான கட்டளை</strong><br />\r\n<br />\r\nஅல்-முன்திர் பின் ஜரீர் அவர்கள் தனது தந்தை (ஜரீர் (ரழி)) கூறியதாக இமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள்: \"ஒரு நாள் அதிகாலையில் நாங்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுடன் இருந்தபோது, காலணிகளற்ற, ஆடையற்ற (அரை நிர்வாணமான), கம்பளியால் ஆன கோடு போட்ட ஆடைகளை அல்லது போர்வைகளை அணிந்து, கழுத்தில் வாள்களைத் தொங்கவிட்டிருந்த சில மனிதர்கள் அங்கு வந்தனர். அவர்கள் அனைவரும் - அல்லது அவர்களில் பெரும்பாலோர் - முதர் கோத்திரத்தைச் சேர்ந்தவர்கள். அவர்களின் வறுமை நிலையைக் கண்ட அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் திருமுகம் (வருத்தத்தால்) நிறம் மாறியது. பிறகு அவர்கள் (தங்கள் வீட்டிற்குள்) சென்றுவிட்டு வெளியே வந்தார்கள். பிலால் (ரழி) அவர்களை அதான் சொல்லுமாறு பணித்தார்கள். பிலால் (ரழி) அவர்கள் அதானும் இகாமத்தும் கூறினார்கள். நபி (ஸல்) அவர்கள் தொழுகை நடத்தினார்கள். பிறகு மக்களுக்கு உரையாற்றியபோது முதலில் இந்த வசனத்தை ஓதினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">أَيُّهَا</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">اتَّقُوا</span> <span class=\"quran-arabic-font text-success\">رَبَّكُمُ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">خَلَقَكُم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">نَّفْسٍ</span> <span class=\"quran-arabic-font text-success\">وَاحِدَةٍ</span><br />\r\n<br />\r\n(மனிதர்களே! ஒரே ஆன்மாவிலிருந்து உங்களைப் படைத்த உங்கள் இறைவனுக்கு அஞ்சி (தக்வாவுடன்) நடந்து கொள்ளுங்கள்...) (<a href=\"qurandisp.php?sura=4&ayah=1\" class=\"link\">4:1</a>) என்று அந்த வசனத்தின் இறுதி வரை ஓதினார்கள். பிறகு ஸூரத்துல் ஹஷ்ரில் உள்ள இந்த வசனத்தை ஓதினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلْتَنظُرْ</span> <span class=\"quran-arabic-font text-success\">نَفْسٌ</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">قَدَّمَتْ</span> <span class=\"quran-arabic-font text-success\">لِغَدٍ</span><br />\r\n<br />\r\n(...ஒவ்வோர் ஆன்மாவும் நாளைக்காக எதை முற்படுத்தி வைத்துள்ளது என்பதைப் பார்க்கட்டும்.) பிறகு நபி (ஸல்) அவர்கள், \"ஒரு மனிதர் தனது தீனாரையும், தனது திர்ஹத்தையும், தனது ஆடைகளையும், ஒரு ஸாஉ (அளவு) கோதுமையையும், ஒரு ஸாஉ பேரீச்சம் பழத்தையும் தர்மம் செய்யட்டும்\" என்று கூறிவிட்டு, இறுதியில் \"ஒரு பேரீச்சம் பழத்தின் துண்டையேனும் (தர்மம் செய்யுங்கள்)\" என்று கூறினார்கள். அப்போது அன்சாரிகளில் ஒருவர் ஒரு பணப்பையைக் கொண்டு வந்தார். அதைத் தூக்க அவரது கைகள் சிரமப்பட்டன; சொல்லப்போனால் அவரால் அதைத் தூக்கவே முடியவில்லை. பிறகு மக்கள் தொடர்ந்து தர்மம் செய்யத் தொடங்கினர். இறுதியில் உணவுப் பொருட்கள் மற்றும் ஆடைகள் இரண்டு குவியல்களாகக் கிடப்பதை நான் கண்டேன். அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் திருமுகம் பொன்னைப் போல மகிழ்ச்சியால் ஜொலிப்பதைக் கண்டேன். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">سَنَّ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْإِسْلَامِ</span> <span class=\"quran-arabic-font text-success\">سُنَّةً</span> <span class=\"quran-arabic-font text-success\">حَسَنَةً</span> <span class=\"quran-arabic-font text-success\">فَلَهُ</span> <span class=\"quran-arabic-font text-success\">أَجْرُهَا</span> <span class=\"quran-arabic-font text-success\">وَأَجْرُ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">عَمِلَ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">بَعْدَهُ،</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">غَيْرِ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يُنْقَصَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أُجُورِهِمْ</span> <span class=\"quran-arabic-font text-success\">شَيْءٌ،</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">سَنَّ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْإِسْلَامِ</span> <span class=\"quran-arabic-font text-success\">سُنَّةً</span> <span class=\"quran-arabic-font text-success\">سَيِّئَةً</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">وِزْرُهَا</span> <span class=\"quran-arabic-font text-success\">وَوِزْرُ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">عَمِلَ</span> <span class=\"quran-arabic-font text-success\">بِهَا،</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">غَيْرِ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يُنْقَصَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَوْزَارِهِمْ</span> <span class=\"quran-arabic-font text-success\">شَيْءٌ</span>»<br />\r\n<br />\r\n\"இஸ்லாத்தில் யார் ஒரு நன்மையான வழிமுறையை (முன்மாதிரியை) உருவாக்குகிறாரோ, அவருக்கு அதற்குரிய நன்மையும், அவருக்குப் பின் அதைப் பின்பற்றிச் செயல்படுபவர்களின் நன்மையும் உண்டு. ஆனால், செயல்படுபவர்களின் நன்மையில் எதுவும் குறைக்கப்பட மாட்டாது. அதேபோல, இஸ்லாத்தில் யார் ஒரு தீய வழிமுறையை உருவாக்குகிறாரோ, அவருக்கு அந்தப் பாவத்தின் சுமையும், அவருக்குப் பின் அதைப் பின்பற்றுபவர்களின் பாவச் சுமையும் உண்டு. ஆனால், பின்பற்றுபவர்களின் பாவச் சுமைகளில் எதுவும் குறைக்கப்பட மாட்டாது.\" இந்த ஹதீஸை இமாம் முஸ்லிம் அவர்கள் ஷுஃபா அவர்களின் அறிவிப்பாளர் தொடர் வழியாகப் பதிவு செய்துள்ளார்கள். எனவே, அல்லாஹ்வின் இக்கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">أَيُّهَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">آمَنُوا</span> <span class=\"quran-arabic-font text-success\">اتَّقُوا</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span><br />\r\n<br />\r\n(நம்பிக்கை கொண்டவர்களே! அல்லாஹ்வுக்கு அஞ்சி (தக்வாவுடன்) நடந்து கொள்ளுங்கள்), என்பது அல்லாஹ் ஏவியவற்றுக்குக் கீழ்ப்படிந்து, அவன் தடுத்தவற்றிலிருந்து விலகி இருப்பதன் மூலம் பேணப்படும் தக்வாவையே வலியுறுத்துகிறது. அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلْتَنظُرْ</span> <span class=\"quran-arabic-font text-success\">نَفْسٌ</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">قَدَّمَتْ</span> <span class=\"quran-arabic-font text-success\">لِغَدٍ</span><br />\r\n<br />\r\n(...ஒவ்வோர் ஆன்மாவும் நாளைக்காக எதை முற்படுத்தி இருக்கிறது என்பதைப் பார்க்கட்டும்.) அதாவது, நீங்கள் விசாரிக்கப்படுவதற்கு முன்னரே உங்களை நீங்களே சுய விசாரணை செய்து கொள்ளுங்கள். நீங்கள் மீண்டு வந்து உங்கள் இறைவனின் முன்னிலையில் நிறுத்தப்படும் அந்த நாளுக்காக, என்னென்ன நற்செயல்களைச் சேமித்து வைத்திருக்கின்றீர்கள் என்பதைச் சிந்தித்துப் பாருங்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاتَّقُوا</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span><br />\r\n<br />\r\n(அல்லாஹ்வுக்கு அஞ்சி (தக்வாவுடன்) நடந்து கொள்ளுங்கள்.) இங்கே மீண்டும் தக்வா வலியுறுத்தப்படுகிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">خَبِيرٌ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ</span><br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ் நீங்கள் செய்பவற்றை நன்கு அறிந்தவன்.) மனிதர்களே! நிச்சயமாக அல்லாஹ் உங்கள் செயல்கள் மற்றும் கர்மங்கள் அனைத்தையும் நன்கு அறிந்தவன் என்பதை அவன் உறுதிப்படுத்துகிறான். உங்களைப் பற்றிய எந்தவொரு விஷயமும் அவனது கண்காணிப்பிலிருந்து தப்புவதில்லை. சிறியதோ அல்லது பெரியதோ உங்கள் எந்தக் காரியமும் அவன் அறியாதது அல்ல.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">تَكُونُوا</span> <span class=\"quran-arabic-font text-success\">كَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">نَسُوا</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">فَأَنسَاهُمْ</span> <span class=\"quran-arabic-font text-success\">أَنفُسَهُمْ</span><br />\r\n<br />\r\n(மேலும் அல்லாஹ்வை மறந்தவர்களைப் போல நீங்கள் ஆகிவிடாதீர்கள்; அதனால் அவன் அவர்களைத் தங்களையே மறக்கச் செய்தான்.) அதாவது, உன்னதமான அல்லாஹ்வின் நினைவை மறந்துவிடாதீர்கள். அப்படி மறந்தால், நீங்கள் அவனிடம் மீண்டு வரும்போது உங்களுக்குப் பயனளிக்கக்கூடிய நற்செயல்களைச் செய்வதை அவன் உங்களை மறக்கச் செய்துவிடுவான். ஏனெனில், பிரதிபலன் என்பது செயலைப் பொறுத்தே அமையும். இதனால்தான் அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أُولَٰئِكَ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْفَاسِقُونَ</span><br />\r\n<br />\r\n(அவர்களே வரம்பு மீறியவர்கள் (ஃபாஸிக்குகள்).) அதாவது, அல்லாஹ்வின் கட்டளைகளுக்குக் கீழ்ப்படிய மறுப்பவர்கள். இவர்கள் மறுமை நாளில் அழிவையும், அவனிடம் மீளும்போது தோல்வியையும் அடைவார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">أَيُّهَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">آمَنُوا</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تُلْهِكُمْ</span> <span class=\"quran-arabic-font text-success\">أَمْوَالُكُمْ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">أَوْلَادُكُمْ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">ذِكْرِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">ۚ</span> <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يَفْعَلْ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">فَأُولَٰئِكَ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْخَاسِرُونَ</span><br />\r\n<br />\r\n(நம்பிக்கை கொண்டவர்களே! உங்கள் செல்வங்களோ அல்லது உங்கள் பிள்ளைகளோ உங்களை அல்லாஹ்வின் நினைவிலிருந்து திசைதிருப்பி விட வேண்டாம். எவர் இவ்வாறு செய்கிறாரோ அவர்களே நஷ்டவாளிகள்.) (<a href=\"qurandisp.php?sura=63&ayah=9\" class=\"link\">63:9</a>)<br />\r\n<br />\r\n<strong>சொர்க்கவாசிகளும் நரகவாசிகளும் ஒருபோதும் சமமாக மாட்டார்கள்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَسْتَوِي</span> <span class=\"quran-arabic-font text-success\">أَصْحَابُ</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">وَأَصْحَابُ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span><br />\r\n<br />\r\n(நரகவாசிகளும் சொர்க்கவாசிகளும் சமமாக மாட்டார்கள்.) அதாவது, மறுமை நாளில் உன்னதமான அல்லாஹ்வின் தீர்ப்பின்படி இவ்விரு பிரிவினரும் ஒருபோதும் சமமாக முடியாது. அல்லாஹ் பிற வசனங்களில் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">حَسِبَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">اجْتَرَحُوا</span> <span class=\"quran-arabic-font text-success\">السَّيِّئَاتِ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">نَّجْعَلَهُمْ</span> <span class=\"quran-arabic-font text-success\">كَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">آمَنُوا</span> <span class=\"quran-arabic-font text-success\">وَعَمِلُوا</span> <span class=\"quran-arabic-font text-success\">الصَّالِحَاتِ</span> <span class=\"quran-arabic-font text-success\">سَوَاءً</span> <span class=\"quran-arabic-font text-success\">مَّحْيَاهُمْ</span> <span class=\"quran-arabic-font text-success\">وَمَمَاتُهُمْ</span> <span class=\"quran-arabic-font text-success\">ۚ</span> <span class=\"quran-arabic-font text-success\">سَاءَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَحْكُمُونَ</span><br />\r\n<br />\r\n(அல்லது, தீய செயல்களைச் செய்தவர்கள், நாம் அவர்களை ஈமான் கொண்டு நற்செயல்கள் புரிந்தவர்களுக்குச் சமமாக ஆக்குவோம் என்று எண்ணுகிறார்களா? அவர்களின் வாழ்வும் மரணமும் சமமாகுமா? அவர்கள் செய்யும் தீர்ப்பு மிகக் கெட்டது.) (<a href=\"qurandisp.php?sura=45&ayah=21\" class=\"link\">45:21</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يَسْتَوِي</span> <span class=\"quran-arabic-font text-success\">الْأَعْمَىٰ</span> <span class=\"quran-arabic-font text-success\">وَالْبَصِيرُ</span> <span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">آمَنُوا</span> <span class=\"quran-arabic-font text-success\">وَعَمِلُوا</span> <span class=\"quran-arabic-font text-success\">الصَّالِحَاتِ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">الْمُسِيءُ</span> <span class=\"quran-arabic-font text-success\">ۚ</span> <span class=\"quran-arabic-font text-success\">قَلِيلًا</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">تَتَذَكَّرُونَ</span><br />\r\n<br />\r\n(பார்வையற்றவரும் பார்வையுடையவரும் சமமாக மாட்டார்கள்; அவ்வாறே, நம்பிக்கை கொண்டு நற்செயல்கள் புரிபவர்களும் தீமை செய்பவர்களும் (சமமாக மாட்டார்கள்). நீங்கள் மிகக் குறைவாகவே படிப்பினை பெறுகிறீர்கள்.) (<a href=\"qurandisp.php?sura=40&ayah=58\" class=\"link\">40:58</a>) மற்றும்<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">نَجْعَلُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">آمَنُوا</span> <span class=\"quran-arabic-font text-success\">وَعَمِلُوا</span> <span class=\"quran-arabic-font text-success\">الصَّالِحَاتِ</span> <span class=\"quran-arabic-font text-success\">كَالْمُفْسِدِينَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">نَجْعَلُ</span> <span class=\"quran-arabic-font text-success\">الْمُتَّقِينَ</span> <span class=\"quran-arabic-font text-success\">كَالْفُجَّارِ</span><br />\r\n<br />\r\n(நம்பிக்கை கொண்டு நற்செயல்கள் புரிந்தவர்களை, பூமியில் குழப்பம் விளைவிப்பவர்களைப் போல நாம் ஆக்குவோமா? அல்லது தக்வா உடையவர்களைப் பாவிகளைப் போல ஆக்குவோமா?) (<a href=\"qurandisp.php?sura=38&ayah=28\" class=\"link\">38:28</a>). எனவே, அல்லாஹ் நல்லவர்களைக் கண்ணியப்படுத்துவான் என்றும் பாவிகளை இழிவுபடுத்துவான் என்றும் உறுதிப்படுத்துகிறான். இதனால்தான் அவன் இங்கே இவ்வாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَصْحَابُ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْفَائِزُونَ</span><br />\r\n<br />\r\n(சொர்க்கவாசிகளே வெற்றியாளர்கள்.) அதாவது, கண்ணியமிக்க மேலான அல்லாஹ்வின் வேதனையிலிருந்து பாதுகாப்பையும் விடுதலையையும் பெற்று, அவனது நற்கூலியை அடைந்தவர்கள் அவர்களே.<br />\r\n<br />","text":"தக்வாவைக் கடைப்பிடிப்பதற்கும் மறுமை நாளுக்காகத் தயாராவதற்குமான கட்டளை\n\r\n\n\r\nஅல்-முன்திர் பின் ஜரீர் அவர்கள் தனது தந்தை (ஜரீர் (ரழி)) கூறியதாக இமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள்: \"ஒரு நாள் அதிகாலையில் நாங்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுடன் இருந்தபோது, காலணிகளற்ற, ஆடையற்ற (அரை நிர்வாணமான), கம்பளியால் ஆன கோடு போட்ட ஆடைகளை அல்லது போர்வைகளை அணிந்து, கழுத்தில் வாள்களைத் தொங்கவிட்டிருந்த சில மனிதர்கள் அங்கு வந்தனர். அவர்கள் அனைவரும் - அல்லது அவர்களில் பெரும்பாலோர் - முதர் கோத்திரத்தைச் சேர்ந்தவர்கள். அவர்களின் வறுமை நிலையைக் கண்ட அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் திருமுகம் (வருத்தத்தால்) நிறம் மாறியது. பிறகு அவர்கள் (தங்கள் வீட்டிற்குள்) சென்றுவிட்டு வெளியே வந்தார்கள். பிலால் (ரழி) அவர்களை அதான் சொல்லுமாறு பணித்தார்கள். பிலால் (ரழி) அவர்கள் அதானும் இகாமத்தும் கூறினார்கள். நபி (ஸல்) அவர்கள் தொழுகை நடத்தினார்கள். பிறகு மக்களுக்கு உரையாற்றியபோது முதலில் இந்த வசனத்தை ஓதினார்கள்:\n\r\n\n\r\nيَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُم مِّن نَّفْسٍ وَاحِدَةٍ\n\r\n\n\r\n(மனிதர்களே! ஒரே ஆன்மாவிலிருந்து உங்களைப் படைத்த உங்கள் இறைவனுக்கு அஞ்சி (தக்வாவுடன்) நடந்து கொள்ளுங்கள்...) (4:1) என்று அந்த வசனத்தின் இறுதி வரை ஓதினார்கள். பிறகு ஸூரத்துல் ஹஷ்ரில் உள்ள இந்த வசனத்தை ஓதினார்கள்:\n\r\n\n\r\nوَلْتَنظُرْ نَفْسٌ مَّا قَدَّمَتْ لِغَدٍ\n\r\n\n\r\n(...ஒவ்வோர் ஆன்மாவும் நாளைக்காக எதை முற்படுத்தி வைத்துள்ளது என்பதைப் பார்க்கட்டும்.) பிறகு நபி (ஸல்) அவர்கள், \"ஒரு மனிதர் தனது தீனாரையும், தனது திர்ஹத்தையும், தனது ஆடைகளையும், ஒரு ஸாஉ (அளவு) கோதுமையையும், ஒரு ஸாஉ பேரீச்சம் பழத்தையும் தர்மம் செய்யட்டும்\" என்று கூறிவிட்டு, இறுதியில் \"ஒரு பேரீச்சம் பழத்தின் துண்டையேனும் (தர்மம் செய்யுங்கள்)\" என்று கூறினார்கள். அப்போது அன்சாரிகளில் ஒருவர் ஒரு பணப்பையைக் கொண்டு வந்தார். அதைத் தூக்க அவரது கைகள் சிரமப்பட்டன; சொல்லப்போனால் அவரால் அதைத் தூக்கவே முடியவில்லை. பிறகு மக்கள் தொடர்ந்து தர்மம் செய்யத் தொடங்கினர். இறுதியில் உணவுப் பொருட்கள் மற்றும் ஆடைகள் இரண்டு குவியல்களாகக் கிடப்பதை நான் கண்டேன். அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் திருமுகம் பொன்னைப் போல மகிழ்ச்சியால் ஜொலிப்பதைக் கண்டேன். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«مَنْ سَنَّ فِي الْإِسْلَامِ سُنَّةً حَسَنَةً فَلَهُ أَجْرُهَا وَأَجْرُ مَنْ عَمِلَ بِهَا بَعْدَهُ، مِنْ غَيْرِ أَنْ يُنْقَصَ مِنْ أُجُورِهِمْ شَيْءٌ، وَمَنْ سَنَّ فِي الْإِسْلَامِ سُنَّةً سَيِّئَةً كَانَ عَلَيْهِ وِزْرُهَا وَوِزْرُ مَنْ عَمِلَ بِهَا، مِنْ غَيْرِ أَنْ يُنْقَصَ مِنْ أَوْزَارِهِمْ شَيْءٌ»\n\r\n\n\r\n\"இஸ்லாத்தில் யார் ஒரு நன்மையான வழிமுறையை (முன்மாதிரியை) உருவாக்குகிறாரோ, அவருக்கு அதற்குரிய நன்மையும், அவருக்குப் பின் அதைப் பின்பற்றிச் செயல்படுபவர்களின் நன்மையும் உண்டு. ஆனால், செயல்படுபவர்களின் நன்மையில் எதுவும் குறைக்கப்பட மாட்டாது. அதேபோல, இஸ்லாத்தில் யார் ஒரு தீய வழிமுறையை உருவாக்குகிறாரோ, அவருக்கு அந்தப் பாவத்தின் சுமையும், அவருக்குப் பின் அதைப் பின்பற்றுபவர்களின் பாவச் சுமையும் உண்டு. ஆனால், பின்பற்றுபவர்களின் பாவச் சுமைகளில் எதுவும் குறைக்கப்பட மாட்டாது.\" இந்த ஹதீஸை இமாம் முஸ்லிம் அவர்கள் ஷுஃபா அவர்களின் அறிவிப்பாளர் தொடர் வழியாகப் பதிவு செய்துள்ளார்கள். எனவே, அல்லாஹ்வின் இக்கூற்று:\n\r\n\n\r\nيَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ\n\r\n\n\r\n(நம்பிக்கை கொண்டவர்களே! அல்லாஹ்வுக்கு அஞ்சி (தக்வாவுடன்) நடந்து கொள்ளுங்கள்), என்பது அல்லாஹ் ஏவியவற்றுக்குக் கீழ்ப்படிந்து, அவன் தடுத்தவற்றிலிருந்து விலகி இருப்பதன் மூலம் பேணப்படும் தக்வாவையே வலியுறுத்துகிறது. அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَلْتَنظُرْ نَفْسٌ مَّا قَدَّمَتْ لِغَدٍ\n\r\n\n\r\n(...ஒவ்வோர் ஆன்மாவும் நாளைக்காக எதை முற்படுத்தி இருக்கிறது என்பதைப் பார்க்கட்டும்.) அதாவது, நீங்கள் விசாரிக்கப்படுவதற்கு முன்னரே உங்களை நீங்களே சுய விசாரணை செய்து கொள்ளுங்கள். நீங்கள் மீண்டு வந்து உங்கள் இறைவனின் முன்னிலையில் நிறுத்தப்படும் அந்த நாளுக்காக, என்னென்ன நற்செயல்களைச் சேமித்து வைத்திருக்கின்றீர்கள் என்பதைச் சிந்தித்துப் பாருங்கள்.\n\r\n\n\r\nوَاتَّقُوا اللَّهَ\n\r\n\n\r\n(அல்லாஹ்வுக்கு அஞ்சி (தக்வாவுடன்) நடந்து கொள்ளுங்கள்.) இங்கே மீண்டும் தக்வா வலியுறுத்தப்படுகிறது.\n\r\n\n\r\nإِنَّ اللَّهَ خَبِيرٌ بِمَا تَعْمَلُونَ\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ் நீங்கள் செய்பவற்றை நன்கு அறிந்தவன்.) மனிதர்களே! நிச்சயமாக அல்லாஹ் உங்கள் செயல்கள் மற்றும் கர்மங்கள் அனைத்தையும் நன்கு அறிந்தவன் என்பதை அவன் உறுதிப்படுத்துகிறான். உங்களைப் பற்றிய எந்தவொரு விஷயமும் அவனது கண்காணிப்பிலிருந்து தப்புவதில்லை. சிறியதோ அல்லது பெரியதோ உங்கள் எந்தக் காரியமும் அவன் அறியாதது அல்ல.\n\r\n\n\r\nوَلَا تَكُونُوا كَالَّذِينَ نَسُوا اللَّهَ فَأَنسَاهُمْ أَنفُسَهُمْ\n\r\n\n\r\n(மேலும் அல்லாஹ்வை மறந்தவர்களைப் போல நீங்கள் ஆகிவிடாதீர்கள்; அதனால் அவன் அவர்களைத் தங்களையே மறக்கச் செய்தான்.) அதாவது, உன்னதமான அல்லாஹ்வின் நினைவை மறந்துவிடாதீர்கள். அப்படி மறந்தால், நீங்கள் அவனிடம் மீண்டு வரும்போது உங்களுக்குப் பயனளிக்கக்கூடிய நற்செயல்களைச் செய்வதை அவன் உங்களை மறக்கச் செய்துவிடுவான். ஏனெனில், பிரதிபலன் என்பது செயலைப் பொறுத்தே அமையும். இதனால்தான் அல்லாஹ் கூறினான்:\n\r\n\n\r\nأُولَٰئِكَ هُمُ الْفَاسِقُونَ\n\r\n\n\r\n(அவர்களே வரம்பு மீறியவர்கள் (ஃபாஸிக்குகள்).) அதாவது, அல்லாஹ்வின் கட்டளைகளுக்குக் கீழ்ப்படிய மறுப்பவர்கள். இவர்கள் மறுமை நாளில் அழிவையும், அவனிடம் மீளும்போது தோல்வியையும் அடைவார்கள்.\n\r\n\n\r\nيَا أَيُّهَا الَّذِينَ آمَنُوا لَا تُلْهِكُمْ أَمْوَالُكُمْ وَلَا أَوْلَادُكُمْ عَن ذِكْرِ اللَّهِ ۚ وَمَن يَفْعَلْ ذَلِكَ فَأُولَٰئِكَ هُمُ الْخَاسِرُونَ\n\r\n\n\r\n(நம்பிக்கை கொண்டவர்களே! உங்கள் செல்வங்களோ அல்லது உங்கள் பிள்ளைகளோ உங்களை அல்லாஹ்வின் நினைவிலிருந்து திசைதிருப்பி விட வேண்டாம். எவர் இவ்வாறு செய்கிறாரோ அவர்களே நஷ்டவாளிகள்.) (63:9)\n\r\n\n\r\nசொர்க்கவாசிகளும் நரகவாசிகளும் ஒருபோதும் சமமாக மாட்டார்கள்\n\r\n\n\r\nஅல்லாஹ் கூறினான்:\n\r\n\n\r\nلَا يَسْتَوِي أَصْحَابُ النَّارِ وَأَصْحَابُ الْجَنَّةِ\n\r\n\n\r\n(நரகவாசிகளும் சொர்க்கவாசிகளும் சமமாக மாட்டார்கள்.) அதாவது, மறுமை நாளில் உன்னதமான அல்லாஹ்வின் தீர்ப்பின்படி இவ்விரு பிரிவினரும் ஒருபோதும் சமமாக முடியாது. அல்லாஹ் பிற வசனங்களில் கூறுகிறான்:\n\r\n\n\r\nأَمْ حَسِبَ الَّذِينَ اجْتَرَحُوا السَّيِّئَاتِ أَن نَّجْعَلَهُمْ كَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ سَوَاءً مَّحْيَاهُمْ وَمَمَاتُهُمْ ۚ سَاءَ مَا يَحْكُمُونَ\n\r\n\n\r\n(அல்லது, தீய செயல்களைச் செய்தவர்கள், நாம் அவர்களை ஈமான் கொண்டு நற்செயல்கள் புரிந்தவர்களுக்குச் சமமாக ஆக்குவோம் என்று எண்ணுகிறார்களா? அவர்களின் வாழ்வும் மரணமும் சமமாகுமா? அவர்கள் செய்யும் தீர்ப்பு மிகக் கெட்டது.) (45:21)\n\r\n\n\r\nوَمَا يَسْتَوِي الْأَعْمَىٰ وَالْبَصِيرُ وَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَلَا الْمُسِيءُ ۚ قَلِيلًا مَّا تَتَذَكَّرُونَ\n\r\n\n\r\n(பார்வையற்றவரும் பார்வையுடையவரும் சமமாக மாட்டார்கள்; அவ்வாறே, நம்பிக்கை கொண்டு நற்செயல்கள் புரிபவர்களும் தீமை செய்பவர்களும் (சமமாக மாட்டார்கள்). நீங்கள் மிகக் குறைவாகவே படிப்பினை பெறுகிறீர்கள்.) (40:58) மற்றும்\n\r\n\n\r\nأَمْ نَجْعَلُ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ كَالْمُفْسِدِينَ فِي الْأَرْضِ أَمْ نَجْعَلُ الْمُتَّقِينَ كَالْفُجَّارِ\n\r\n\n\r\n(நம்பிக்கை கொண்டு நற்செயல்கள் புரிந்தவர்களை, பூமியில் குழப்பம் விளைவிப்பவர்களைப் போல நாம் ஆக்குவோமா? அல்லது தக்வா உடையவர்களைப் பாவிகளைப் போல ஆக்குவோமா?) (38:28). எனவே, அல்லாஹ் நல்லவர்களைக் கண்ணியப்படுத்துவான் என்றும் பாவிகளை இழிவுபடுத்துவான் என்றும் உறுதிப்படுத்துகிறான். இதனால்தான் அவன் இங்கே இவ்வாறு கூறுகிறான்:\n\r\n\n\r\nأَصْحَابُ الْجَنَّةِ هُمُ الْفَائِزُونَ\n\r\n\n\r\n(சொர்க்கவாசிகளே வெற்றியாளர்கள்.) அதாவது, கண்ணியமிக்க மேலான அல்லாஹ்வின் வேதனையிலிருந்து பாதுகாப்பையும் விடுதலையையும் பெற்று, அவனது நற்கூலியை அடைந்தவர்கள் அவர்களே."},"21":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=59&ayah=24\" class=\"link\">59:24</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 59:24 ஐ பார்க்கவும்"},"22":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=59&ayah=24\" class=\"link\">59:24</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 59:24 ஐ பார்க்கவும்"},"23":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=59&ayah=24\" class=\"link\">59:24</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 59:24 ஐ பார்க்கவும்"},"24":{"html":"<strong>குர்ஆனின் மகத்துவத்தை உறுதிப்படுத்துதல்</strong><br />\r\n<br />\r\nமேன்மைமிக்க அல்லாஹ் குர்ஆனின் மகத்துவத்தையும், அதன் உயர்ந்த அந்தஸ்தையும், அதைக் கேட்கும்போது உள்ளங்கள் பணிந்து பிளந்து போவதற்கும் அது தகுதியானது என்பதையும் வலியுறுத்துகிறான். ஏனெனில், அதில் உண்மையான வாக்குறுதிகளும் உறுதியான எச்சரிக்கைகளும் இடம் பெற்றுள்ளன.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَوْ</span> <span class=\"quran-arabic-font text-success\">أَنزَلْنَا</span> <span class=\"quran-arabic-font text-success\">هَذَا</span> <span class=\"quran-arabic-font text-success\">الْقُرْآنَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">جَبَلٍ</span> <span class=\"quran-arabic-font text-success\">لَّرَأَيْتَهُ</span> <span class=\"quran-arabic-font text-success\">خَاشِعًا</span> <span class=\"quran-arabic-font text-success\">مُّتَصَدِّعًا</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">خَشْيَةِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span><br />\r\n<br />\r\n(நாம் இந்த குர்ஆனை ஒரு மலையின் மீது இறக்கியிருந்தால், அது அல்லாஹ்வின் பயத்தால் பணிந்து பிளந்து போவதை நீர் நிச்சயமாகக் கண்டிருப்பீர்.) கடினமான மற்றும் பிரம்மாண்டமான ஒரு மலையே, இந்த குர்ஆனை விளங்கிக்கொள்ளும் திறன் அதற்கு வழங்கப்பட்டால், மேன்மைமிக்க அல்லாஹ்வின் மீதான அச்சத்தால் பணிந்து நொறுங்கிவிடும் என்றால், மனிதர்களே! உங்களைப் பற்றி என்ன நினைக்கிறீர்கள்? அல்லாஹ்வின் கட்டளைகளையும் அவனது வேதத்தையும் நீங்கள் விளங்கிக்கொண்டும், உங்கள் உள்ளங்கள் ஏன் அல்லாஹ்வின் பயத்தால் மென்மையாகவும் பணிவாகவும் மாறுவதில்லை? இதனால்தான் அல்லாஹ் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَتِلْكَ</span> <span class=\"quran-arabic-font text-success\">الْأَمْثَالُ</span> <span class=\"quran-arabic-font text-success\">نَضْرِبُهَا</span> <span class=\"quran-arabic-font text-success\">لِلنَّاسِ</span> <span class=\"quran-arabic-font text-success\">لَعَلَّهُمْ</span> <span class=\"quran-arabic-font text-success\">يَتَفَكَّرُونَ</span><br />\r\n<br />\r\n(மனிதர்கள் சிந்திப்பதற்காக இத்தகைய உவமைகளை நாம் கூறுகிறோம்.) அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தமக்காக ஒரு மின்பரை (உரை மேடை) செய்யச் சொன்னார்கள் என்று ஒரு 'முதவாதிர்' தரத்திலான ஹதீஸில் கூறப்பட்டுள்ளது. அதற்கு முன்பு, அவர்கள் மஸ்ஜிதில் ஒரு மரக்கட்டையின் அருகே நின்று உரை நிகழ்த்தி வந்தார்கள். மின்பர் செய்யப்பட்டு மஸ்ஜிதில் வைக்கப்பட்டபோது, நபி (ஸல்) அவர்கள் உரை நிகழ்த்தச் செல்வதற்காக அந்த மரக்கட்டையைக் கடந்து மின்பரை நோக்கிச் சென்றார்கள்; அப்போது அந்த மரக்கட்டை ஒரு கைக்குழந்தையைப் போல அழத் தொடங்கியது. தன் அருகில் ஓதப்பட்டு வந்த அல்லாஹ்வின் நினைவூட்டல்களையும் வஹீ (இறைச்செய்தி)யையும் கேட்க முடியவில்லையே என்று அந்த மரக்கட்டை ஏங்கியது. இந்த ஹதீஸை அறிவித்த பிறகு அல்-ஹஸன் அல்-பஸரி அவர்கள் கூறினார்கள்: \"மனிதர்களே! அந்த மரக்கட்டையை விட அல்லாஹ்வின் தூதர் (ஸல்) அவர்களைப் பிரிந்து ஏங்குவதற்கு நீங்கள் தான் அதிக தகுதியுடையவர்கள்!\" அதேபோன்று, இந்த கண்ணியமிக்க ஆயத் இவ்வாறு வினவுகிறது: திடமான மலைகளே அல்லாஹ்வின் பேச்சைக் கேட்டு, அதை விளங்கிக்கொண்டால், அல்லாஹ்வின் பயத்தால் பணிந்து பிளந்துவிடுகின்றன என்றால், குர்ஆனைக் கேட்டு, அதை விளங்கிக்கொண்ட மனிதர்களான உங்களின் நிலை என்ன? மேன்மைமிக்க அல்லாஹ் மற்றொரு ஆயத்தில் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">قُرْآنًا</span> <span class=\"quran-arabic-font text-success\">سُيِّرَتْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">الْجِبَالُ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">قُطِّعَتْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضُ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">كُلِّمَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">الْمَوْتَى</span><br />\r\n<br />\r\n(மேலும், ஒரு குர்ஆன் இருந்திருந்தால், அதன் மூலம் மலைகள் நகர்த்தப்பட்டிருக்கும், அல்லது பூமி பிளக்கப்பட்டிருக்கும், அல்லது இறந்தவர்கள் பேச வைக்கப்பட்டிருப்பார்கள்.) (<a href=\"qurandisp.php?sura=13&ayah=31\" class=\"link\">13:31</a>). இத்தகைய சிறப்புகளைக் கொண்ட ஒரு குர்ஆன் இருந்திருந்தால், அது இந்த குர்ஆனாகத்தான் இருந்திருக்கும் என்பதே இந்த ஆயத்தின் பொருளாகும் என்று நாம் குறிப்பிட்டுள்ளோம். மேன்மைமிக்க அல்லாஹ் மற்றொரு ஆயத்தில் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْحِجَارَةِ</span> <span class=\"quran-arabic-font text-success\">لَمَا</span> <span class=\"quran-arabic-font text-success\">يَتَفَجَّرُ</span> <span class=\"quran-arabic-font text-success\">مِنْهُ</span> <span class=\"quran-arabic-font text-success\">الْأَنْهَارُ</span> <span class=\"quran-arabic-font text-success\">وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span> <span class=\"quran-arabic-font text-success\">لَمَا</span> <span class=\"quran-arabic-font text-success\">يَشَّقَّقُ</span> <span class=\"quran-arabic-font text-success\">فَيَخْرُجُ</span> <span class=\"quran-arabic-font text-success\">مِنْهُ</span> <span class=\"quran-arabic-font text-success\">الْمَاءُ</span> <span class=\"quran-arabic-font text-success\">وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span> <span class=\"quran-arabic-font text-success\">لَمَا</span> <span class=\"quran-arabic-font text-success\">يَهْبِطُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">خَشْيَةِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span><br />\r\n<br />\r\n(நிச்சயமாக, கற்களில் சிலவற்றிலிருந்து ஆறுகள் பீறிட்டு ஓடுகின்றன; நிச்சயமாக, அவற்றில் சில பிளந்து, அவற்றிலிருந்து தண்ணீர் வெளிப்படுகிறது; நிச்சயமாக, அவற்றில் சில அல்லாஹ்வின் பயத்தால் கீழே விழுகின்றன.) (<a href=\"qurandisp.php?sura=2&ayah=74\" class=\"link\">2:74</a>)<br />\r\n<br />\r\n<strong>அவனது திருநாமங்களையும் பண்புகளையும் குறிப்பிடுவதன் மூலம் மேன்மைமிக்க அல்லாஹ்வைத் துதித்தல்</strong><br />\r\n<br />\r\nமேன்மைமிக்க அல்லாஹ் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">إِلَهَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">عَالِمُ</span> <span class=\"quran-arabic-font text-success\">الْغَيْبِ</span> <span class=\"quran-arabic-font text-success\">وَالشَّهَادَةِ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَنُ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمُ</span><br />\r\n<br />\r\n(அவனே அல்லாஹ், அவனைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை (லா இலாஹ இல்லா ஹுவ), மறைவானவற்றையும் வெளிப்படையானவற்றையும் நன்கறிந்தவன். அவன் அளவற்ற அருளாளன், நிகரற்ற அன்புடையோன்.) வணக்கத்திற்குரியவன் அவன் ஒருவனே என்று அல்லாஹ் கூறுகிறான். அகிலத்தைப் படைத்து பரிபாலிக்கும் இறைவன் அல்லது கடவுள் அவனைத் தவிர வேறு யாருமில்லை. அல்லாஹ்வையன்றி வணங்கப்படுபவை அனைத்தும் போலியான தெய்வங்களே. அல்லாஹ் மறைவானவற்றையும் வெளிப்படையானவற்றையும் நன்கறிந்தவன்; நாம் காணும் படைப்பினங்கள் மற்றும் காணமுடியாத படைப்பினங்கள் தொடர்பான அனைத்தையும் அவன் அறிவான். வானத்திலோ பூமியிலோ உள்ள எதுவும் அவனது அறிவிலிருந்து தப்புவதில்லை; அது எவ்வளவு பெரியதாக இருந்தாலும் அல்லது அற்பமானதாக இருந்தாலும், இருளில் உள்ள எறும்புகள் உட்பட அனைத்தையும் அவன் அறிகிறான். அல்லாஹ்வின் கூற்று,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَنُ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمُ</span><br />\r\n<br />\r\n(அவன் அளவற்ற அருளாளன், நிகரற்ற அன்புடையோன்.) இந்த தஃப்ஸீரின் ஆரம்பத்திலேயே இது பற்றி விரிவாக விளக்கப்பட்டுள்ளது, எனவே அதை மீண்டும் இங்கே விளக்குவது அவசியமில்லை. மேலும், அல்லாஹ் தனது படைப்புகள் அனைத்தையும் உள்ளடக்கிய பரந்த கருணையின் உரிமையாளன் என்பதை இது உறுதிப்படுத்துகிறது. அவன் இம்மையிலும் மறுமையிலும் அர்-ரஹ்மான் மற்றும் அர்-ரஹீம் ஆக இருக்கிறான். மேன்மைமிக்க அல்லாஹ் மற்ற ஆயத்துகளில் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَرَحْمَتِي</span> <span class=\"quran-arabic-font text-success\">وَسِعَتْ</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span><br />\r\n<br />\r\n(என் கருணை எல்லாப் பொருட்களையும் சூழ்ந்துள்ளது.) (<a href=\"qurandisp.php?sura=7&ayah=156\" class=\"link\">7:156</a>),<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَتَبَ</span> <span class=\"quran-arabic-font text-success\">رَبُّكُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">نَفْسِهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَةَ</span><br />\r\n<br />\r\n(உங்கள் இறைவன் தன் மீது கருணையை விதித்துக் கொண்டான்.) (<a href=\"qurandisp.php?sura=6&ayah=54\" class=\"link\">6:54</a>), மற்றும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">بِفَضْلِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَبِرَحْمَتِهِ</span> <span class=\"quran-arabic-font text-success\">فَبِذَلِكَ</span> <span class=\"quran-arabic-font text-success\">فَلْيَفْرَحُواْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ</span> <span class=\"quran-arabic-font text-success\">مِّمَّا</span> <span class=\"quran-arabic-font text-success\">يَجْمَعُونَ</span><br />\r\n<br />\r\n(கூறுவீராக: \"அல்லாஹ்வின் அருட்கொடையிலும் அவனது கருணையிலும் - அதிலேயே அவர்கள் மகிழ்ச்சியடையட்டும்.\" அது அவர்கள் சேகரித்து வைக்கும் (செல்வத்தை) விடச் சிறந்தது.) (<a href=\"qurandisp.php?sura=10&ayah=58\" class=\"link\">10:58</a>) மேன்மைமிக்க அல்லாஹ் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">إِلَهَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">الْمَلِكُ</span><br />\r\n<br />\r\n(அவனே அல்லாஹ், அவனைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை (லா இலாஹ இல்லா ஹுவ), அல்-மாலிக்.) அல்-மாலிக் என்றால் \"அனைத்துப் பொருட்களின் உரிமையாளன் மற்றும் அரசன்\" என்று பொருள். எவ்வித எதிர்ப்போ தடையோ இன்றி அவற்றின் மீது முழு அதிகாரம் கொண்டவன். அல்லாஹ்வின் கூற்று,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الْقُدُّوسُ</span><br />\r\n<br />\r\n(அல்-குத்தூஸ்,) என்பதற்கு வஹ்ப் பின் முனப்பிஹ் அவர்கள் \"பரிசுத்தமானவன்\" என்று பொருள் கூறியுள்ளார். முஜாஹித் மற்றும் கத்தாதா ஆகியோர் \"பாக்கியம் மிக்கவன்\" என்று பொருள் கூறியுள்ளனர். இப்னு ஜுரைஜ் அவர்கள் \"கண்ணியமிக்க வானவர்கள் எவனைத் துதிக்கிறார்களோ அவன்\" என்று பொருள் கூறியுள்ளார்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">السَّلَامُ</span><br />\r\n<br />\r\n(அஸ்-ஸலாம்,) அதாவது, அவனது பரிபூரண பண்புகளையும் செயல்களையும் குறைக்கும் எந்தவொரு குறைபாடுகளிலிருந்தும் விடுபட்டவன். அல்லாஹ்வின் கூற்று,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الْمُؤْمِنُ</span><br />\r\n<br />\r\n(அல்-முஃமின்,) என்பதற்கு இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அத்-தஹ்ஹாக் அவர்கள் அறிவித்தபடி, \"தனது அடியார்களுக்கு ஒருபோதும் அநீதி இழைக்கமாட்டேன் என்று வாக்குறுதியளித்து அவர்களுக்குப் பாதுகாப்பு வழங்கியவன்\" என்று பொருள். கத்தாதா அவர்கள் \"அல்லாஹ் தனது கூற்றுகள் உண்மை என உறுதிப்படுத்துகிறான்\" என்று பொருள் கூறினார். இப்னு ஸைத் அவர்கள், \"அவன் மீது நம்பிக்கை கொண்ட தனது உண்மையுள்ள அடியார்களின் நம்பிக்கையை அவன் அங்கீகரித்தான்\" என்று பொருள் கூறினார். அல்லாஹ்வின் கூற்று,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الْمُهَيْمِنُ</span><br />\r\n<br />\r\n(அல்-முஹைமின்,) என்பதற்கு இப்னு அப்பாஸ் (ரழி) மற்றும் பிற அறிஞர்கள், \"அடியார்களின் செயல்களைக் கண்காணிக்கும் சாட்சியாளன்\" என்று பொருள் கூறியுள்ளனர். அல்லாஹ் இதே போன்ற ஆயத்துகளில் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">شَهِيدٌ</span><br />\r\n<br />\r\n(மேலும் அல்லாஹ் எல்லாப் பொருட்களுக்கும் சாட்சியாளனாக இருக்கிறான்.) (<a href=\"qurandisp.php?sura=58&ayah=6\" class=\"link\">58:6</a>),<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">شَهِيدٌ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَفْعَلُونَ</span><br />\r\n<br />\r\n(மேலும், அவர்கள் செய்து கொண்டிருந்தவற்றிற்கு அல்லாஹ் சாட்சியாளனாக இருக்கிறான்.) (<a href=\"qurandisp.php?sura=10&ayah=46\" class=\"link\">10:46</a>), மற்றும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَفَمَنْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">قَآئِمٌ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">نَفْسٍ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">كَسَبَتْ</span><br />\r\n<br />\r\n(ஒவ்வொரு ஆத்மாவும் சம்பாதித்ததை (அல்லாஹ்) கண்காணித்துக் கொண்டிருக்கவில்லையா?) (<a href=\"qurandisp.php?sura=13&ayah=33\" class=\"link\">13:33</a>) அல்லாஹ் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الْعَزِيزُ</span><br />\r\n<br />\r\n(அல்-அஸீஸ்,) அதாவது \"அவன் வல்லமை மிக்கவன், அனைத்தையும் மிகைத்தவன்.\" எனவே, அவனது வலிமை, மகத்துவம், தடுக்க முடியாத சக்தி மற்றும் பெருமை காரணமாக அவனது மாட்சிமை ஒருபோதும் மீறப்படுவதில்லை. அல்லாஹ் கூறினான்;<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الْجَبَّارُ</span> <span class=\"quran-arabic-font text-success\">الْمُتَكَبِّرُ</span><br />\r\n<br />\r\n(அல்-ஜப்பார், அல்-முதகப்பிர்), அதாவது \"அடக்கி ஆள்பவனாகவும் பெருமைக்குரியவனாகவும் இருப்பதற்குத் தகுதியானவன் அவன் ஒருவனே.\" ஸஹீஹ் ஹதீஸ் தொகுப்பில் ஒரு ஹதீஸ் இடம்பெற்றுள்ளது, அதில் அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">الْعَظَمَةُ</span> <span class=\"quran-arabic-font text-success\">إِزَارِي،</span> <span class=\"quran-arabic-font text-success\">وَالْكِبْرِيَاءُ</span> <span class=\"quran-arabic-font text-success\">رِدَائِي،</span> <span class=\"quran-arabic-font text-success\">فَمَنْ</span> <span class=\"quran-arabic-font text-success\">نَازَعَنِي</span> <span class=\"quran-arabic-font text-success\">وَاحِدًا</span> <span class=\"quran-arabic-font text-success\">مِنْهُمَا</span> <span class=\"quran-arabic-font text-success\">عَذَّبْتُه</span>»<br />\r\n<br />\r\n(வல்லமை எனது இஜார் (கீழாடை), பெருமை எனது ரிதா (மேலாடை); எவரேனும் இவற்றில் ஒன்றில் என்னுடன் போட்டியிட்டால், நான் அவரைத் தண்டிப்பேன்.) மேன்மைமிக்க அல்லாஹ் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سُبْحَانَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">عَمَّا</span> <span class=\"quran-arabic-font text-success\">يُشْرِكُونَ</span><br />\r\n<br />\r\n(அல்லாஹ் தூயவன்! அவர்கள் இணை வைப்பவற்றை விட்டும் அவன் உயர்ந்தவன்.), பிறகு அவன் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">الْخَالِقُ</span> <span class=\"quran-arabic-font text-success\">الْبَارِئُ</span> <span class=\"quran-arabic-font text-success\">الْمُصَوِّرُ</span><br />\r\n<br />\r\n(அவனே அல்லாஹ், அல்-காலிக், அல்-பாரிஃ, அல்-முஸவ்விர்.) அல்-காலிக் என்பது திட்டமிட்டு அளவிடுவதையும் விகிதாச்சாரப்படுத்துவதையும் குறிக்கிறது. அல்-பாரிஃ என்பது தான் திட்டமிட்டு அளவிட்டதை உருவாக்கி இருப்புக்குக் கொண்டு வருவதைக் குறிக்கிறது. நிச்சயமாக, அல்லாஹ்வைத் தவிர வேறு எவராலும் எதையும் அளவிடவோ, வெளிக்கொணரவோ, படைக்கவோ முடியாது. அல்லாஹ்வின் கூற்று,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الْخَالِقُ</span> <span class=\"quran-arabic-font text-success\">الْبَارِئُ</span> <span class=\"quran-arabic-font text-success\">الْمُصَوِّرُ</span><br />\r\n<br />\r\n(அல்-காலிக், அல்-பாரிஃ, அல்-முஸவ்விர்.) என்பதன் பொருள், அல்லாஹ் ஒரு பொருளை நாடினால், அதனிடம் \"ஆகு\" என்று கூறுகிறான், உடனே அது அவன் நாடிய வடிவத்திலும், அவன் தேர்ந்தெடுத்த உருவத்திலும் இருப்புக்கு வருகிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">أَيِّ</span> <span class=\"quran-arabic-font text-success\">صُورَةٍ</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">شَاءَ</span> <span class=\"quran-arabic-font text-success\">رَكَّبَكَ</span><br />\r\n<br />\r\n(அவன் நாடிய எந்த வடிவத்திலும் உன்னை அவன் ஒன்று சேர்த்தான்.) (<a href=\"qurandisp.php?sura=82&ayah=8\" class=\"link\">82:8</a>) அல்லாஹ் தன்னை அல்-முஸவ்விர் என்று விவரிக்கிறான்; அவன் நாடும் எதையும், தான் தீர்மானிக்கும் உருவத்திலும் வடிவத்திலும் இருப்புக்குக் கொண்டு வருபவன்.<br />\r\n<br />\r\n<strong>அல்-அஸ்மாஉல் ஹுஸ்னா</strong><br />\r\n<br />\r\nமேன்மைமிக்க அல்லாஹ் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">الْأَسْمَاءُ</span> <span class=\"quran-arabic-font text-success\">الْحُسْنَى</span><br />\r\n<br />\r\n(அவனுக்கே மிக அழகிய திருநாமங்கள் (அல்-அஸ்மாஉல் ஹுஸ்னா) உரியன.) இந்த ஆயத்தின் பொருளை ஸூரா அல்-அஃராஃபின் தஃப்ஸீரில் நாம் விளக்கியுள்ளோம். அபூ ஹுரைரா (ரழி) அவர்கள் அறிவித்ததாக இரண்டு ஸஹீஹ் நூல்களிலும் பதிவு செய்யப்பட்டுள்ளது, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">للهِ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span> <span class=\"quran-arabic-font text-success\">تِسْعَةً</span> <span class=\"quran-arabic-font text-success\">وَتِسْعِينَ</span> <span class=\"quran-arabic-font text-success\">اسْمًا،</span> <span class=\"quran-arabic-font text-success\">مِائَةً</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">وَاحِدًا،</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">أَحْصَاهَا</span> <span class=\"quran-arabic-font text-success\">دَخَلَ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةَ،</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">وِتْرٌ</span> <span class=\"quran-arabic-font text-success\">يُحِبُّ</span> <span class=\"quran-arabic-font text-success\">الْوِتْر</span>»<br />\r\n<br />\r\n(மேன்மைமிக்க அல்லாஹ்வுக்குத் தொண்ணூற்று ஒன்பது திருநாமங்கள் -நூற்றுக்கு ஒன்று குறைவு- உள்ளன. அவற்றை யார் (மனப்பாடம் செய்து) பேணுகிறாரோ அவர் சொர்க்கத்தில் நுழைவார். அல்லாஹ் ஒற்றையானவன் (வித்ர்), அவன் ஒற்றைப் படையையே விரும்புகிறான்.)<br />\r\n<br />\r\n<strong>எல்லாமே அல்லாஹ்வைத் துதிக்கின்றன</strong><br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்று,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يُسَبِّحُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضِ</span><br />\r\n<br />\r\n(வானங்களிலும் பூமியிலும் உள்ளவை அனைத்தும் அவனைத் துதிக்கின்றன.) என்பது அவனது மற்றொரு கூற்றைப் போன்றது,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">تُسَبِّحُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتُ</span> <span class=\"quran-arabic-font text-success\">السَّبْعُ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضُ</span> <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">فِيهِنَّ</span> <span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">يُسَبِّحُ</span> <span class=\"quran-arabic-font text-success\">بِحَمْدَهِ</span> <span class=\"quran-arabic-font text-success\">وَلَكِن</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">تَفْقَهُونَ</span> <span class=\"quran-arabic-font text-success\">تَسْبِيحَهُمْ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">حَلِيمًا</span> <span class=\"quran-arabic-font text-success\">غَفُورًا</span><br />\r\n<br />\r\n(ஏழு வானங்களும், பூமியும், அவற்றில் உள்ள அனைத்தும் அவனைத் துதிக்கின்றன. மேலும், அவனது புகழைத் துதிக்காத பொருள் எதுவுமில்லை. ஆனால், அவற்றின் துதித்தலை நீங்கள் புரிந்து கொள்வதில்லை. நிச்சயமாக, அவன் மிகவும் சகிப்புத்தன்மை உடையவனாகவும், மிக்க மன்னிப்பவனாகவும் இருக்கிறான்.) (<a href=\"qurandisp.php?sura=17&ayah=44\" class=\"link\">17:44</a>) அல்லாஹ்வின் கூற்று,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الْعَزِيزُ</span><br />\r\n<br />\r\n(மேலும் அவன் அல்-அஸீஸ்) அவன் வல்லமை மிக்கவன், அதாவது, அவனது மாட்சிமை ஒருபோதும் தாழ்த்தப்படுவதில்லை,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الْحَكِيمُ</span><br />\r\n<br />\r\n(அல்-ஹகீம்) அவன் தனது சட்டங்களிலும் தீர்மானங்களிலும் ஞானமிக்கவன்.<br />\r\n<br />\r\nஇமாம் அஹ்மத் (ரஹ்) அவர்கள் பதிவு செய்துள்ளார்கள்: மக்கில் பின் யசார் (ரழி) அவர்கள் அறிவிக்கிறார்கள், நபி (ஸல்) அவர்கள் கூறினார்கள்: \"எவர் காலையில் (தூக்கத்திலிருந்து) எழுந்ததும் மூன்று முறை 'அவூது பில்லாஹிஸ் ஸமீஇல் அலீம் மினஷ் ஷைத்தானிர் ரஜீம்' (விரட்டப்பட்ட ஷைத்தானிடமிருந்து, அனைத்தையும் செவியேற்பவனும் நன்கறிபவனுமாகிய அல்லாஹ்விடம் நான் பாதுகாப்புத் தேடுகிறேன்) என்று கூறிவிட்டு, ஸூரா அல்-ஹஷ்ரின் இறுதி மூன்று ஆயத்துகளை ஓதுகின்றாரோ, அவருக்காக மாலை நேரம் வரும் வரை பிரார்த்தனை செய்வதற்காக அல்லாஹ் எழுபதாயிரம் வானவர்களை நியமிக்கிறான். மேலும், அந்த நாளில் அவர் இறந்துவிட்டால், அவர் ஒரு ஷஹீதாக (உயிர் தியாகியாக) இறக்கிறார். எவர் மாலை நேரத்தில் இதனை ஓதுகின்றாரோ, அவரும் இதே நிலையில் இருப்பார் (காலை வரை).\"<br />\r\n<br />\r\nஇத்துடன் ஸூரா அல்-ஹஷ்ரின் தஃப்ஸீர் நிறைவுபெற்றது. எல்லாப் புகழும் அல்லாஹ்வுக்கே.<br />\r\n<br />\r\n<br />\r\n<br />","text":"குர்ஆனின் மகத்துவத்தை உறுதிப்படுத்துதல்\n\r\n\n\r\nமேன்மைமிக்க அல்லாஹ் குர்ஆனின் மகத்துவத்தையும், அதன் உயர்ந்த அந்தஸ்தையும், அதைக் கேட்கும்போது உள்ளங்கள் பணிந்து பிளந்து போவதற்கும் அது தகுதியானது என்பதையும் வலியுறுத்துகிறான். ஏனெனில், அதில் உண்மையான வாக்குறுதிகளும் உறுதியான எச்சரிக்கைகளும் இடம் பெற்றுள்ளன.\n\r\n\n\r\nلَوْ أَنزَلْنَا هَذَا الْقُرْآنَ عَلَى جَبَلٍ لَّرَأَيْتَهُ خَاشِعًا مُّتَصَدِّعًا مِّنْ خَشْيَةِ اللَّهِ\n\r\n\n\r\n(நாம் இந்த குர்ஆனை ஒரு மலையின் மீது இறக்கியிருந்தால், அது அல்லாஹ்வின் பயத்தால் பணிந்து பிளந்து போவதை நீர் நிச்சயமாகக் கண்டிருப்பீர்.) கடினமான மற்றும் பிரம்மாண்டமான ஒரு மலையே, இந்த குர்ஆனை விளங்கிக்கொள்ளும் திறன் அதற்கு வழங்கப்பட்டால், மேன்மைமிக்க அல்லாஹ்வின் மீதான அச்சத்தால் பணிந்து நொறுங்கிவிடும் என்றால், மனிதர்களே! உங்களைப் பற்றி என்ன நினைக்கிறீர்கள்? அல்லாஹ்வின் கட்டளைகளையும் அவனது வேதத்தையும் நீங்கள் விளங்கிக்கொண்டும், உங்கள் உள்ளங்கள் ஏன் அல்லாஹ்வின் பயத்தால் மென்மையாகவும் பணிவாகவும் மாறுவதில்லை? இதனால்தான் அல்லாஹ் கூறினான்,\n\r\n\n\r\nوَتِلْكَ الْأَمْثَالُ نَضْرِبُهَا لِلنَّاسِ لَعَلَّهُمْ يَتَفَكَّرُونَ\n\r\n\n\r\n(மனிதர்கள் சிந்திப்பதற்காக இத்தகைய உவமைகளை நாம் கூறுகிறோம்.) அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தமக்காக ஒரு மின்பரை (உரை மேடை) செய்யச் சொன்னார்கள் என்று ஒரு 'முதவாதிர்' தரத்திலான ஹதீஸில் கூறப்பட்டுள்ளது. அதற்கு முன்பு, அவர்கள் மஸ்ஜிதில் ஒரு மரக்கட்டையின் அருகே நின்று உரை நிகழ்த்தி வந்தார்கள். மின்பர் செய்யப்பட்டு மஸ்ஜிதில் வைக்கப்பட்டபோது, நபி (ஸல்) அவர்கள் உரை நிகழ்த்தச் செல்வதற்காக அந்த மரக்கட்டையைக் கடந்து மின்பரை நோக்கிச் சென்றார்கள்; அப்போது அந்த மரக்கட்டை ஒரு கைக்குழந்தையைப் போல அழத் தொடங்கியது. தன் அருகில் ஓதப்பட்டு வந்த அல்லாஹ்வின் நினைவூட்டல்களையும் வஹீ (இறைச்செய்தி)யையும் கேட்க முடியவில்லையே என்று அந்த மரக்கட்டை ஏங்கியது. இந்த ஹதீஸை அறிவித்த பிறகு அல்-ஹஸன் அல்-பஸரி அவர்கள் கூறினார்கள்: \"மனிதர்களே! அந்த மரக்கட்டையை விட அல்லாஹ்வின் தூதர் (ஸல்) அவர்களைப் பிரிந்து ஏங்குவதற்கு நீங்கள் தான் அதிக தகுதியுடையவர்கள்!\" அதேபோன்று, இந்த கண்ணியமிக்க ஆயத் இவ்வாறு வினவுகிறது: திடமான மலைகளே அல்லாஹ்வின் பேச்சைக் கேட்டு, அதை விளங்கிக்கொண்டால், அல்லாஹ்வின் பயத்தால் பணிந்து பிளந்துவிடுகின்றன என்றால், குர்ஆனைக் கேட்டு, அதை விளங்கிக்கொண்ட மனிதர்களான உங்களின் நிலை என்ன? மேன்மைமிக்க அல்லாஹ் மற்றொரு ஆயத்தில் கூறினான்,\n\r\n\n\r\nوَلَوْ أَنَّ قُرْآنًا سُيِّرَتْ بِهِ الْجِبَالُ أَوْ قُطِّعَتْ بِهِ الْأَرْضُ أَوْ كُلِّمَ بِهِ الْمَوْتَى\n\r\n\n\r\n(மேலும், ஒரு குர்ஆன் இருந்திருந்தால், அதன் மூலம் மலைகள் நகர்த்தப்பட்டிருக்கும், அல்லது பூமி பிளக்கப்பட்டிருக்கும், அல்லது இறந்தவர்கள் பேச வைக்கப்பட்டிருப்பார்கள்.) (13:31). இத்தகைய சிறப்புகளைக் கொண்ட ஒரு குர்ஆன் இருந்திருந்தால், அது இந்த குர்ஆனாகத்தான் இருந்திருக்கும் என்பதே இந்த ஆயத்தின் பொருளாகும் என்று நாம் குறிப்பிட்டுள்ளோம். மேன்மைமிக்க அல்லாஹ் மற்றொரு ஆயத்தில் கூறினான்,\n\r\n\n\r\nوَإِنَّ مِنَ الْحِجَارَةِ لَمَا يَتَفَجَّرُ مِنْهُ الْأَنْهَارُ وَإِنَّ مِنْهَا لَمَا يَشَّقَّقُ فَيَخْرُجُ مِنْهُ الْمَاءُ وَإِنَّ مِنْهَا لَمَا يَهْبِطُ مِنْ خَشْيَةِ اللَّهِ\n\r\n\n\r\n(நிச்சயமாக, கற்களில் சிலவற்றிலிருந்து ஆறுகள் பீறிட்டு ஓடுகின்றன; நிச்சயமாக, அவற்றில் சில பிளந்து, அவற்றிலிருந்து தண்ணீர் வெளிப்படுகிறது; நிச்சயமாக, அவற்றில் சில அல்லாஹ்வின் பயத்தால் கீழே விழுகின்றன.) (2:74)\n\r\n\n\r\nஅவனது திருநாமங்களையும் பண்புகளையும் குறிப்பிடுவதன் மூலம் மேன்மைமிக்க அல்லாஹ்வைத் துதித்தல்\n\r\n\n\r\nமேன்மைமிக்க அல்லாஹ் கூறினான்,\n\r\n\n\r\nهُوَ اللَّهُ الَّذِي لاَ إِلَهَ إِلاَّ هُوَ عَالِمُ الْغَيْبِ وَالشَّهَادَةِ هُوَ الرَّحْمَنُ الرَّحِيمُ\n\r\n\n\r\n(அவனே அல்லாஹ், அவனைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை (லா இலாஹ இல்லா ஹுவ), மறைவானவற்றையும் வெளிப்படையானவற்றையும் நன்கறிந்தவன். அவன் அளவற்ற அருளாளன், நிகரற்ற அன்புடையோன்.) வணக்கத்திற்குரியவன் அவன் ஒருவனே என்று அல்லாஹ் கூறுகிறான். அகிலத்தைப் படைத்து பரிபாலிக்கும் இறைவன் அல்லது கடவுள் அவனைத் தவிர வேறு யாருமில்லை. அல்லாஹ்வையன்றி வணங்கப்படுபவை அனைத்தும் போலியான தெய்வங்களே. அல்லாஹ் மறைவானவற்றையும் வெளிப்படையானவற்றையும் நன்கறிந்தவன்; நாம் காணும் படைப்பினங்கள் மற்றும் காணமுடியாத படைப்பினங்கள் தொடர்பான அனைத்தையும் அவன் அறிவான். வானத்திலோ பூமியிலோ உள்ள எதுவும் அவனது அறிவிலிருந்து தப்புவதில்லை; அது எவ்வளவு பெரியதாக இருந்தாலும் அல்லது அற்பமானதாக இருந்தாலும், இருளில் உள்ள எறும்புகள் உட்பட அனைத்தையும் அவன் அறிகிறான். அல்லாஹ்வின் கூற்று,\n\r\n\n\r\nهُوَ الرَّحْمَنُ الرَّحِيمُ\n\r\n\n\r\n(அவன் அளவற்ற அருளாளன், நிகரற்ற அன்புடையோன்.) இந்த தஃப்ஸீரின் ஆரம்பத்திலேயே இது பற்றி விரிவாக விளக்கப்பட்டுள்ளது, எனவே அதை மீண்டும் இங்கே விளக்குவது அவசியமில்லை. மேலும், அல்லாஹ் தனது படைப்புகள் அனைத்தையும் உள்ளடக்கிய பரந்த கருணையின் உரிமையாளன் என்பதை இது உறுதிப்படுத்துகிறது. அவன் இம்மையிலும் மறுமையிலும் அர்-ரஹ்மான் மற்றும் அர்-ரஹீம் ஆக இருக்கிறான். மேன்மைமிக்க அல்லாஹ் மற்ற ஆயத்துகளில் கூறினான்,\n\r\n\n\r\nوَرَحْمَتِي وَسِعَتْ كُلَّ شَيْءٍ\n\r\n\n\r\n(என் கருணை எல்லாப் பொருட்களையும் சூழ்ந்துள்ளது.) (7:156),\n\r\n\n\r\nكَتَبَ رَبُّكُمْ عَلَى نَفْسِهِ الرَّحْمَةَ\n\r\n\n\r\n(உங்கள் இறைவன் தன் மீது கருணையை விதித்துக் கொண்டான்.) (6:54), மற்றும்,\n\r\n\n\r\nقُلْ بِفَضْلِ اللَّهِ وَبِرَحْمَتِهِ فَبِذَلِكَ فَلْيَفْرَحُواْ هُوَ خَيْرٌ مِّمَّا يَجْمَعُونَ\n\r\n\n\r\n(கூறுவீராக: \"அல்லாஹ்வின் அருட்கொடையிலும் அவனது கருணையிலும் - அதிலேயே அவர்கள் மகிழ்ச்சியடையட்டும்.\" அது அவர்கள் சேகரித்து வைக்கும் (செல்வத்தை) விடச் சிறந்தது.) (10:58) மேன்மைமிக்க அல்லாஹ் கூறினான்,\n\r\n\n\r\nهُوَ اللَّهُ الَّذِي لاَ إِلَهَ إِلاَّ هُوَ الْمَلِكُ\n\r\n\n\r\n(அவனே அல்லாஹ், அவனைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை (லா இலாஹ இல்லா ஹுவ), அல்-மாலிக்.) அல்-மாலிக் என்றால் \"அனைத்துப் பொருட்களின் உரிமையாளன் மற்றும் அரசன்\" என்று பொருள். எவ்வித எதிர்ப்போ தடையோ இன்றி அவற்றின் மீது முழு அதிகாரம் கொண்டவன். அல்லாஹ்வின் கூற்று,\n\r\n\n\r\nالْقُدُّوسُ\n\r\n\n\r\n(அல்-குத்தூஸ்,) என்பதற்கு வஹ்ப் பின் முனப்பிஹ் அவர்கள் \"பரிசுத்தமானவன்\" என்று பொருள் கூறியுள்ளார். முஜாஹித் மற்றும் கத்தாதா ஆகியோர் \"பாக்கியம் மிக்கவன்\" என்று பொருள் கூறியுள்ளனர். இப்னு ஜுரைஜ் அவர்கள் \"கண்ணியமிக்க வானவர்கள் எவனைத் துதிக்கிறார்களோ அவன்\" என்று பொருள் கூறியுள்ளார்.\n\r\n\n\r\nالسَّلَامُ\n\r\n\n\r\n(அஸ்-ஸலாம்,) அதாவது, அவனது பரிபூரண பண்புகளையும் செயல்களையும் குறைக்கும் எந்தவொரு குறைபாடுகளிலிருந்தும் விடுபட்டவன். அல்லாஹ்வின் கூற்று,\n\r\n\n\r\nالْمُؤْمِنُ\n\r\n\n\r\n(அல்-முஃமின்,) என்பதற்கு இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அத்-தஹ்ஹாக் அவர்கள் அறிவித்தபடி, \"தனது அடியார்களுக்கு ஒருபோதும் அநீதி இழைக்கமாட்டேன் என்று வாக்குறுதியளித்து அவர்களுக்குப் பாதுகாப்பு வழங்கியவன்\" என்று பொருள். கத்தாதா அவர்கள் \"அல்லாஹ் தனது கூற்றுகள் உண்மை என உறுதிப்படுத்துகிறான்\" என்று பொருள் கூறினார். இப்னு ஸைத் அவர்கள், \"அவன் மீது நம்பிக்கை கொண்ட தனது உண்மையுள்ள அடியார்களின் நம்பிக்கையை அவன் அங்கீகரித்தான்\" என்று பொருள் கூறினார். அல்லாஹ்வின் கூற்று,\n\r\n\n\r\nالْمُهَيْمِنُ\n\r\n\n\r\n(அல்-முஹைமின்,) என்பதற்கு இப்னு அப்பாஸ் (ரழி) மற்றும் பிற அறிஞர்கள், \"அடியார்களின் செயல்களைக் கண்காணிக்கும் சாட்சியாளன்\" என்று பொருள் கூறியுள்ளனர். அல்லாஹ் இதே போன்ற ஆயத்துகளில் கூறினான்,\n\r\n\n\r\nوَاللَّهُ عَلَى كُلِّ شَيْءٍ شَهِيدٌ\n\r\n\n\r\n(மேலும் அல்லாஹ் எல்லாப் பொருட்களுக்கும் சாட்சியாளனாக இருக்கிறான்.) (58:6),\n\r\n\n\r\nثُمَّ اللَّهُ شَهِيدٌ عَلَى مَا يَفْعَلُونَ\n\r\n\n\r\n(மேலும், அவர்கள் செய்து கொண்டிருந்தவற்றிற்கு அல்லாஹ் சாட்சியாளனாக இருக்கிறான்.) (10:46), மற்றும்,\n\r\n\n\r\nأَفَمَنْ هُوَ قَآئِمٌ عَلَى كُلِّ نَفْسٍ بِمَا كَسَبَتْ\n\r\n\n\r\n(ஒவ்வொரு ஆத்மாவும் சம்பாதித்ததை (அல்லாஹ்) கண்காணித்துக் கொண்டிருக்கவில்லையா?) (13:33) அல்லாஹ் கூறினான்,\n\r\n\n\r\nالْعَزِيزُ\n\r\n\n\r\n(அல்-அஸீஸ்,) அதாவது \"அவன் வல்லமை மிக்கவன், அனைத்தையும் மிகைத்தவன்.\" எனவே, அவனது வலிமை, மகத்துவம், தடுக்க முடியாத சக்தி மற்றும் பெருமை காரணமாக அவனது மாட்சிமை ஒருபோதும் மீறப்படுவதில்லை. அல்லாஹ் கூறினான்;\n\r\n\n\r\nالْجَبَّارُ الْمُتَكَبِّرُ\n\r\n\n\r\n(அல்-ஜப்பார், அல்-முதகப்பிர்), அதாவது \"அடக்கி ஆள்பவனாகவும் பெருமைக்குரியவனாகவும் இருப்பதற்குத் தகுதியானவன் அவன் ஒருவனே.\" ஸஹீஹ் ஹதீஸ் தொகுப்பில் ஒரு ஹதீஸ் இடம்பெற்றுள்ளது, அதில் அல்லாஹ் கூறினான்:\n\r\n\n\r\n«الْعَظَمَةُ إِزَارِي، وَالْكِبْرِيَاءُ رِدَائِي، فَمَنْ نَازَعَنِي وَاحِدًا مِنْهُمَا عَذَّبْتُه»\n\r\n\n\r\n(வல்லமை எனது இஜார் (கீழாடை), பெருமை எனது ரிதா (மேலாடை); எவரேனும் இவற்றில் ஒன்றில் என்னுடன் போட்டியிட்டால், நான் அவரைத் தண்டிப்பேன்.) மேன்மைமிக்க அல்லாஹ் கூறினான்,\n\r\n\n\r\nسُبْحَانَ اللَّهِ عَمَّا يُشْرِكُونَ\n\r\n\n\r\n(அல்லாஹ் தூயவன்! அவர்கள் இணை வைப்பவற்றை விட்டும் அவன் உயர்ந்தவன்.), பிறகு அவன் கூறினான்,\n\r\n\n\r\nهُوَ اللَّهُ الْخَالِقُ الْبَارِئُ الْمُصَوِّرُ\n\r\n\n\r\n(அவனே அல்லாஹ், அல்-காலிக், அல்-பாரிஃ, அல்-முஸவ்விர்.) அல்-காலிக் என்பது திட்டமிட்டு அளவிடுவதையும் விகிதாச்சாரப்படுத்துவதையும் குறிக்கிறது. அல்-பாரிஃ என்பது தான் திட்டமிட்டு அளவிட்டதை உருவாக்கி இருப்புக்குக் கொண்டு வருவதைக் குறிக்கிறது. நிச்சயமாக, அல்லாஹ்வைத் தவிர வேறு எவராலும் எதையும் அளவிடவோ, வெளிக்கொணரவோ, படைக்கவோ முடியாது. அல்லாஹ்வின் கூற்று,\n\r\n\n\r\nالْخَالِقُ الْبَارِئُ الْمُصَوِّرُ\n\r\n\n\r\n(அல்-காலிக், அல்-பாரிஃ, அல்-முஸவ்விர்.) என்பதன் பொருள், அல்லாஹ் ஒரு பொருளை நாடினால், அதனிடம் \"ஆகு\" என்று கூறுகிறான், உடனே அது அவன் நாடிய வடிவத்திலும், அவன் தேர்ந்தெடுத்த உருவத்திலும் இருப்புக்கு வருகிறது.\n\r\n\n\r\nفِي أَيِّ صُورَةٍ مَّا شَاءَ رَكَّبَكَ\n\r\n\n\r\n(அவன் நாடிய எந்த வடிவத்திலும் உன்னை அவன் ஒன்று சேர்த்தான்.) (82:8) அல்லாஹ் தன்னை அல்-முஸவ்விர் என்று விவரிக்கிறான்; அவன் நாடும் எதையும், தான் தீர்மானிக்கும் உருவத்திலும் வடிவத்திலும் இருப்புக்குக் கொண்டு வருபவன்.\n\r\n\n\r\nஅல்-அஸ்மாஉல் ஹுஸ்னா\n\r\n\n\r\nமேன்மைமிக்க அல்லாஹ் கூறினான்,\n\r\n\n\r\nلَهُ الْأَسْمَاءُ الْحُسْنَى\n\r\n\n\r\n(அவனுக்கே மிக அழகிய திருநாமங்கள் (அல்-அஸ்மாஉல் ஹுஸ்னா) உரியன.) இந்த ஆயத்தின் பொருளை ஸூரா அல்-அஃராஃபின் தஃப்ஸீரில் நாம் விளக்கியுள்ளோம். அபூ ஹுரைரா (ரழி) அவர்கள் அறிவித்ததாக இரண்டு ஸஹீஹ் நூல்களிலும் பதிவு செய்யப்பட்டுள்ளது, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்,\n\r\n\n\r\n«إِنَّ للهِ تَعَالَى تِسْعَةً وَتِسْعِينَ اسْمًا، مِائَةً إِلَّا وَاحِدًا، مَنْ أَحْصَاهَا دَخَلَ الْجَنَّةَ، وَهُوَ وِتْرٌ يُحِبُّ الْوِتْر»\n\r\n\n\r\n(மேன்மைமிக்க அல்லாஹ்வுக்குத் தொண்ணூற்று ஒன்பது திருநாமங்கள் -நூற்றுக்கு ஒன்று குறைவு- உள்ளன. அவற்றை யார் (மனப்பாடம் செய்து) பேணுகிறாரோ அவர் சொர்க்கத்தில் நுழைவார். அல்லாஹ் ஒற்றையானவன் (வித்ர்), அவன் ஒற்றைப் படையையே விரும்புகிறான்.)\n\r\n\n\r\nஎல்லாமே அல்லாஹ்வைத் துதிக்கின்றன\n\r\n\n\r\nஅல்லாஹ்வின் கூற்று,\n\r\n\n\r\nيُسَبِّحُ لَهُ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ\n\r\n\n\r\n(வானங்களிலும் பூமியிலும் உள்ளவை அனைத்தும் அவனைத் துதிக்கின்றன.) என்பது அவனது மற்றொரு கூற்றைப் போன்றது,\n\r\n\n\r\nتُسَبِّحُ لَهُ السَّمَاوَاتُ السَّبْعُ وَالْأَرْضُ وَمَن فِيهِنَّ وَإِن مِّن شَيْءٍ إِلاَّ يُسَبِّحُ بِحَمْدَهِ وَلَكِن لاَّ تَفْقَهُونَ تَسْبِيحَهُمْ إِنَّهُ كَانَ حَلِيمًا غَفُورًا\n\r\n\n\r\n(ஏழு வானங்களும், பூமியும், அவற்றில் உள்ள அனைத்தும் அவனைத் துதிக்கின்றன. மேலும், அவனது புகழைத் துதிக்காத பொருள் எதுவுமில்லை. ஆனால், அவற்றின் துதித்தலை நீங்கள் புரிந்து கொள்வதில்லை. நிச்சயமாக, அவன் மிகவும் சகிப்புத்தன்மை உடையவனாகவும், மிக்க மன்னிப்பவனாகவும் இருக்கிறான்.) (17:44) அல்லாஹ்வின் கூற்று,\n\r\n\n\r\nوَهُوَ الْعَزِيزُ\n\r\n\n\r\n(மேலும் அவன் அல்-அஸீஸ்) அவன் வல்லமை மிக்கவன், அதாவது, அவனது மாட்சிமை ஒருபோதும் தாழ்த்தப்படுவதில்லை,\n\r\n\n\r\nالْحَكِيمُ\n\r\n\n\r\n(அல்-ஹகீம்) அவன் தனது சட்டங்களிலும் தீர்மானங்களிலும் ஞானமிக்கவன்.\n\r\n\n\r\nஇமாம் அஹ்மத் (ரஹ்) அவர்கள் பதிவு செய்துள்ளார்கள்: மக்கில் பின் யசார் (ரழி) அவர்கள் அறிவிக்கிறார்கள், நபி (ஸல்) அவர்கள் கூறினார்கள்: \"எவர் காலையில் (தூக்கத்திலிருந்து) எழுந்ததும் மூன்று முறை 'அவூது பில்லாஹிஸ் ஸமீஇல் அலீம் மினஷ் ஷைத்தானிர் ரஜீம்' (விரட்டப்பட்ட ஷைத்தானிடமிருந்து, அனைத்தையும் செவியேற்பவனும் நன்கறிபவனுமாகிய அல்லாஹ்விடம் நான் பாதுகாப்புத் தேடுகிறேன்) என்று கூறிவிட்டு, ஸூரா அல்-ஹஷ்ரின் இறுதி மூன்று ஆயத்துகளை ஓதுகின்றாரோ, அவருக்காக மாலை நேரம் வரும் வரை பிரார்த்தனை செய்வதற்காக அல்லாஹ் எழுபதாயிரம் வானவர்களை நியமிக்கிறான். மேலும், அந்த நாளில் அவர் இறந்துவிட்டால், அவர் ஒரு ஷஹீதாக (உயிர் தியாகியாக) இறக்கிறார். எவர் மாலை நேரத்தில் இதனை ஓதுகின்றாரோ, அவரும் இதே நிலையில் இருப்பார் (காலை வரை).\"\n\r\n\n\r\nஇத்துடன் ஸூரா அல்-ஹஷ்ரின் தஃப்ஸீர் நிறைவுபெற்றது. எல்லாப் புகழும் அல்லாஹ்வுக்கே."}}};})(self);
